function refundAddCompany(){
  const sel=document.getElementById('refundCompanySelect');
  const name=sel.value;
  if(!name)return;
  if(_refundSelected.length>=10){alert('Maximum 10 companies per email. Remove one to add another.');return;}
  if(_refundSelected.includes(name)){alert(name+' is already added.');return;}
  _refundSelected.push(name);
  sel.value='';
  refundRenderSelected();
}
function refundRemoveCompany(name){
  _refundSelected=_refundSelected.filter(n=>n!==name);
  refundRenderSelected();
}
function refundRenderSelected(){
  const list=document.getElementById('refundSelectedList');
  const note=document.getElementById('refundCountNote');
  const btn=document.getElementById('refundGenerateBtn');
  if(!list)return;
  if(!_refundSelected.length){
    list.innerHTML='';
    note.textContent='No companies selected yet.';
    btn.style.opacity='.45';btn.style.pointerEvents='none';
    return;
  }
  list.innerHTML=_refundSelected.map((n,i)=>`
    <div style="display:flex;align-items:center;justify-content:space-between;background:#f4f2ed;border-radius:8px;padding:7px 10px;font-size:12px;font-weight:600;color:#0d1f3c;">
      <span>${i+1}. ${n}${FSP_REFUND_EMAILS[n]?'':' <span style="color:#9ca3af;font-weight:400;">(no email on file)</span>'}</span>
      <button onclick="refundRemoveCompany('${n.replace(/'/g,"\\'")}')" style="background:none;border:none;color:#9ca3af;cursor:pointer;font-size:14px;padding:0 0 0 8px;">✕</button>
    </div>`).join('');
  const count=_refundSelected.length;
  note.textContent=`${count} compan${count===1?'y':'ies'} selected${count===10?' (maximum reached)':''}.`;
  btn.style.opacity='1';btn.style.pointerEvents='auto';
}
function generateRefundEmail(){
  if(!_refundSelected.length)return;
  const emails=_refundSelected.map(n=>FSP_REFUND_EMAILS[n]).filter(Boolean);
  const noEmail=_refundSelected.filter(n=>!FSP_REFUND_EMAILS[n]);
  if(noEmail.length){
    if(!confirm('No email address on file for: '+noEmail.join(', ')+'. Continue without them?'))return;
  }
  if(!emails.length){alert('No email addresses found for the selected companies.');return;}
  const clientName=(document.getElementById('refundClientName').value.trim())||'[Full Name]';
  const idNumber=(document.getElementById('refundIdNumber').value.trim());
  if(!idNumber){alert('Please enter the client ID number — it is required in the subject line.');return;}
  const advisorName=(document.getElementById('refundAdvisorName').value.trim())||'[Your Name]';
  const dateVal=document.getElementById('refundDate').value;
  const dateStr=dateVal?new Date(dateVal).toLocaleDateString('en-ZA',{day:'2-digit',month:'long',year:'numeric'}):'[Date]';
  saveLoaClient(clientName,idNumber);
  const subject=idNumber+' — Premium Refund Request';
  const body=`Good day,\n\nOn behalf of ${clientName} (ID Number: ${idNumber}), I am hereby requesting a premium refund.\n\nPolicy No: [Policy Number]\nAmount: R[Amount]\n\nKindly process the refund and confirm once the amount has been transferred to the client's account.\n\nKind regards,\n${advisorName}\n${dateStr}`;
  const toAddr=emails.join(',');
  const url='https://mail.google.com/mail/?view=cm&to='+encodeURIComponent(toAddr)+'&su='+encodeURIComponent(subject)+'&body='+encodeURIComponent(body);
  closeRefundBuilder();
  triggerLoaDownload();
  window.open(url,'_blank');
  showLoaReminder();
}
// ── END REFUND EMAIL BUILDER ───────────────────────────────────────────────

