let _schedSelected=[];

function showScheduleEmailBuilder(){
  let overlay=document.getElementById('schedBuilderOverlay');
  if(overlay)overlay.remove();
  _schedSelected=[];
  overlay=document.createElement('div');
  overlay.id='schedBuilderOverlay';
  overlay.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,.5);z-index:9100;display:flex;align-items:center;justify-content:center;';
  overlay.innerHTML=`
    <div id="schedBuilderModal" style="background:#fff;border-radius:16px;padding:22px 20px 18px;width:340px;max-width:94vw;box-shadow:0 8px 32px rgba(0,0,0,.25);max-height:90vh;overflow-y:auto;">
      <h3 style="margin:0 0 4px;font-size:15px;font-weight:700;color:#0d1f3c;text-align:center;">Schedule Email Builder</h3>
      <p style="margin:0 0 12px;font-size:12px;color:#6b7280;text-align:center;">Select up to 10 companies — one email will be generated for all.</p>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:6px;margin-bottom:10px;">
        <div><label style="font-size:10px;font-weight:700;color:#6b7280;text-transform:uppercase;letter-spacing:.5px;display:block;margin-bottom:3px;">Client Full Name</label><input id="schedClientName" placeholder="e.g. Zanele Dlamini" style="width:100%;padding:7px 9px;font-size:12px;border:1px solid #e5e7eb;border-radius:7px;background:#f9f9f9;box-sizing:border-box;"/></div>
        <div><label style="font-size:10px;font-weight:700;color:#6b7280;text-transform:uppercase;letter-spacing:.5px;display:block;margin-bottom:3px;">ID Number</label><input id="schedIdNumber" placeholder="13-digit ID" style="width:100%;padding:7px 9px;font-size:12px;border:1px solid #e5e7eb;border-radius:7px;background:#f9f9f9;box-sizing:border-box;font-family:monospace;"/></div>
        <div><label style="font-size:10px;font-weight:700;color:#6b7280;text-transform:uppercase;letter-spacing:.5px;display:block;margin-bottom:3px;">Advisor Name</label><input id="schedAdvisorName" placeholder="Your name" style="width:100%;padding:7px 9px;font-size:12px;border:1px solid #e5e7eb;border-radius:7px;background:#f9f9f9;box-sizing:border-box;"/></div>
        <div><label style="font-size:10px;font-weight:700;color:#6b7280;text-transform:uppercase;letter-spacing:.5px;display:block;margin-bottom:3px;">Date</label><input id="schedDate" type="date" style="width:100%;padding:7px 9px;font-size:12px;border:1px solid #e5e7eb;border-radius:7px;background:#f9f9f9;box-sizing:border-box;"/></div>
      </div>
      <div style="display:flex;gap:6px;margin-bottom:10px;">
        <select id="schedCompanySelect" style="flex:1;padding:8px 10px;font-size:13px;border:1px solid #e5e7eb;border-radius:8px;background:#f9f9f9;color:#1a1a2e;">
          <option value="">Select company…</option>
          ${INSURER_LIST.filter(n=>n!=='Other').map(n=>`<option value="${n}">${n}</option>`).join('')}
        </select>
        <button onclick="schedAddCompany()" style="padding:8px 14px;background:#0d1f3c;color:#fff;border:none;border-radius:8px;font-size:13px;font-weight:700;cursor:pointer;">Add</button>
      </div>
      <div id="schedSelectedList" style="display:flex;flex-direction:column;gap:6px;min-height:36px;margin-bottom:14px;"></div>
      <div id="schedCountNote" style="font-size:11px;color:#9ca3af;text-align:center;margin-bottom:12px;">No companies selected yet.</div>
      <div style="display:flex;gap:8px;">
        <button onclick="closeSchedBuilder()" style="flex:1;padding:9px;background:#f4f2ed;color:#374151;border:none;border-radius:8px;font-size:13px;font-weight:600;cursor:pointer;">Cancel</button>
        <button id="schedGenerateBtn" onclick="generateScheduleEmail()" style="flex:2;padding:9px;background:#0d1f3c;color:#fff;border:none;border-radius:8px;font-size:13px;font-weight:700;cursor:pointer;opacity:.45;pointer-events:none;">Generate Email</button>
      </div>
    </div>`;
  overlay.addEventListener('click',e=>{if(e.target===overlay)closeSchedBuilder();});
  document.body.appendChild(overlay);
  document.getElementById('schedDate').value=new Date().toISOString().slice(0,10);
  if(currentUser&&currentUser.name)document.getElementById('schedAdvisorName').value=currentUser.name;
  if(_loaClient.name)document.getElementById('schedClientName').value=_loaClient.name;
  if(_loaClient.idNumber)document.getElementById('schedIdNumber').value=_loaClient.idNumber;
}
function closeSchedBuilder(){
  const o=document.getElementById('schedBuilderOverlay');
  if(o)o.remove();
}
function schedAddCompany(){
  const sel=document.getElementById('schedCompanySelect');
  const name=sel.value;
  if(!name)return;
  if(_schedSelected.length>=10){alert('Maximum 10 companies per email. Remove one to add another.');return;}
  if(_schedSelected.includes(name)){alert(name+' is already added.');return;}
  _schedSelected.push(name);
  sel.value='';
  schedRenderSelected();
}
function schedRemoveCompany(name){
  _schedSelected=_schedSelected.filter(n=>n!==name);
  schedRenderSelected();
}
function schedRenderSelected(){
  const list=document.getElementById('schedSelectedList');
  const note=document.getElementById('schedCountNote');
  const btn=document.getElementById('schedGenerateBtn');
  if(!list)return;
  if(!_schedSelected.length){
    list.innerHTML='';
    note.textContent='No companies selected yet.';
    btn.style.opacity='.45';btn.style.pointerEvents='none';
    return;
  }
  list.innerHTML=_schedSelected.map((n,i)=>`
    <div style="display:flex;align-items:center;justify-content:space-between;background:#f4f2ed;border-radius:8px;padding:7px 10px;font-size:12px;font-weight:600;color:#0d1f3c;">
      <span>${i+1}. ${n}${FSP_SCHEDULE_EMAILS[n]?'':' <span style="color:#9ca3af;font-weight:400;">(no email on file)</span>'}</span>
      <button onclick="schedRemoveCompany('${n.replace(/'/g,"\\'")}')" style="background:none;border:none;color:#9ca3af;cursor:pointer;font-size:14px;padding:0 0 0 8px;">✕</button>
    </div>`).join('');
  const count=_schedSelected.length;
  note.textContent=`${count} compan${count===1?'y':'ies'} selected${count===10?' (maximum reached)':''}.`;
  btn.style.opacity='1';btn.style.pointerEvents='auto';
}
function generateScheduleEmail(){
  if(!_schedSelected.length)return;
  const emails=_schedSelected.map(n=>FSP_SCHEDULE_EMAILS[n]).filter(Boolean);
  const noEmail=_schedSelected.filter(n=>!FSP_SCHEDULE_EMAILS[n]);
  if(noEmail.length){
    if(!confirm('No email address on file for: '+noEmail.join(', ')+'. Continue without them?'))return;
  }
  if(!emails.length){alert('No email addresses found for the selected companies.');return;}
  const clientName=(document.getElementById('schedClientName').value.trim())||'[Full Name]';
  const idNumber=(document.getElementById('schedIdNumber').value.trim());
  if(!idNumber){alert('Please enter the client ID number — it is required in the subject line.');return;}
  const advisorName=(document.getElementById('schedAdvisorName').value.trim())||'[Your Name]';
  const dateVal=document.getElementById('schedDate').value;
  const dateStr=dateVal?new Date(dateVal).toLocaleDateString('en-ZA',{day:'2-digit',month:'long',year:'numeric'}):'[Date]';
  saveLoaClient(clientName,idNumber);
  const subject=idNumber+' — Policy Schedule Request';
  const body=`Good day,\n\nPlease find the attached Letter of Authority for ${clientName} (ID Number: ${idNumber}).\n\nKindly provide the full policy contracts including full names, surnames, and dates of birth of all insured lives, for all active policies held by this client.\n\nKind regards,\n${advisorName}\n${dateStr}`;
  const toAddr=emails.join(',');
  const url='https://mail.google.com/mail/?view=cm&to='+encodeURIComponent(toAddr)+'&su='+encodeURIComponent(subject)+'&body='+encodeURIComponent(body);
  closeSchedBuilder();
  triggerLoaDownload();
  window.open(url,'_blank');
  showLoaReminder();
}
// ── END SCHEDULE EMAIL BUILDER ────────────────────────────────────────────

function filterDirectory(q){
  const query=q.toLowerCase().trim();
  let anyFsp=false,anyDir=false;
  document.querySelectorAll('#page-directory .fsp-card').forEach(c=>{
    const match=!query||(c.dataset.search||c.textContent).toLowerCase().includes(query);
    c.style.display=match?'':'none';
    if(match)anyFsp=true;
  });
  document.querySelectorAll('#page-directory .dir-card').forEach(c=>{
    const match=!query||(c.dataset.search||c.textContent).toLowerCase().includes(query);
    c.style.display=match?'':'none';
    if(match)anyDir=true;
  });
  document.querySelectorAll('#page-directory .dir-group').forEach(g=>{
    const vis=[...g.querySelectorAll('.dir-card')].some(c=>c.style.display!=='none');
    g.style.display=vis?'':'none';
  });
  const fspLabel=document.getElementById('fspSectionLabel');
  if(fspLabel)fspLabel.style.display=anyFsp||!query?'':'none';
  const noRes=document.getElementById('dirNoResults');
  if(noRes)noRes.style.display=(!anyFsp&&!anyDir&&query)?'block':'none';
}

function _copyPhone(num){
  navigator.clipboard.writeText(num).catch(()=>{const t=document.createElement('textarea');t.value=num;document.body.appendChild(t);t.select();document.execCommand('copy');document.body.removeChild(t);});
  showAlert('Copied '+num,'success');
}
function wrapFspPhones(){
  if(window._fspPhonesWrapped)return;
  window._fspPhonesWrapped=true;
  document.querySelectorAll('.fsp-num').forEach(div=>{
    const parts=div.textContent.split('·').map(s=>s.trim());
    div.innerHTML=parts.map(part=>{
      const m=part.match(/[\d\s]{8,}/);
      if(m){
        const digits=part.replace(/\s+/g,'');
        const tel='tel:'+digits.replace(/^0/,'+27');
        return`<span style="display:inline-flex;align-items:center;gap:5px;"><a href="${tel}" style="color:#0d1f3c;font-weight:700;text-decoration:none;">${part}</a><button onclick="_copyPhone('${digits}')" title="Copy number" style="background:none;border:1px solid #d1d5db;border-radius:5px;padding:1px 5px;font-size:10px;color:#6b7280;cursor:pointer;line-height:1.4;">📋</button></span>`;
      }
      return part;
    }).join(' · ');
  });
}
function wrapFspEmails(){
  if(window._fspEmailsWrapped) return;
  window._fspEmailsWrapped=true;
  document.querySelectorAll('.fsp-email').forEach(div=>{
    const raw=div.textContent;
    const parts=raw.split('·').map(s=>s.trim());
    const allEmails=parts.map(p=>{const m=p.match(/[^\s·]+@[^\s·]+\.[^\s·]+/);return m?m[0]:null;}).filter(Boolean);
    div.innerHTML=parts.map(p=>{
      const emailMatch=p.match(/[^\s·]+@[^\s·]+\.[^\s·]+/);
      if(emailMatch){
        const addr=emailMatch[0];
        const cc=allEmails.filter(e=>e!==addr);
        const ccJson=JSON.stringify(cc).replace(/"/g,'&quot;');
        return '<span class="fsp-email-link" onclick="showClientDetailStep(\''+addr+'\','+ccJson+')">'+p+'</span>';
      }
      return p;
    }).join(' · ');
  });
}
function showPage(p){
  document.querySelectorAll('.page').forEach(el=>el.classList.remove('active'));
  document.querySelectorAll('.nav-tab').forEach(el=>el.classList.remove('active'));
  const pg=document.getElementById('page-'+p);if(pg){pg.classList.add('active');pg.scrollTop=0;window.scrollTo(0,0);}
  // Only save when user is navigating, not during app startup renders
  if(!window._appBooting)try{localStorage.setItem('tl_page',p);}catch(e){}
  // highlight matching nav tab by onclick attribute
  document.querySelectorAll('.nav-tab').forEach(t=>{
    const oc=t.getAttribute('onclick')||'';
    if(oc.includes("'"+p+"'"))t.classList.add('active');
    // also match opsland to ops tab
    if(p==='opsland'&&oc.includes("'opsland'"))t.classList.add('active');
    if(p==='team'&&oc.includes('showTeam'))t.classList.add('active');
  });
  if(p==='hub'){updateWelcomeBar();updatePrecanHubAlert();updateQlinkHubAlert();updateNtuHubAlert();updateCpdsSection();renderBibleVerse();renderHubCountdown();renderHubPaymentReminder();renderProdCountdownStandalone();renderTop3();renderDailyBrief();}
  if(p==='commcases'){renderCommCases();renderCommQueries();startCommQueryListener();}
  else{stopCommQueryListener();}
  if(p==='referrals')renderReferrals();
  if(p==='guides'){const fc=document.getElementById('fanewsCard');if(fc)fc.style.display=(currentUser&&['SKA310889','PURSHIVILLE'].includes(currentUser.code))?'flex':'none';}
  if(p==='activity')renderActivityLog();
  if(p==='canpack'){mdInit();}
  if(p==='termcal')renderTermCal();
  if(p==='ntu')renderNTUDash();
  if(p==='prospectmap')renderProspectMap();
  if(p==='appchecks')renderAppChecks();
  if(p==='recruit')renderRecruits();
  if(p==='budget'){if(!window._bgtInit){window._bgtInit=true;initBudget();}else{bgtRenderAll();}}
  if(p==='schedules'){renderScheduleTracker();startScheduleListener();}
  else{stopScheduleListener();}
  if(p==='documents')renderDocs();
  if(p==='manager')renderManagerDash();
  if(p==='team'){renderTeamPage();_startTeamPageRefresh();}else{_stopTeamPageRefresh();}
  if(p==='ops'||p==='dailyops')renderOpsPage();
  if(p==='opsland')renderOpsLand();
  if(p==='competitor')renderCompetitors('');
  if(p==='directory'){wrapFspEmails();wrapFspPhones();const ds=document.getElementById('dirSearch');if(ds&&ds.value){ds.value='';filterDirectory('');}}
  if(p==='dailyregion'){if(currentUser&&currentUser.isManager)initDailyRegion();else showPage('hub');}
  if(p==='forms'){renderFormsPage();return;}
  if(p==='standard'){setupStandardHero();renderYTDStats();renderYTDTop3();}
  if(p==='cancellations'){cpInit();}
  if(p==='claimpack'){claimInit();}
  if(p==='fica'){ficaSetMode(_ficaMode||'nb');}
  if(p==='worksites')renderWorksites();
  if(p==='policyreview'){renderPRSavedList();}
  if(p==='replform'){if(!currentUser?.isManager&&!currentUser?.isOps)return showPage('hub');rfInit();}
  if(p==='replpresentation'){replPresentationInit();}
  if(p==='meetingagenda'){if(!currentUser?.isManager&&!currentUser?.isOps)return showPage('hub');agendaRenderNotes();}
  if(p==='prodsnap'){
    if(!currentUser?.isManager&&!currentUser?.isOps)return showPage('hub');
    const now=new Date();
    const mm=document.getElementById('snapPeriodMonth');
    const yy=document.getElementById('snapPeriodYear');
    if(mm&&!mm._init){mm.value=String(now.getMonth()+1).padStart(2,'0');mm._init=true;}
    if(yy&&!yy._init){yy.value=String(now.getFullYear());yy._init=true;}
    renderProdSnap();
  }
  // fitproper page renders itself — no explicit call needed
  // Close More dropdown and sync active states
  closeMoreDropdown();
  document.querySelectorAll('.nav-more-item[data-page]').forEach(btn=>{
    btn.classList.toggle('active', btn.dataset.page===p);
  });
  const moreBtn=document.getElementById('navMoreBtn');
  const morePages=['fitproper','budget','commission','documents','academy'];
  if(moreBtn)moreBtn.classList.toggle('active', morePages.includes(p));
}
function toggleChat(){
  const popup=document.getElementById('aiPopup');
  const pills=document.getElementById('chatPills');
  const isOpen=popup.style.display!=='none';
  popup.style.display=isOpen?'none':'flex';
  document.getElementById('aiUnread').style.display='none';
  if(!isOpen){
    if(!chatHistory.length)_restoreChatHistory();
    document.getElementById('chatInput').focus();
    if(pills)pills.style.display=chatHistory.length?'none':'flex';
    loadGuideForAI();
  }
}


