// ── IMAGE COMPRESSION HELPER ──
async function compressImage(file){
  return new Promise((resolve)=>{
    const img=new Image();
    const url=URL.createObjectURL(file);
    img.onload=()=>{
      const MAX=1600;
      let w=img.width,h=img.height;
      if(w>MAX||h>MAX){if(w>h){h=Math.round(h*MAX/w);w=MAX;}else{w=Math.round(w*MAX/h);h=MAX;}}
      const canvas=document.createElement('canvas');
      canvas.width=w;canvas.height=h;
      canvas.getContext('2d').drawImage(img,0,0,w,h);
      URL.revokeObjectURL(url);
      const dataUrl=canvas.toDataURL('image/jpeg',0.82);
      resolve(dataUrl.split(',')[1]);
    };
    img.onerror=()=>{URL.revokeObjectURL(url);resolve(null);};
    img.src=url;
  });
}

// ── CLAUDE VISION HELPER ──
async function callClaudeVision(b64, mediaType, prompt, maxTokens=1024){
  let finalB64=b64;
  let finalType=mediaType||'image/jpeg';
  if(mediaType!=='application/pdf'){
    const supported=['image/jpeg','image/png','image/gif','image/webp'];
    if(!supported.includes(finalType)) finalType='image/jpeg';
    if(b64.length>2000000){
      const blob=await fetch('data:'+finalType+';base64,'+b64).then(r=>r.blob());
      const compressed=await compressImage(blob);
      if(compressed) finalB64=compressed;
      finalType='image/jpeg';
    }
  }
  const mediaPart = finalType==='application/pdf'
    ? {type:'document', source:{type:'base64', media_type:'application/pdf', data:finalB64}}
    : {type:'image', source:{type:'base64', media_type:finalType, data:finalB64}};
  const response = await fetch('https://sky-claude-proxy.percy-nortje.workers.dev',{
    method:'POST',
    headers:{'content-type':'application/json'},
    body:JSON.stringify({model:'claude-sonnet-4-6',max_tokens:maxTokens,messages:[{role:'user',content:[mediaPart,{type:'text',text:prompt}]}]})
  });
  if(!response.ok){const err=await response.json().catch(()=>({}));throw new Error(err.error?.message||'API error '+response.status);}
  const data=await response.json();
  if(data.error)throw new Error(data.error.message);
  return data.content?.[0]?.text||'{}';
}

// Multi-file variant — sends all pages/screenshots of one policy in a single call
async function callClaudeVisionMulti(files, prompt, maxTokens=4096){
  const contentParts=[];
  for(const f of files){
    let b64=f.b64; let type=f.mediaType||'image/jpeg';
    if(type!=='application/pdf'){
      const supported=['image/jpeg','image/png','image/gif','image/webp'];
      if(!supported.includes(type))type='image/jpeg';
      if(b64.length>2000000){
        const blob=await fetch('data:'+type+';base64,'+b64).then(r=>r.blob());
        const compressed=await compressImage(blob);
        if(compressed)b64=compressed;
        type='image/jpeg';
      }
    }
    contentParts.push(type==='application/pdf'
      ?{type:'document',source:{type:'base64',media_type:'application/pdf',data:b64}}
      :{type:'image',source:{type:'base64',media_type:type,data:b64}});
  }
  contentParts.push({type:'text',text:prompt});
  const response=await fetch('https://sky-claude-proxy.percy-nortje.workers.dev',{
    method:'POST',
    headers:{'content-type':'application/json'},
    body:JSON.stringify({model:'claude-sonnet-4-6',max_tokens:maxTokens,messages:[{role:'user',content:contentParts}]})
  });
  if(!response.ok){const err=await response.json().catch(()=>({}));throw new Error(err.error?.message||'API error '+response.status);}
  const data=await response.json();
  if(data.error)throw new Error(data.error.message);
  return data.content?.[0]?.text||'{}';
}

