function openSettingsPanel(){
  if(!currentUser)return;
  // Show current photo
  const photo=currentUser.photo||(getUsers()[currentUser.code]?.photo)||null;
  const photoEl=document.getElementById('sp_photoPreview');
  if(photoEl)photoEl.innerHTML=photo?`<img src="${photo}" style="width:100%;height:100%;object-fit:cover;border-radius:50%;display:block;">`:'📷';
  const photoInput=document.getElementById('sp_photoInput');
  if(photoInput){photoInput.value='';photoInput._b64=null;}
  // Populate profile fields
  document.getElementById('sp_name').value=currentUser.name||'';
  document.getElementById('sp_email').value=currentUser.email||'';
  document.getElementById('sp_dob').value=currentUser.dob||'';
  document.getElementById('sp_dofa').value=currentUser.dofa||'';
  // Hide password fields for hardcoded accounts
  const isHardcoded=currentUser.code==='PURSHIVILLE'||currentUser.code==='ARLENE';
  document.querySelector('.settings-panel .settings-section:nth-child(2)').style.display=isHardcoded?'none':'block';
  // Reset password fields
  ['sp_oldPass','sp_newPass','sp_newPass2'].forEach(id=>{document.getElementById(id).value='';});
  const msg=document.getElementById('sp_passMsg');if(msg)msg.style.display='none';
  // Update notification status
  updateNotifStatus();
  // Update avatar initials
  updateTopbarAvatar();
  document.getElementById('settingsPanel').classList.add('open');
  document.getElementById('settingsOverlay').classList.add('open');
  sigLoadDisplay();
  sigInitCanvas();
}

function closeSettingsPanel(){
  document.getElementById('settingsPanel').classList.remove('open');
  document.getElementById('settingsOverlay').classList.remove('open');
}

function updateTopbarAvatar(){
  const btn=document.getElementById('topbarAvatarBtn');
  if(!btn||!currentUser)return;
  const photo=currentUser.photo||(getUsers()[currentUser.code]?.photo)||null;
  if(photo){
    btn.innerHTML=`<img src="${photo}" style="width:100%;height:100%;object-fit:cover;border-radius:50%;display:block;">`;
  } else {
    const initials=(currentUser.name||'?').split(' ').map(w=>w[0]).join('').toUpperCase().slice(0,2);
    btn.textContent=initials;
  }
}

function saveProfileSettings(){
  if(!currentUser)return;
  const name=document.getElementById('sp_name').value.trim();
  const email=document.getElementById('sp_email').value.trim();
  const dob=document.getElementById('sp_dob').value;
  const dofa=document.getElementById('sp_dofa').value;
  if(!name)return alert('Name cannot be empty.');
  const users=getUsers();
  if(users[currentUser.code]){
    users[currentUser.code].name=name;
    users[currentUser.code].email=email;
    users[currentUser.code].dob=dob;
    users[currentUser.code].dofa=dofa;
    saveUsers(users);
    if(window.FB_READY){window.FB.saveUser(currentUser.code,users[currentUser.code]).catch(()=>{});}
  }
  currentUser.name=name;currentUser.email=email;currentUser.dob=dob;currentUser.dofa=dofa;
  try{localStorage.setItem('tl_session',JSON.stringify(currentUser));}catch(e){}
  updateTopbarAvatar();
  updateWelcomeBar();
  const btn=document.getElementById('sp_saveProfileBtn');
  btn.textContent='✓ Saved!';btn.classList.add('success');
  setTimeout(()=>{btn.textContent='Save profile';btn.classList.remove('success');},2000);
}

function savePasswordSettings(){
  const oldPass=document.getElementById('sp_oldPass').value;
  const newPass=document.getElementById('sp_newPass').value;
  const newPass2=document.getElementById('sp_newPass2').value;
  const msg=document.getElementById('sp_passMsg');
  const showMsg=(text,ok)=>{msg.style.display='block';msg.style.background=ok?'#f0fdf4':'#fef2f2';msg.style.color=ok?'#166534':'#991b1b';msg.style.border=ok?'1px solid #86efac':'1px solid #fca5a5';msg.textContent=text;};
  if(!oldPass||!newPass||!newPass2)return showMsg('Please fill in all password fields.', false);
  if(newPass.length<6)return showMsg('New password must be at least 6 characters.', false);
  if(newPass!==newPass2)return showMsg('New passwords do not match.', false);
  const users=getUsers();
  if(!users[currentUser.code])return showMsg('Account not found.', false);
  if(users[currentUser.code].pass!==oldPass)return showMsg('Current password is incorrect.', false);
  users[currentUser.code].pass=newPass;
  saveUsers(users);
  if(window.FB_READY){window.FB.saveUser(currentUser.code,users[currentUser.code]).catch(()=>{});}
  ['sp_oldPass','sp_newPass','sp_newPass2'].forEach(id=>{document.getElementById(id).value='';});
  showMsg('✓ Password updated successfully!', true);
}

function updateNotifStatus(){
  const statusEl=document.getElementById('sp_notifStatus');
  const btn=document.getElementById('sp_notifBtn');
  if(!statusEl||!btn)return;
  if(!('Notification' in window)){
    statusEl.className='notif-status denied';statusEl.textContent='Notifications not supported in this browser.';btn.style.display='none';return;
  }
  if(Notification.permission==='granted'){
    statusEl.className='notif-status granted';statusEl.textContent='✓ Notifications enabled — you will be alerted when new notices are posted.';btn.style.display='none';
  } else if(Notification.permission==='denied'){
    statusEl.className='notif-status denied';statusEl.textContent='Notifications blocked. Go to your browser settings to allow notifications for this site.';btn.style.display='none';
  } else {
    statusEl.className='notif-status default';statusEl.textContent='Notifications not yet enabled.';btn.style.display='block';
  }
}

function requestNotifFromSettings(){
  if(!('Notification' in window))return;
  Notification.requestPermission().then(()=>updateNotifStatus());
}

async function doChangePassword(){
  clearAlert();
  const code=document.getElementById('cpCode').value.trim().toUpperCase();
  const oldPass=document.getElementById('cpOld').value;
  const newPass=document.getElementById('cpNew').value;
  const newPass2=document.getElementById('cpNew2').value;
  if(!code)return showAlert('Please enter your employee code.','error');
  if(!oldPass)return showAlert('Please enter your current password.','error');
  if(!newPass||newPass.length<6)return showAlert('New password must be at least 6 characters.','error');
  if(newPass!==newPass2)return showAlert('New passwords do not match.','error');
  const users=getUsers();
  if(!users[code])return showAlert('Employee code not found. Please register first.','error');
  if(users[code].pass!==oldPass)return showAlert('Current password is incorrect.','error');
  users[code].pass=newPass;
  saveUsers(users);
  if(window.FB_READY){window.FB.saveUser(code,users[code]).catch(()=>{});}
  if(window.FB_READY&&window.FB.logActivity){window.FB.logActivity({userCode:code,userName:users[code]?.name||code,action:'PASSWORD_CHANGED',detail:'Password updated via login screen',localTs:new Date().toISOString()}).catch(()=>{});}
  document.getElementById('cpCode').value='';document.getElementById('cpOld').value='';document.getElementById('cpNew').value='';document.getElementById('cpNew2').value='';
  showAlert('Password updated successfully. You can now sign in.','success');
  setTimeout(()=>switchTab('login'),2000);
}

// ── POLICY REVIEW ──────────────────────────────────────────────────────────
let _prLoaFile=null;
let _prDocFiles=[];
let _prExtracted=[];

const PR_LOA_PROMPT=`Read this Letter of Authority document and extract the client's personal details. Return ONLY valid JSON — no markdown, no explanation.

Look for: full name, South African 13-digit ID number, cellphone or telephone number, email address.

Return exactly: {"name":"","id_number":"","phone":"","email":""}

Use empty string for any field not found.`;

const PR_EXTRACT_PROMPT=`You are reading a South African life insurance policy document (schedule or full contract). Extract all details and return ONLY valid JSON — no explanation, no markdown.

IMPORTANT: If this document contains MULTIPLE policies (e.g. a Sanlam Sky group policy schedule listing several policy numbers and premiums), return an ARRAY of policy objects: [{...}, {...}, ...]. For a single policy return a single-element array: [{...}]. Every object in the array must follow the full structure below.

IDENTIFY POLICY TYPE — use one of these exact values or combinations:
- "Funeral" — funeral cover, burial policy, final expenses plan
- "Life" — life cover/assurance, death benefit only
- "Disability" — disability cover, income protection, temporary/permanent disability
- "Dread Disease" — critical illness, severe illness, dread disease cover
- "Accidental Death" — personal accident, accidental death only policy
- For combined cover use plus sign: "Life + Funeral", "Life + Disability", "Life + Disability + Dread Disease" etc.
- Default to "Life" only if truly unclear.

NORMALISE terminology:
- "Sum assured" / "benefit amount" / "cover amount" / "insured amount" / "total benefit" / "death benefit" → cover per life
- "Premium waiver" / "waiver of premium" / "no more premiums" / "premium protector" / "payor benefit" / "APW" / "breadwinner's benefit" / "breadwinner benefit" / "BW benefit" → no_more_premiums: true
- "Accidental death benefit" / "ADB" / "double accident" / "double indemnity" / "personal accident" → accident_double: true
- "Funeral benefit" / "burial benefit" / "funeral cover" / "final expenses" / "funeral plan" → burial: true
- "Cash bonus" / "loyalty bonus" / "paid-up bonus" / "cashback" / "cash dividend" / "recurring bonus" → cashback: true
- "Premium holiday" / "payment holiday" / "premium break" / "death holiday" → payment_holiday: true
- "Paid-up option" / "reduced paid-up" / "fully paid-up" → paid_up: true
- "Principal member" / "main life" / "policyholder" / "life assured (main)" / "primary member" → relationship: "Main"
- "Spouse" / "partner" / "life partner" / "married partner" → relationship: "Spouse"
- "Child" / "dependent" / "juvenile" / "dependent child" → relationship: "Child"
- "Mother" / "Father" / "Parent" → relationship: "Parent"
- "Brother" / "Sister" → relationship: "Sibling"
- "Uncle" / "Aunt" / "Cousin" / "Nephew" / "Niece" → keep as-is
- "Extended family" / "extended member" / "other" → relationship: "Extended"

Also:
- "Inception date" / "commencement date" / "policy date" → start_date
- Account in arrears, overdue premiums, lapsed → in_arrears: true AND add to red_flags
- Any exclusions, waiting periods, high-risk notes → add to red_flags
- Any beneficiary with NO cover (no sum assured) → include in lives with cover: 0 and is_beneficiary_only: true
- extra: remaining benefits not captured above, semicolon-separated; empty string if none
- IMPORTANT: Do NOT list the main policyholder twice under different relationship labels. If "Extended" or any non-Main life has the same name and date of birth as the Main life, omit that duplicate entry entirely.

Return this exact structure:
{"insurer":"","policy_number":null,"start_date":null,"plan_name":"","policy_type":"Funeral","premium":0,"benefits":{"cashback":false,"payment_holiday":false,"no_more_premiums":false,"accident_double":false,"burial":false,"paid_up":false,"extra":""},"in_arrears":false,"lives":[{"name":null,"relationship":"Main","dob":null,"gender":null,"cover":0,"is_beneficiary_only":false}],"red_flags":[]}

Use null for unknown strings, 0 for unknown numbers, false for unknown booleans.`;

function handlePRLOAUpload(input){
  const file=input.files[0];
  if(!file)return;
  const reader=new FileReader();
  reader.onload=async e=>{
    const b64=e.target.result.split(',')[1];
    const mediaType=file.type||'image/jpeg';
    _prLoaFile={b64,mediaType,name:file.name};
    const status=document.getElementById('prLoaStatus');
    if(status)status.innerHTML=`<span style="color:#16a34a;font-weight:700;">✓ LOA uploaded: ${file.name} — reading client details…</span>`;
    const zone=document.getElementById('prLoaZone');
    if(zone){zone.style.borderColor='#16a34a';zone.style.background='#f0fdf4';}
    const note=document.getElementById('prLoaRequiredNote');
    if(note)note.style.display='none';
    updatePRButtons();
    try{
      const raw=await callClaudeVision(b64,mediaType,PR_LOA_PROMPT);
      const m=raw.match(/\{[\s\S]*\}/);
      if(m){
        const d=JSON.parse(m[0]);
        const fill=(id,val)=>{if(val){const el=document.getElementById(id);if(el&&!el.value.trim())el.value=val;}};
        fill('prClientName',d.name);
        fill('prClientId',d.id_number);
        fill('prClientPhone',d.phone);
        fill('prClientEmail',d.email);
        if(status)status.innerHTML=`<span style="color:#16a34a;font-weight:700;">✓ LOA uploaded — client details auto-filled from: ${file.name}</span>`;
      }
    }catch(e){
      if(status)status.innerHTML=`<span style="color:#16a34a;font-weight:700;">✓ LOA uploaded: ${file.name}</span> <span style="color:#6b7280;font-size:11px;">(fill client details manually)</span>`;
    }
  };
  reader.readAsDataURL(file);
}

// _prDocFiles entries: {files:[{b64,mediaType,name}], label, status, data, error}
function handlePRDocUpload(input){
  const files=Array.from(input.files);
  if(!files.length)return;
  let pending=files.length;
  files.forEach(file=>{
    const reader=new FileReader();
    reader.onload=e=>{
      const b64=e.target.result.split(',')[1];
      const mediaType=file.type||'image/jpeg';
      _prDocFiles.push({files:[{b64,mediaType,name:file.name}],label:file.name,status:'pending',data:null,error:null});
      if(--pending===0){renderPRDocList();updatePRButtons();}
    };
    reader.readAsDataURL(file);
  });
  input.value='';
}

function addPageToPRDoc(idx){
  const inp=document.createElement('input');
  inp.type='file';inp.accept='image/*,.pdf';inp.multiple=true;
  inp.onchange=e=>{
    const files=Array.from(e.target.files);
    if(!files.length)return;
    let pending=files.length;
    files.forEach(file=>{
      const reader=new FileReader();
      reader.onload=ev=>{
        _prDocFiles[idx].files.push({b64:ev.target.result.split(',')[1],mediaType:file.type||'image/jpeg',name:file.name});
        if(_prDocFiles[idx].status==='done')_prDocFiles[idx].status='pending'; // mark for re-analysis
        _prDocFiles[idx].label=_prDocFiles[idx].files[0].name+((_prDocFiles[idx].files.length>1)?' + '+((_prDocFiles[idx].files.length-1)+' more'):'');
        if(--pending===0){renderPRDocList();updatePRButtons();}
      };
      reader.readAsDataURL(file);
    });
  };
  inp.click();
}

function removePRDoc(idx){
  _prDocFiles.splice(idx,1);
  _prExtracted.splice(idx,1);
  renderPRDocList();
  renderPRSummary();
  updatePRButtons();
}

function renderPRDocList(){
  const el=document.getElementById('prDocList');
  if(!el)return;
  if(!_prDocFiles.length){
    el.innerHTML='<div style="text-align:center;color:#9ca3af;font-size:12px;padding:8px;">No documents uploaded yet.</div>';
    return;
  }
  el.innerHTML=_prDocFiles.map((f,i)=>{
    let badge='';
    if(f.status==='pending')badge='<span style="background:#fef3c7;color:#92400e;font-size:10px;font-weight:700;padding:2px 8px;border-radius:10px;">Pending</span>';
    else if(f.status==='processing')badge='<span style="background:#dbeafe;color:#1d4ed8;font-size:10px;font-weight:700;padding:2px 8px;border-radius:10px;">Analysing…</span>';
    else if(f.status==='done')badge='<span style="background:#dcfce7;color:#166534;font-size:10px;font-weight:700;padding:2px 8px;border-radius:10px;">✓ Done</span>';
    else if(f.status==='error')badge='<span style="background:#fee2e2;color:#991b1b;font-size:10px;font-weight:700;padding:2px 8px;border-radius:10px;">⚠ Error</span>';
    const reReadBtn=(f.status==='error'||f.status==='done')?`<button onclick="reReadPRDoc(${i})" style="background:#f4f2ed;border:1px solid #e5e7eb;color:#0d1f3c;cursor:pointer;font-size:11px;font-weight:700;padding:3px 10px;border-radius:7px;white-space:nowrap;">↻ Re-read</button>`:'';
    const reUploadBtn=f.status==='error'?`<button onclick="reUploadPRDoc(${i})" style="background:#fee2e2;border:1px solid #fca5a5;color:#991b1b;cursor:pointer;font-size:11px;font-weight:700;padding:3px 10px;border-radius:7px;white-space:nowrap;">↑ Re-upload</button>`:'';
    const addPageBtn=f.status!=='error'?`<button onclick="addPageToPRDoc(${i})" style="background:#f0f9ff;border:1px solid #bae6fd;color:#075985;cursor:pointer;font-size:11px;font-weight:700;padding:3px 10px;border-radius:7px;white-space:nowrap;">+ Add page</button>`:'';
    const pageList=f.files.length>1?`<div style="font-size:10px;color:#6b7280;margin-top:3px;">${f.files.map(p=>'📄 '+p.name).join(' · ')}</div>`:'';
    const preview=f.data?`<div style="font-size:11px;color:#6b7280;margin-top:4px;">${f.data.insurer||'Unknown'} — ${f.data.plan_name||'Unknown plan'} — ${_prFmtR(f.data.premium||0)}/month</div>`:'';
    const errMsg=f.error?`<div style="font-size:11px;color:#dc2626;margin-top:4px;">${f.error}</div>`:'';
    return `<div style="display:flex;align-items:flex-start;justify-content:space-between;background:#f8f7f4;border-radius:10px;padding:9px 12px;border:1px solid #e5e7eb;">
      <div style="flex:1;">
        <div style="display:flex;align-items:center;gap:6px;flex-wrap:wrap;">
          <span style="font-size:12px;font-weight:700;color:#0d1f3c;">${f.label}</span>${badge}${reReadBtn}${reUploadBtn}${addPageBtn}
        </div>
        ${pageList}${preview}${errMsg}
      </div>
      <button onclick="removePRDoc(${i})" title="Remove this policy" style="background:none;border:none;color:#9ca3af;cursor:pointer;font-size:16px;padding:0 0 0 10px;flex-shrink:0;">✕</button>
    </div>`;
  }).join('');
}

async function _prExtractOne(idx){
  const f=_prDocFiles[idx];
  f.status='processing';f.error=null;
  renderPRDocList();
  try{
    const raw=await callClaudeVisionMulti(f.files,PR_EXTRACT_PROMPT,4096);
    let parsed;
    try{
      let js=raw.replace(/```(?:json)?\s*/gi,'').replace(/```\s*/g,'').trim();
      // Try array first, then fall back to single object
      const arrStart=js.indexOf('[');const objStart=js.indexOf('{');
      if(arrStart>=0&&(objStart<0||arrStart<objStart)){
        let d=0,end=-1;for(let ci=arrStart;ci<js.length;ci++){if(js[ci]==='[')d++;else if(js[ci]===']'){d--;if(d===0){end=ci;break;}}}
        js=end>=0?js.slice(arrStart,end+1):js.slice(arrStart);
      } else if(objStart>=0){
        let d=0,end=-1;for(let ci=objStart;ci<js.length;ci++){if(js[ci]==='{')d++;else if(js[ci]==='}'){d--;if(d===0){end=ci;break;}}}
        js=end>=0?js.slice(objStart,end+1):js.slice(objStart);
      }
      parsed=JSON.parse(js);
    }catch(e){throw new Error('Could not read this document. Please tap Re-upload with a clearer scan or a different file.');}
    // Handle multi-policy array response
    const policies=Array.isArray(parsed)?parsed:[parsed];
    f.status='done';f.data=policies[0];_prExtracted[idx]=policies[0];
    // Insert extra policies as additional entries after current index
    for(let i=1;i<policies.length;i++){
      _prDocFiles.splice(idx+i,0,{files:f.files,label:f.label+' — Policy '+(i+1),status:'done',data:policies[i],error:null});
      _prExtracted.splice(idx+i,0,policies[i]);
    }
  }catch(err){
    f.status='error';f.error=err.message||'Analysis failed — tap Re-read to try again.';_prExtracted[idx]=null;
  }
  renderPRDocList();
}

async function reReadPRDoc(idx){
  if(!_prDocFiles[idx])return;
  await _prExtractOne(idx);
  renderPRSummary();
  updatePRButtons();
}

function reUploadPRDoc(idx){
  if(!_prDocFiles[idx])return;
  const inp=document.createElement('input');
  inp.type='file';inp.accept='.pdf,image/*';inp.multiple=true;
  inp.onchange=async()=>{
    const files=Array.from(inp.files);if(!files.length)return;
    const loaded=[];
    for(const file of files){
      await new Promise((res,rej)=>{
        const r=new FileReader();
        r.onload=e=>{loaded.push({b64:e.target.result.split(',')[1],mediaType:file.type||'image/jpeg',name:file.name});res();};
        r.onerror=rej;r.readAsDataURL(file);
      });
    }
    _prDocFiles[idx].files=loaded;
    _prDocFiles[idx].label=loaded[0].name+(loaded.length>1?` + ${loaded.length-1} more`:'');
    _prDocFiles[idx].status='pending';_prDocFiles[idx].data=null;_prDocFiles[idx].error=null;
    renderPRDocList();
    await _prExtractOne(idx);
    renderPRSummary();updatePRButtons();
  };
  inp.click();
}

function updatePRButtons(){
  const analyseBtn=document.getElementById('prAnalyseBtn');
  const generateBtn=document.getElementById('prGenerateBtn');
  const rlNote=document.getElementById('prRateLimitNote');
  const hasLoa=!!_prLoaFile;
  const hasDocs=_prDocFiles.length>0;
  const allDone=_prDocFiles.length>0&&_prDocFiles.every(f=>f.status==='done'||f.status==='error');
  // Check 24-hour rate limit (bypassed for manager/ops)
  const rlKey='prLastAnalysis_'+(currentUser?.code||'default');
  const lastRun=parseInt(localStorage.getItem(rlKey)||'0',10);
  const elapsed=Date.now()-lastRun;
  const limit24h=24*60*60*1000;
  const isRateLimited=!(currentUser?.isManager||currentUser?.isOps)&&lastRun>0&&elapsed<limit24h;
  if(rlNote){
    if(isRateLimited){
      const rem=limit24h-elapsed;
      const hrs=Math.floor(rem/3600000);const mins=Math.floor((rem%3600000)/60000);
      rlNote.style.display='block';
      rlNote.innerHTML=`🚫 You have already run a policy review in the last 24 hours. Next analysis available in <strong>${hrs}h ${mins}m</strong>. If this is a new client, please try again later or contact your manager.`;
    } else {rlNote.style.display='none';}
  }
  if(analyseBtn){
    const canAnalyse=hasLoa&&hasDocs&&!isRateLimited;
    analyseBtn.disabled=!canAnalyse;
    analyseBtn.style.opacity=canAnalyse?'1':'.4';
    analyseBtn.style.cursor=canAnalyse?'pointer':'not-allowed';
  }
  if(generateBtn){
    const canGen=allDone&&_prExtracted.some(Boolean);
    generateBtn.disabled=!canGen;
    generateBtn.style.opacity=canGen?'1':'.4';
    generateBtn.style.cursor=canGen?'pointer':'not-allowed';
  }
  const saveBtn=document.getElementById('prSaveBtn');
  if(saveBtn){
    const canSave=allDone&&_prExtracted.some(Boolean);
    saveBtn.disabled=!canSave;
    saveBtn.style.opacity=canSave?'1':'.4';
    saveBtn.style.cursor=canSave?'pointer':'not-allowed';
  }
}

async function analysePRDocuments(){
  if(!_prLoaFile){alert('Please upload the Letter of Authority first — it is required before generating a policy review.');return;}
  if(!_prDocFiles.length){alert('Please upload at least one policy document.');return;}
  // 24-hour rate limit per advisor (manager/ops exempt)
  const rlKey='prLastAnalysis_'+(currentUser?.code||'default');
  const lastRun=parseInt(localStorage.getItem(rlKey)||'0',10);
  const elapsed=Date.now()-lastRun;
  const limit24h=24*60*60*1000;
  if(!(currentUser?.isManager||currentUser?.isOps)&&elapsed<limit24h){
    const remaining=limit24h-elapsed;
    const hrs=Math.floor(remaining/3600000);
    const mins=Math.floor((remaining%3600000)/60000);
    const note=document.getElementById('prRateLimitNote');
    if(note){note.style.display='block';note.innerHTML=`🚫 You have already run a policy review in the last 24 hours. Next analysis available in <strong>${hrs}h ${mins}m</strong>. If this is a new client, please try again later or contact your manager.`;}
    return;
  }
  const analyseBtn=document.getElementById('prAnalyseBtn');
  if(analyseBtn){analyseBtn.disabled=true;analyseBtn.textContent='Analysing…';}
  // Ensure extracted array matches doc array length
  while(_prExtracted.length<_prDocFiles.length)_prExtracted.push(null);
  for(let i=0;i<_prDocFiles.length;i++){
    if(_prDocFiles[i].status==='done')continue; // skip already-analysed docs
    await _prExtractOne(i);
  }
  if(analyseBtn){analyseBtn.disabled=false;analyseBtn.textContent='Analyse new documents';}
  // Record timestamp for 24-hour rate limit
  localStorage.setItem('prLastAnalysis_'+(currentUser?.code||'default'),Date.now().toString());
  const rlNote=document.getElementById('prRateLimitNote');
  if(rlNote)rlNote.style.display='none';
  renderPRSummary();
  _prAutoFillNotes();
  updatePRButtons();
  const sec=document.getElementById('prSummarySection');
  if(sec&&_prExtracted.some(Boolean)){sec.style.display='block';sec.scrollIntoView({behavior:'smooth',block:'start'});}
}

function _prAgeFromDob(dob){
  if(!dob)return null;
  const m=dob.match(/(\d{1,2})[\/-](\d{1,2})[\/-](\d{4})/);
  if(!m)return null;
  const birth=new Date(parseInt(m[3]),parseInt(m[2])-1,parseInt(m[1]));
  const now=new Date();
  let age=now.getFullYear()-birth.getFullYear();
  if(now.getMonth()<birth.getMonth()||(now.getMonth()===birth.getMonth()&&now.getDate()<birth.getDate()))age--;
  return isNaN(age)?null:age;
}

function _prFmtR(n){
  const s=(n||0).toFixed(2);
  const[int,dec]=s.split('.');
  return'R '+int.replace(/\B(?=(\d{3})+(?!\d))/g,' ')+'.'+dec;
}

function _prLiveBg(life){
  if(life.totalCover===0)return{bg:'#fff8e1',label:'No cover'};
  if(life.totalCover>100000)return{bg:'#fef3c7',label:''};  // amber — very high cover
  if(life.totalCover>=80000)return{bg:'#dcfce7',label:''};   // green — good cover
  if(life.totalCover>0&&life.totalCover<20000){
    const rel=(life.relationship||'').toLowerCase();
    if(rel.includes('child')){const age=_prAgeFromDob(life.dob);if(age!==null&&age<7)return{bg:'',label:''};}
    return{bg:'#fee2e2',label:''};  // red — low cover
  }
  return{bg:'',label:''};
}

function _prAutoFillNotes(){
  const pols=(_prExtracted||[]).filter(Boolean);
  if(!pols.length)return;
  const notesEl=document.getElementById('prAdvisorNotes');
  if(!notesEl)return;
  const notes=[];

  // Policies without premium waiver — will lapse when main life dies, all family members lose cover
  const noPW=[];
  pols.forEach((p,i)=>{
    if(!p.benefits?.no_more_premiums){
      const affected=(p.lives||[])
        .filter(l=>l.relationship!=='Main'&&!l.is_beneficiary_only&&(l.cover||0)>0)
        .map(l=>l.name?`${l.relationship} (${l.name})`:l.relationship);
      const label=`${p.insurer||'Policy '+(i+1)}${p.policy_number?' — '+p.policy_number:''}`;
      if(affected.length){
        noPW.push(`  • ${label}: ${affected.join(', ')} will lose their cover`);
      }
    }
  });
  if(noPW.length){
    notes.push(`⚠ POLICIES WITHOUT PREMIUM WAIVER\nIf the client passes away, the premium on the following policies will not be paid and they will lapse — all remaining covered lives will lose their cover:\n${noPW.join('\n')}`);
  }

  // No spouse on any policy
  const allLives=pols.flatMap(p=>p.lives||[]);
  const hasSpouse=allLives.some(l=>l.relationship==='Spouse'&&!l.is_beneficiary_only);
  if(!hasSpouse){
    notes.push(`❓ SPOUSE / LIFE PARTNER\nNo spouse or life partner appears as an insured life on any of the client's policies. Is the client single, divorced, or widowed? Does the client have a partner who should be considered for cover?`);
  }

  if(!notes.length)return;
  // Replace any previously auto-generated block (identified by marker) or append
  const MARKER='⚠ POLICIES WITHOUT PREMIUM WAIVER';
  const MARKER2='❓ SPOUSE / LIFE PARTNER';
  let existing=notesEl.value;
  // Strip old auto-block if present
  [MARKER,MARKER2].forEach(mk=>{
    const start=existing.indexOf(mk);
    if(start!==-1){
      const before=existing.slice(0,start).trimEnd();
      const after=existing.slice(start).replace(/[\s\S]*?(\n\n|$)/,'').trimStart();
      existing=(before+(after?'\n\n'+after:'')).trim();
    }
  });
  notesEl.value=(existing?existing+'\n\n':'')+notes.join('\n\n');
}

function _prBuildLivesMap(policies){
  const map={};
  policies.forEach((p,pIdx)=>{
    // Find main life DOB and surname for duplicate detection
    const mainLife=(p.lives||[]).find(l=>l.relationship==='Main');
    const mainDob=mainLife?.dob||'';
    const mainSurname=(mainLife?.name||'').split(' ').pop().toLowerCase();
    (p.lives||[]).forEach(life=>{
      // Skip if this non-Main life appears to be the policyholder listed again
      if(life.relationship!=='Main'&&mainDob&&life.dob===mainDob){
        const lifeSurname=(life.name||'').split(' ').pop().toLowerCase();
        if(mainSurname&&lifeSurname&&lifeSurname===mainSurname)return;
      }
      const key=(life.name||'')+'|'+(life.relationship||'')+'|'+(life.dob||'');
      if(!map[key])map[key]={relationship:life.relationship||'Other',name:life.name||'',dob:life.dob||'',gender:life.gender||'',policies:{},isBeneficiaryOnly:!!life.is_beneficiary_only,totalCover:0};
      map[key].policies[pIdx]=life.cover||0;
      if(!life.is_beneficiary_only)map[key].totalCover+=(life.cover||0);
    });
  });
  const relOrder=['Main','Spouse','Child','Parent','Sibling','Uncle','Aunt','Cousin','Nephew','Niece','In-Law','Extended','Other'];
  return Object.values(map).sort((a,b)=>{const ai=relOrder.indexOf(a.relationship);const bi=relOrder.indexOf(b.relationship);return(ai===-1?99:ai)-(bi===-1?99:bi);});
}

function _prTypeBadge(type,forPdf){
  if(!type)return'—';
  const colors={'Funeral':'#7c3aed','Life':'#1d4ed8','Disability':'#047857','Dread Disease':'#b45309','Accidental Death':'#dc2626'};
  let bg='#6b7280';
  for(const[k,c]of Object.entries(colors)){if(type.includes(k)){bg=c;break;}}
  if(forPdf)return`<span style="background:${bg};color:#fff;font-size:8px;font-weight:700;padding:2px 6px;border-radius:8px;white-space:nowrap;">${type}</span>`;
  return`<span style="background:${bg};color:#fff;font-size:10px;font-weight:700;padding:2px 8px;border-radius:10px;white-space:nowrap;">${type}</span>`;
}

function _prPolicyNotesGroups(policies){
  return policies.map((p,i)=>{
    const notes=[];
    if(p.in_arrears)notes.push('Account is in arrears — premiums overdue');
    (p.red_flags||[]).forEach(rf=>{if(rf&&!notes.includes(rf))notes.push(rf);});
    if(!notes.length)return null;
    return{label:`${p.insurer||'Policy '+(i+1)}${p.policy_number?' — '+p.policy_number:''}`,notes};
  }).filter(Boolean);
}

function _prCheckMissing(){
  const el=document.getElementById('prMissingWarning');
  if(!el)return;
  const policies=(_prExtracted||[]).filter(Boolean);
  if(!policies.length){el.style.display='none';return;}
  const rows=[];
  policies.forEach((p,i)=>{
    const label=p.insurer||(p.plan_name?p.plan_name:'Policy '+(i+1));
    const missing=[];
    if(!p.start_date)missing.push('start date');
    if(!p.policy_number)missing.push('policy number');
    if(!p.plan_name)missing.push('plan name');
    if(!p.premium)missing.push('premium amount');
    (p.lives||[]).forEach(l=>{
      if(!l.dob)missing.push(`date of birth for ${l.name||l.relationship}`);
    });
    if(missing.length)rows.push({label,missing});
  });
  if(!rows.length){el.style.display='none';return;}
  el.style.display='block';
  el.innerHTML=`<div style="background:#fffbeb;border:1px solid #f59e0b;border-radius:10px;padding:12px 14px;">
    <div style="font-size:12px;font-weight:800;color:#92400e;margin-bottom:8px;">⚠ Some details could not be read from the documents — please verify and complete manually if needed. The review can still be generated as-is.</div>
    ${rows.map(r=>`<div style="margin-bottom:6px;"><span style="font-size:11px;font-weight:700;color:#0d1f3c;">${r.label}:</span> <span style="font-size:11px;color:#78350f;">${r.missing.join(', ')}</span></div>`).join('')}
  </div>`;
}

function renderPRSummary(){
  const policies=_prExtracted.filter(Boolean);
  const previewEl=document.getElementById('prSummaryPreview');
  if(!previewEl)return;
  if(!policies.length){previewEl.innerHTML='';return;}
  const tick=v=>v?'✓':'';
  const totalPremium=policies.reduce((s,p)=>s+(p.premium||0),0);
  const allLives=_prBuildLivesMap(policies);
  const noteGroups=_prPolicyNotesGroups(policies);

  const th='padding:6px 8px;background:#0d1f3c;color:#fff;text-align:left;white-space:nowrap;border:1px solid #1b3460;font-size:11px;';
  const thC='padding:6px 8px;background:#0d1f3c;color:#fff;text-align:center;white-space:nowrap;border:1px solid #1b3460;font-size:11px;';
  const thBenef='padding:4px 8px;background:#1b3460;color:#f5d98b;text-align:center;border:1px solid #0d1f3c;font-size:10px;font-weight:700;letter-spacing:.5px;';

  // Policy rows
  const policyRows=policies.map((p,i)=>{
    const b=p.benefits||{};
    const arr=p.in_arrears?` <span style="color:#dc2626;font-size:9px;font-weight:800;"> ⚠ ARREARS</span>`:'';
    const bg=i%2===0?'':'background:#f9f9f9;';
    const tdS=`padding:6px 8px;border:1px solid #e5e7eb;font-size:11px;vertical-align:middle;${bg}`;
    return`<tr><td style="${tdS}">${p.insurer||'—'}${arr}</td><td style="${tdS}font-family:monospace;">${p.policy_number||'—'}</td><td style="${tdS}">${p.start_date||'—'}</td><td style="${tdS}">${p.plan_name||'—'}</td><td style="${tdS}text-align:center;">${_prTypeBadge(p.policy_type,false)}</td><td style="${tdS}text-align:right;font-weight:700;">${_prFmtR(p.premium||0)}</td><td style="${tdS}text-align:center;">${tick(b.cashback)}</td><td style="${tdS}text-align:center;">${tick(b.payment_holiday)}</td><td style="${tdS}text-align:center;">${tick(b.no_more_premiums)}</td><td style="${tdS}text-align:center;">${b.accident_double?'✓':''}</td><td style="${tdS}text-align:center;">${tick(b.burial)}</td><td style="${tdS}text-align:center;">${tick(b.paid_up)}</td><td style="${tdS}font-size:10px;">${b.extra||'—'}</td></tr>`;
  }).join('');

  // Lives rows
  const phCols=policies.map((p,i)=>`<th style="${thC}min-width:80px;">${p.policy_number||'P'+(i+1)}</th>`).join('');
  const livesRows=allLives.map(life=>{
    const {bg:rowBg,label:rowLabel}=_prLiveBg(life);
    const bgStyle=rowBg?`background:${rowBg};`:'';
    const cells=policies.map((p,pIdx)=>{
      const c=life.policies[pIdx];
      return`<td style="padding:6px 8px;border:1px solid #e5e7eb;font-size:11px;text-align:center;${bgStyle}">${(c&&c>0)?'R '+c.toLocaleString('en-ZA'):''}</td>`;
    }).join('');
    const badge=rowLabel?` <span style="background:#f59e0b;color:#fff;font-size:9px;font-weight:700;padding:1px 6px;border-radius:8px;">${rowLabel}</span>`:'';
    return`<tr><td style="padding:6px 8px;border:1px solid #e5e7eb;font-size:11px;${bgStyle}">${life.relationship}${badge}</td><td style="padding:6px 8px;border:1px solid #e5e7eb;font-size:11px;${bgStyle}">${life.name||''}</td><td style="padding:6px 8px;border:1px solid #e5e7eb;font-size:11px;font-family:monospace;${bgStyle}">${life.dob||''} ${life.gender?'('+life.gender+')':''}</td>${cells}</tr>`;
  }).join('');

  // Notes section
  const notesHtml=noteGroups.length?`<div style="margin-top:16px;"><div style="font-size:12px;font-weight:700;color:#0d1f3c;text-transform:uppercase;letter-spacing:.5px;margin-bottom:10px;border-bottom:2px solid #0d1f3c;padding-bottom:4px;">Notes &amp; Red Flags</div>${noteGroups.map(g=>`<div style="margin-bottom:10px;background:#fef2f2;border:1px solid #fca5a5;border-radius:8px;padding:8px 12px;"><div style="font-size:12px;font-weight:800;color:#991b1b;margin-bottom:4px;">⚠ ${g.label}</div>${g.notes.map(n=>`<div style="font-size:11px;color:#7f1d1d;padding:2px 0 2px 8px;">• ${n}</div>`).join('')}</div>`).join('')}</div>`:'';

  previewEl.innerHTML=`
    <div style="overflow-x:auto;margin-bottom:16px;">
      <table style="width:100%;border-collapse:collapse;">
        <thead>
          <tr><th style="${th}min-width:110px;" rowspan="2">Policy</th><th style="${th}min-width:90px;" rowspan="2">Policy #</th><th style="${th}min-width:80px;" rowspan="2">Start date</th><th style="${th}min-width:130px;" rowspan="2">Plan name</th><th style="${th}min-width:90px;" rowspan="2">Type</th><th style="${th}min-width:75px;text-align:right;" rowspan="2">Premium</th><th colspan="7" style="${thBenef}">BENEFITS</th></tr>
          <tr><th style="${thC}min-width:70px;">Cashback</th><th style="${thC}min-width:70px;">Payment holiday</th><th style="${thC}min-width:70px;">No more premiums</th><th style="${thC}min-width:70px;">Accident cover</th><th style="${thC}min-width:55px;">Burial</th><th style="${thC}min-width:55px;">Paid up</th><th style="${th}min-width:100px;">Extra</th></tr>
        </thead>
        <tbody>${policyRows}</tbody>
        <tfoot><tr><td colspan="5" style="padding:6px 8px;border:1px solid #e5e7eb;text-align:right;font-weight:700;color:#0d1f3c;background:#f4f2ed;">TOTAL MONTHLY PREMIUM</td><td style="padding:6px 8px;border:1px solid #e5e7eb;text-align:right;font-weight:800;color:#c9922a;font-size:14px;background:#f4f2ed;">${_prFmtR(totalPremium)}</td><td colspan="7" style="border:1px solid #e5e7eb;background:#f4f2ed;"></td></tr></tfoot>
      </table>
    </div>
    <div style="overflow-x:auto;margin-bottom:4px;">
      <table style="width:100%;border-collapse:collapse;">
        <thead><tr><th style="${th}min-width:100px;">Relationship</th><th style="${th}min-width:140px;">Name</th><th style="${th}min-width:110px;">DOB (Gender)</th>${phCols}</tr></thead>
        <tbody>${livesRows}</tbody>
      </table>
    </div>
    <div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px;font-size:10px;font-weight:600;">
      <span style="background:#fff8e1;border:1px solid #fde68a;border-radius:6px;padding:3px 10px;">Yellow = no cover</span>
      <span style="background:#fee2e2;border:1px solid #fca5a5;border-radius:6px;padding:3px 10px;">Red = under R20 000</span>
      <span style="background:#dcfce7;border:1px solid #86efac;border-radius:6px;padding:3px 10px;">Green = R80 000 – R100 000</span>
      <span style="background:#fef3c7;border:1px solid #f59e0b;border-radius:6px;padding:3px 10px;">Amber = over R100 000</span>
    </div>
    ${notesHtml}`;
  _prCheckMissing();
}

function generatePRPdf(){
  if(!_prLoaFile){alert('LOA is required before generating a policy review.');return;}
  const policies=_prExtracted.filter(Boolean);
  if(!policies.length){alert('No policy data available. Please analyse documents first.');return;}
  const clientName=document.getElementById('prClientName').value.trim()||'[Client Name]';
  const clientId=document.getElementById('prClientId').value.trim()||'[ID Number]';
  const clientPhone=document.getElementById('prClientPhone').value.trim()||'—';
  const clientEmail=document.getElementById('prClientEmail').value.trim()||'—';
  const advisorNotes=document.getElementById('prAdvisorNotes').value.trim();
  const today=new Date().toLocaleDateString('en-ZA',{day:'2-digit',month:'long',year:'numeric'});
  const allLives=_prBuildLivesMap(policies);
  const totalPremium=policies.reduce((s,p)=>s+(p.premium||0),0);
  const noteGroups=_prPolicyNotesGroups(policies);
  const tick=v=>v?'&#10003;':'';

  const clientHdr=`<div class="client-grid"><div><div class="cl">Name</div><div class="cv">${clientName}</div></div><div><div class="cl">ID Number</div><div class="cv">${clientId}</div></div><div><div class="cl">Telephone</div><div class="cv">${clientPhone}</div></div><div><div class="cl">Email</div><div class="cv">${clientEmail}</div></div></div>`;
  const pageHdr=(pg,ttl)=>`<div class="hdr"><div><div class="pg-label">Page ${pg}</div><h1>Team Buffalos — Policy Review Summary</h1><div class="sub">Generated ${today} &nbsp;|&nbsp; LOA on file &nbsp;|&nbsp; ${clientName} (${clientId})</div></div><div style="font-size:11px;font-weight:700;color:#0d1f3c;background:#f4f2ed;padding:6px 12px;border-radius:8px;">${ttl}</div></div>`;
  const footer=`<div class="footer"><span>Team Buffalos &mdash; Policy Review &middot; ${today}</span><span>For internal use only. All figures must be verified against original policy documents.</span></div>`;

  // Page 1 — Policy summary
  const policyRows=policies.map((p,i)=>{
    const b=p.benefits||{};
    const arr=p.in_arrears?' <span style="color:#dc2626;font-weight:800;">&#9888; ARREARS</span>':'';
    const bg=i%2===0?'':'background:#f9f9f9;';
    return`<tr><td style="${bg}">${p.insurer||'—'}${arr}</td><td style="${bg}">${p.policy_number||'—'}</td><td style="${bg}">${p.start_date||'—'}</td><td style="${bg}">${p.plan_name||'—'}</td><td class="ctr" style="${bg}">${_prTypeBadge(p.policy_type,true)}</td><td class="num" style="${bg}">${_prFmtR(p.premium||0)}</td><td class="ctr" style="${bg}">${tick(b.cashback)}</td><td class="ctr" style="${bg}">${tick(b.payment_holiday)}</td><td class="ctr" style="${bg}">${tick(b.no_more_premiums)}</td><td class="ctr" style="${bg}">${b.accident_double?'&#10003;':''}</td><td class="ctr" style="${bg}">${tick(b.burial)}</td><td class="ctr" style="${bg}">${tick(b.paid_up)}</td><td style="${bg}font-size:8px;">${b.extra||'—'}</td></tr>`;
  }).join('');

  // Page 2 — Lives
  const phCols=policies.map((p,i)=>`<th class="ctr">${p.policy_number||'P'+(i+1)}</th>`).join('');
  const livesRows=allLives.map(life=>{
    const {bg:rowBg,label:rowLabel}=_prLiveBg(life);
    const bgStyle=rowBg?`background:${rowBg};`:'';
    const cells=policies.map((p,pIdx)=>{const c=life.policies[pIdx];return`<td class="ctr" style="${bgStyle}">${(c&&c>0)?'R '+c.toLocaleString('en-ZA'):''}</td>`;}).join('');
    const tag=rowLabel?` <span class="no-cover-badge">${rowLabel}</span>`:'';
    return`<tr><td style="${bgStyle}">${life.relationship}${tag}</td><td style="${bgStyle}">${life.name||''}</td><td style="${bgStyle}">${life.dob||''} ${life.gender?'('+life.gender+')':''}</td>${cells}</tr>`;
  }).join('');

  // Page 3 — Notes
  const notesPage3=noteGroups.map(g=>`<div class="note-group"><div class="note-group-title">&#9888; ${g.label}</div>${g.notes.map(n=>`<div class="note-item">&#8226; ${n}</div>`).join('')}</div>`).join('');
  const advisorBlock=advisorNotes?`<div class="notes-box"><div class="notes-title">Advisor Notes</div><div class="notes-body">${advisorNotes.replace(/\n/g,'<br>')}</div></div>`:'';
  const hasNotes=noteGroups.length||advisorNotes;

  const html=`<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Policy Review — ${clientName}</title>
<style>
*{box-sizing:border-box;margin:0;padding:0;}
body{font-family:Arial,sans-serif;font-size:9px;color:#1a1a2e;padding:14px 18px;}
.hdr{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:10px;border-bottom:2px solid #0d1f3c;padding-bottom:8px;}
.hdr h1{font-size:13px;font-weight:800;color:#0d1f3c;}
.hdr .sub{font-size:8px;color:#6b7280;margin-top:2px;}
.pg-label{font-size:8px;font-weight:700;color:#c9922a;text-transform:uppercase;letter-spacing:1px;margin-bottom:2px;}
.client-grid{display:grid;grid-template-columns:1fr 1fr;gap:3px 18px;font-size:9px;margin-bottom:10px;}
.cl{color:#6b7280;font-size:7px;font-weight:700;text-transform:uppercase;letter-spacing:.5px;}
.cv{font-size:10px;font-weight:700;color:#0d1f3c;}
.sec{font-size:9px;font-weight:800;color:#0d1f3c;text-transform:uppercase;letter-spacing:.5px;margin:10px 0 4px;border-bottom:1px solid #e5e7eb;padding-bottom:2px;}
table{width:100%;border-collapse:collapse;margin-bottom:12px;font-size:8px;}
th{background:#0d1f3c;color:#fff;padding:4px 5px;font-weight:700;text-align:left;white-space:nowrap;border:1px solid #1b3460;}
.th-benef{background:#1b3460;color:#f5d98b;text-align:center;border:1px solid #0d1f3c;font-size:7px;font-weight:700;letter-spacing:.3px;}
td{padding:3px 5px;border:1px solid #e5e7eb;vertical-align:middle;}
.ctr{text-align:center;}
.num{text-align:right;}
.gold{color:#c9922a;font-size:11px;font-weight:800;}
.no-cover-badge{background:#f59e0b;color:#fff;font-size:7px;font-weight:700;padding:1px 5px;border-radius:6px;margin-left:4px;}
.note-group{background:#fef2f2;border:1px solid #fca5a5;border-radius:5px;padding:6px 9px;margin-bottom:8px;}
.note-group-title{font-weight:800;color:#991b1b;font-size:9px;margin-bottom:3px;}
.note-item{font-size:8px;color:#7f1d1d;padding:1px 0 1px 6px;}
.notes-box{background:#f0f9ff;border:1px solid #bae6fd;border-radius:5px;padding:7px 9px;margin-bottom:8px;}
.notes-title{font-weight:700;color:#075985;font-size:9px;margin-bottom:3px;}
.notes-body{font-size:9px;color:#0d1f3c;line-height:1.6;}
.footer{margin-top:10px;border-top:1px solid #e5e7eb;padding-top:5px;font-size:7px;color:#9ca3af;display:flex;justify-content:space-between;}
.page-break{page-break-before:always;padding-top:14px;}
@media print{body{padding:8px 12px;}@page{margin:10mm;size:A4 landscape;}}
*{-webkit-print-color-adjust:exact!important;print-color-adjust:exact!important;}
</style></head><body>

<!-- PAGE 1: POLICY SUMMARY -->
${pageHdr(1,'Policy Summary')}
${clientHdr}
<div class="sec">Policy Summary</div>
<table>
  <thead>
    <tr><th rowspan="2">Policy</th><th rowspan="2">Policy #</th><th rowspan="2">Start date</th><th rowspan="2">Plan name</th><th rowspan="2" class="ctr">Type</th><th rowspan="2" class="num">Premium</th><th colspan="7" class="th-benef">BENEFITS</th></tr>
    <tr><th class="ctr">Cashback</th><th class="ctr">Payment holiday</th><th class="ctr">No more premiums</th><th class="ctr">Accident cover</th><th class="ctr">Burial</th><th class="ctr">Paid up</th><th>Extra</th></tr>
  </thead>
  <tbody>${policyRows}</tbody>
  <tfoot><tr><td colspan="5" style="text-align:right;font-weight:700;color:#0d1f3c;background:#f4f2ed;">TOTAL MONTHLY PREMIUM</td><td class="num gold" style="background:#f4f2ed;">${_prFmtR(totalPremium)}</td><td colspan="7" style="background:#f4f2ed;"></td></tr></tfoot>
</table>
${footer}

<!-- PAGE 2: LIVES -->
<div class="page-break">
${pageHdr(2,'Lives &amp; Cover')}
${clientHdr}
<div class="sec">Lives Assured &amp; Cover per Policy</div>
<table>
  <thead><tr><th>Relationship</th><th>Name</th><th>DOB (Gender)</th>${phCols}</tr></thead>
  <tbody>${livesRows}</tbody>
</table>
<div style="display:flex;gap:6px;flex-wrap:wrap;font-size:8px;font-weight:700;">
  <span style="background:#fff8e1;border:1px solid #fde68a;border-radius:4px;padding:2px 8px;">Yellow = no cover</span>
  <span style="background:#fee2e2;border:1px solid #fca5a5;border-radius:4px;padding:2px 8px;">Red = under R20 000</span>
  <span style="background:#dcfce7;border:1px solid #86efac;border-radius:4px;padding:2px 8px;">Green = R80 000&ndash;R100 000</span>
  <span style="background:#fef3c7;border:1px solid #f59e0b;border-radius:4px;padding:2px 8px;">Amber = over R100 000</span>
</div>
${footer}
</div>

<!-- PAGE 3: NOTES (only if there are notes) -->
${hasNotes?`<div class="page-break">
${pageHdr(3,'Notes &amp; Advisor Comments')}
${clientHdr}
${noteGroups.length?`<div class="sec">Red Flags &amp; System Notes</div>${notesPage3}`:''}
${advisorNotes?`<div class="sec">Advisor Notes</div>${advisorBlock}`:''}
${footer}
</div>`:''}

<script>window.onload=()=>{window.print();}<\/script>
</body></html>`;
  const w=window.open('','_blank');
  if(w){w.document.write(html);w.document.close();}
  else alert('Please allow pop-ups to generate the PDF.');
}

function clearPolicyReview(){
  _prLoaFile=null;_prDocFiles=[];_prExtracted=[];
  const loaInput=document.getElementById('prLoaInput');if(loaInput)loaInput.value='';
  const loaStatus=document.getElementById('prLoaStatus');if(loaStatus)loaStatus.innerHTML='';
  const loaZone=document.getElementById('prLoaZone');if(loaZone){loaZone.style.borderColor='#bae6fd';loaZone.style.background='#fff';}
  const note=document.getElementById('prLoaRequiredNote');if(note)note.style.display='flex';
  const docInput=document.getElementById('prDocInput');if(docInput)docInput.value='';
  renderPRDocList();
  const sec=document.getElementById('prSummarySection');if(sec)sec.style.display='none';
  const warn=document.getElementById('prMissingWarning');if(warn)warn.style.display='none';
  const notes=document.getElementById('prAdvisorNotes');if(notes)notes.value='';
  updatePRButtons();
}
async function savePRReview(){
  const policies=_prExtracted.filter(Boolean);
  if(!policies.length){showAlert('No policy data to save — please analyse documents first.','error');return;}
  const clientName=document.getElementById('prClientName').value.trim()||'[Client Name]';
  const clientId=document.getElementById('prClientId').value.trim()||'';
  const clientPhone=document.getElementById('prClientPhone').value.trim()||'';
  const clientEmail=document.getElementById('prClientEmail').value.trim()||'';
  const advisorNotes=document.getElementById('prAdvisorNotes').value.trim()||'';
  const advisorCode=currentUser?.code||'';
  const advisorName=currentUser?.name||'';
  const totalPremium=policies.reduce((s,p)=>s+(p.premium||0),0);
  const data={clientName,clientId,clientPhone,clientEmail,advisorNotes,advisorCode,advisorName,totalPremium,policyCount:policies.length,policies};
  const btn=document.getElementById('prSaveBtn');
  if(btn){btn.disabled=true;btn.textContent='Saving…';}
  try{
    if(window.FB_READY&&window.FB.savePolicyReview){
      await window.FB.savePolicyReview(data);
    }
    showAlert('Review saved for '+clientName,'success');
    renderPRSavedList();
  }catch(e){
    showAlert('Save failed: '+(e.message||'Unknown error'),'error');
  }finally{
    if(btn){btn.textContent='💾 Save Review';updatePRButtons();}
  }
}

async function renderPRSavedList(){
  const el=document.getElementById('prSavedList');
  if(!el)return;
  el.style.display='block';
  el.innerHTML='<div style="padding:10px 12px;color:#6b7280;font-size:13px;">Loading saved reviews…</div>';
  let reviews=[];
  try{
    if(window.FB_READY&&window.FB.getPolicyReviews)reviews=await window.FB.getPolicyReviews();
  }catch(e){
    el.innerHTML='<div style="padding:10px 12px;color:#dc2626;font-size:13px;">Could not load saved reviews.</div>';
    return;
  }
  const isManager=currentUser&&(currentUser.isManager||currentUser.isOps);
  if(!isManager)reviews=reviews.filter(r=>r.advisorCode===currentUser?.code);
  window._prSavedReviews=reviews;
  if(!reviews.length){el.innerHTML='<div style="padding:10px 12px;color:#6b7280;font-size:13px;">No saved reviews yet.</div>';return;}
  el.innerHTML=reviews.map(r=>{
    const date=r.savedAt?.toDate?(r.savedAt.toDate().toLocaleDateString('en-ZA',{day:'2-digit',month:'short',year:'numeric'})):(r.savedAt?new Date(r.savedAt).toLocaleDateString('en-ZA',{day:'2-digit',month:'short',year:'numeric'}):'Unknown date');
    const total=r.totalPremium?'R '+r.totalPremium.toLocaleString('en-ZA'):'—';
    return`<div style="padding:10px 14px;border-bottom:1px solid #f3f4f6;display:flex;align-items:center;gap:10px;flex-wrap:wrap;">
      <div style="flex:1;min-width:0;">
        <div style="font-weight:700;font-size:13px;color:#0d1f3c;">${r.clientName||'[Unknown]'}</div>
        <div style="font-size:11px;color:#6b7280;margin-top:2px;">${date} &nbsp;·&nbsp; ${r.policyCount||0} polic${r.policyCount===1?'y':'ies'} &nbsp;·&nbsp; ${total}/month${isManager&&r.advisorName?' &nbsp;·&nbsp; '+r.advisorName:''}</div>
      </div>
      <button onclick="_openSavedPRReview('${r.id}')" style="flex-shrink:0;padding:6px 14px;background:#0d1f3c;color:#fff;border:none;border-radius:8px;font-size:12px;font-weight:700;cursor:pointer;">Open</button>
      <button onclick="_deleteSavedPRReview('${r.id}')" style="flex-shrink:0;padding:6px 10px;background:#fee2e2;color:#dc2626;border:none;border-radius:8px;font-size:12px;font-weight:700;cursor:pointer;">🗑</button>
    </div>`;
  }).join('');
}

function _openSavedPRReview(id){
  const r=(window._prSavedReviews||[]).find(x=>x.id===id);
  if(!r)return;
  const date=r.savedAt?.toDate?(r.savedAt.toDate().toLocaleDateString('en-ZA',{day:'2-digit',month:'long',year:'numeric'})):(r.savedAt?new Date(r.savedAt).toLocaleDateString('en-ZA',{day:'2-digit',month:'long',year:'numeric'}):'Unknown date');
  const policies=(r.policies||[]).filter(Boolean);
  const policyRows=policies.map((p,i)=>{
    const bg=i%2===0?'#fff':'#f9f9f9';
    return`<tr style="background:${bg}"><td style="padding:6px 8px;border:1px solid #e5e7eb;">${p.insurer||'—'}</td><td style="padding:6px 8px;border:1px solid #e5e7eb;">${p.policy_number||'—'}</td><td style="padding:6px 8px;border:1px solid #e5e7eb;">${p.plan_name||'—'}</td><td style="padding:6px 8px;border:1px solid #e5e7eb;text-align:right;">${p.premium?'R '+p.premium.toLocaleString('en-ZA'):'—'}</td></tr>`;
  }).join('');
  const total=r.totalPremium?'R '+r.totalPremium.toLocaleString('en-ZA'):'—';

  let ov=document.getElementById('_prOpenModalOverlay');
  if(!ov){ov=document.createElement('div');ov.id='_prOpenModalOverlay';document.body.appendChild(ov);}
  ov.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:9999;display:flex;align-items:flex-start;justify-content:center;padding:20px 12px;overflow-y:auto;';
  ov.innerHTML=`<div style="background:#fff;border-radius:16px;width:100%;max-width:540px;box-shadow:0 8px 40px rgba(0,0,0,.25);overflow:hidden;">
    <div style="background:#0d1f3c;color:#fff;padding:14px 16px;display:flex;align-items:center;justify-content:space-between;">
      <div><div style="font-weight:800;font-size:15px;">${r.clientName||'[Client]'}</div><div style="font-size:11px;opacity:.7;margin-top:2px;">Saved ${date}${r.advisorName?' &nbsp;·&nbsp; '+r.advisorName:''}</div></div>
      <button onclick="document.getElementById('_prOpenModalOverlay').style.display='none'" style="background:none;border:none;color:#fff;font-size:20px;cursor:pointer;line-height:1;">✕</button>
    </div>
    <div style="padding:14px 16px;">
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:6px 14px;font-size:12px;margin-bottom:14px;">
        ${r.clientId?`<div><div style="color:#9ca3af;font-size:10px;font-weight:700;text-transform:uppercase;">ID Number</div><div style="font-weight:700;color:#0d1f3c;">${r.clientId}</div></div>`:''}
        ${r.clientPhone?`<div><div style="color:#9ca3af;font-size:10px;font-weight:700;text-transform:uppercase;">Phone</div><div style="font-weight:700;">${r.clientPhone}</div></div>`:''}
        ${r.clientEmail?`<div><div style="color:#9ca3af;font-size:10px;font-weight:700;text-transform:uppercase;">Email</div><div style="font-weight:700;">${r.clientEmail}</div></div>`:''}
      </div>
      ${policies.length?`<div style="font-size:11px;font-weight:800;color:#0d1f3c;text-transform:uppercase;letter-spacing:.5px;margin-bottom:6px;">Policies (${policies.length})</div>
      <table style="width:100%;border-collapse:collapse;font-size:12px;margin-bottom:12px;">
        <thead><tr style="background:#0d1f3c;color:#fff;"><th style="padding:6px 8px;text-align:left;font-weight:700;">Insurer</th><th style="padding:6px 8px;text-align:left;font-weight:700;">Policy #</th><th style="padding:6px 8px;text-align:left;font-weight:700;">Plan</th><th style="padding:6px 8px;text-align:right;font-weight:700;">Premium</th></tr></thead>
        <tbody>${policyRows}</tbody>
        <tfoot><tr style="background:#f4f2ed;"><td colspan="3" style="padding:6px 8px;font-weight:700;text-align:right;border:1px solid #e5e7eb;">Total</td><td style="padding:6px 8px;font-weight:800;color:#c9922a;text-align:right;border:1px solid #e5e7eb;">${total}/month</td></tr></tfoot>
      </table>`:'<div style="color:#9ca3af;font-size:13px;margin-bottom:12px;">No policy data stored.</div>'}
      ${r.advisorNotes?`<div style="background:#f0f9ff;border:1px solid #bae6fd;border-radius:8px;padding:10px 12px;margin-bottom:12px;"><div style="font-size:10px;font-weight:800;color:#075985;text-transform:uppercase;letter-spacing:.5px;margin-bottom:4px;">Advisor Notes</div><div style="font-size:12px;color:#0d1f3c;line-height:1.6;">${r.advisorNotes.replace(/\n/g,'<br>')}</div></div>`:''}
      <div style="display:flex;gap:10px;">
        <button onclick="_generatePdfFromSaved('${id}')" style="flex:1;padding:10px;background:#c9922a;color:#fff;border:none;border-radius:10px;font-size:13px;font-weight:700;cursor:pointer;">Generate PDF</button>
        <button onclick="document.getElementById('_prOpenModalOverlay').style.display='none'" style="flex:1;padding:10px;background:#f4f2ed;color:#374151;border:none;border-radius:10px;font-size:13px;font-weight:700;cursor:pointer;">Close</button>
      </div>
    </div>
  </div>`;
  ov.onclick=e=>{if(e.target===ov)ov.style.display='none';};
}

function _generatePdfFromSaved(id){
  const r=(window._prSavedReviews||[]).find(x=>x.id===id);
  if(!r)return;
  // Temporarily restore state so generatePRPdf can run
  _prExtracted=(r.policies||[]).filter(Boolean);
  _prLoaFile={name:'LOA on file (saved)'};
  const fill=(eid,v)=>{const el=document.getElementById(eid);if(el)el.value=v||'';};
  fill('prClientName',r.clientName);fill('prClientId',r.clientId);
  fill('prClientPhone',r.clientPhone);fill('prClientEmail',r.clientEmail);
  fill('prAdvisorNotes',r.advisorNotes);
  generatePRPdf();
}
async function _deleteSavedPRReview(id){
  if(!confirm('Delete this saved review? This cannot be undone.'))return;
  try{
    if(window.FB_READY&&window.FB.deletePolicyReview)await window.FB.deletePolicyReview(id);
    window._prSavedReviews=(window._prSavedReviews||[]).filter(x=>x.id!==id);
    showAlert('Review deleted.','success');
    renderPRSavedList();
  }catch(e){showAlert('Delete failed: '+(e.message||'Unknown error'),'error');}
}
// ── END POLICY REVIEW ──────────────────────────────────────────────────────


// ── REFERRAL TRACKER ────────────────────────────────────────────────────────
function getReferrals(){try{return JSON.parse(localStorage.getItem('tl_referrals')||'[]');}catch(e){return[];}}
function saveReferrals(d){localStorage.setItem('tl_referrals',JSON.stringify(d));}
const REF_STATUS_LABELS={pipeline:'In pipeline',contacted:'Contacted',converted:'Converted',lost:'Lost'};
function _fmtContactDT(dt){
  if(!dt)return'';
  try{const d=new Date(dt);return d.toLocaleDateString('en-ZA',{day:'2-digit',month:'short',year:'numeric'})+' '+d.toLocaleTimeString('en-ZA',{hour:'2-digit',minute:'2-digit'});}catch(e){return dt;}
}
function _refContactLog(r){
  const contacts=r.contacts||[];
  const entries=contacts.map((c,i)=>`<div style="display:flex;align-items:flex-start;gap:6px;margin-bottom:4px;"><div style="flex:1;background:#f8f7f4;border-radius:6px;padding:5px 8px;"><div style="font-size:10px;color:#6b7280;font-weight:600;">${_fmtContactDT(c.datetime)}</div><div style="font-size:12px;color:#374151;margin-top:2px;">${(c.notes||'').replace(/</g,'&lt;')}</div></div><button onclick="refDeleteContact('${r.id}',${i})" style="background:none;border:none;color:#d1d5db;cursor:pointer;font-size:12px;padding:2px 4px;flex-shrink:0;">✕</button></div>`).join('');
  const now=new Date().toISOString().slice(0,16);
  return`<div style="margin-top:8px;padding-top:8px;border-top:1px dashed #e5e7eb;">${entries}<div style="display:flex;gap:6px;align-items:center;margin-top:${contacts.length?'6':'0'}px;"><input type="datetime-local" id="refDT_${r.id}" style="font-size:11px;padding:4px 6px;border:1px solid #e5e7eb;border-radius:6px;max-width:160px;flex-shrink:0;" value="${now}"/><input type="text" id="refNote_${r.id}" placeholder="Contact note..." style="flex:1;font-size:12px;padding:4px 8px;border:1px solid #e5e7eb;border-radius:6px;background:#f9f9f9;min-width:0;"/><button onclick="refLogContact('${r.id}')" style="font-size:11px;font-weight:700;background:#0d1f3c;color:#fff;border:none;border-radius:6px;padding:5px 10px;cursor:pointer;white-space:nowrap;flex-shrink:0;">+ Log</button></div></div>`;
}
function refLogContact(id){
  const dt=document.getElementById('refDT_'+id)?.value;
  const note=(document.getElementById('refNote_'+id)?.value||'').trim();
  if(!note)return showAlert('Please enter a note before logging a contact.','error');
  const refs=getReferrals();const r=refs.find(x=>x.id===id);if(!r)return;
  if(!r.contacts)r.contacts=[];
  r.contacts.push({datetime:dt||new Date().toISOString(),notes:note});
  saveReferrals(refs);renderReferrals();
}
function refDeleteContact(refId,idx){
  const refs=getReferrals();const r=refs.find(x=>x.id===refId);if(!r||!r.contacts)return;
  r.contacts.splice(idx,1);saveReferrals(refs);renderReferrals();
}
function refAdd(){
  const by=document.getElementById('ref-by').value.trim();
  const name=document.getElementById('ref-name').value.trim();
  const facility=document.getElementById('ref-facility').value.trim();
  const phone=document.getElementById('ref-phone').value.trim();
  const relation=document.getElementById('ref-relation').value;
  if(!by||!name||!facility)return showAlert('Please fill in all referral fields.','error');
  const refs=getReferrals();
  refs.unshift({id:Date.now()+'_'+Math.random().toString(36).slice(2),referredBy:by,name,phone,facility,relation,status:'pipeline',advisorCode:currentUser.code,createdAt:new Date().toISOString()});
  saveReferrals(refs);
  ['ref-by','ref-name','ref-facility','ref-phone'].forEach(id=>{const el=document.getElementById(id);if(el)el.value='';});
  renderReferrals();
}
function refSetStatus(id,status){
  const refs=getReferrals();const r=refs.find(x=>x.id===id);if(!r)return;
  r.status=status;saveReferrals(refs);renderReferrals();
}
function refDelete(id){
  if(!confirm('Remove this referral?'))return;
  saveReferrals(getReferrals().filter(x=>x.id!==id));renderReferrals();
}
function _refAge(r){
  if(!r.createdAt||r.status==='converted'||r.status==='lost')return'';
  const days=Math.floor((Date.now()-new Date(r.createdAt).getTime())/86400000);
  if(days<7)return'';
  const warn=days>=14;
  return`<span style="font-size:10px;font-weight:700;padding:2px 7px;border-radius:8px;background:${warn?'#fef2f2':'#fffbeb'};color:${warn?'#dc2626':'#d97706'};border:1px solid ${warn?'#fca5a5':'#fde68a'};margin-left:6px;">${days}d in pipeline</span>`;
}
function renderReferrals(){
  const isOps=currentUser&&(currentUser.isOps||currentUser.isManager);
  let refs=getReferrals();
  if(!isOps)refs=refs.filter(r=>r.advisorCode===currentUser.code);
  // stats
  const statsEl=document.getElementById('refStats');
  if(statsEl){
    const total=refs.length;const conv=refs.filter(r=>r.status==='converted').length;const pipe=refs.filter(r=>r.status==='pipeline').length;
    statsEl.innerHTML=[
      {label:'Total referrals',val:total,col:'#0d1f3c'},
      {label:'Converted',val:conv,col:'#16a34a'},
      {label:'In pipeline',val:pipe,col:'#d97706'},
    ].map(s=>`<div style="background:#fff;border:1px solid #e8e4db;border-radius:12px;padding:12px;text-align:center;"><div style="font-size:22px;font-weight:800;color:${s.col};">${s.val}</div><div style="font-size:10px;color:#9ca3af;font-weight:700;text-transform:uppercase;letter-spacing:.5px;">${s.label}</div></div>`).join('');
  }
  const el=document.getElementById('refList');if(!el)return;
  if(!refs.length){el.innerHTML='<div style="text-align:center;color:#9ca3af;font-size:13px;padding:2rem;">No referrals logged yet — add your first referral above.</div>';return;}
  // group by referredBy
  const byClient={};refs.forEach(r=>{if(!byClient[r.referredBy])byClient[r.referredBy]=[];byClient[r.referredBy].push(r);});
  el.innerHTML=Object.entries(byClient).map(([client,list])=>{
    const count=list.length;const colBadge=count>=2?'#dcfce7':'#fef9ec';const colTxt=count>=2?'#166534':'#92400e';
    return`<div class="full-card" style="margin-bottom:12px;padding:0;overflow:hidden;">
      <div style="padding:10px 16px;background:#f8f7f4;display:flex;align-items:center;justify-content:space-between;">
        <div style="font-size:13px;font-weight:700;color:#0d1f3c;">From: ${client}</div>
        <div style="background:${colBadge};color:${colTxt};font-size:10px;font-weight:700;padding:3px 10px;border-radius:20px;">${count} referral${count!==1?'s':''} ${count>=2?'✓':''}</div>
      </div>
      ${list.map(r=>`<div style="padding:10px 16px;border-top:1px solid #f4f2ed;">
        <div style="display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:6px;">
          <div><div style="font-size:13px;font-weight:700;color:#0d1f3c;">${r.name}${_refAge(r)}</div><div style="font-size:11px;color:#6b7280;">${r.facility} · ${r.relation}${r.phone?` · <a href="tel:${r.phone}" style="color:#c9922a;text-decoration:none;">${r.phone}</a>`:''}</div></div>
          <div style="display:flex;align-items:center;gap:6px;">
            <select onchange="refSetStatus('${r.id}',this.value)" style="font-size:11px;padding:4px 6px;border:1px solid #e5e7eb;border-radius:6px;background:#f9f9f9;">
              ${Object.entries(REF_STATUS_LABELS).map(([v,l])=>`<option value="${v}"${r.status===v?' selected':''}>${l}</option>`).join('')}
            </select>
            <button onclick="refDelete('${r.id}')" style="background:none;border:none;color:#9ca3af;cursor:pointer;font-size:14px;">✕</button>
          </div>
        </div>
        ${_refContactLog(r)}
      </div>`).join('')}
    </div>`;
  }).join('');
}
// ── END REFERRAL TRACKER ────────────────────────────────────────────────────

// ── MERGE DOCS & SIGNATURE ───────────────────────────────────────────────────
let _mdFiles=[];
let _mdCropState=null;

/* ── APP CHECKS ── */
const AC_STATUSES={
  pending_approval:'Pending Approval',attention_needed:'Attention Needed',
  pending_spotcheck:'Pending Spotcheck',spotcheck:'Spotcheck',
  checklist:'Checklist',approved:'Approved',rejected:'Rejected',debicheck:'DebiCheck',
};
const MONTHS_LONG=['January','February','March','April','May','June','July','August','September','October','November','December'];

let _acMonth=null;
let _acEditId=null;
let _acDetailId=null;
// pill/tri selection state for the form
const _acPills={};   // groupName -> value
const _acTris={};    // groupName -> value
let _acPolicies=[];  // [{number,premium,company,schedUploaded,cxlPack,soMandate}]
let _acCollType='';  // 'gov_qlink'|'debicheck'|'muni'
let _acSearch='';
let _acFilterTag=''; // ''|'passed'|'attention'|'pending_docs'

function acMonthKey(d){return d.getFullYear()+'-'+(''+(d.getMonth()+1)).padStart(2,'0');}
function acMonthLabel(k){const[y,m]=k.split('-');return MONTHS_LONG[+m-1]+' '+y+' Production';}
function acGetCases(month){try{return JSON.parse(localStorage.getItem('tl_appchecks_'+month)||'[]');}catch(e){return[];}}
function acSaveCases(month,cases){localStorage.setItem('tl_appchecks_'+month,JSON.stringify(cases));}

function renderAppChecks(){
  if(!_acMonth)_acMonth=acMonthKey(new Date());
  document.getElementById('acMonthLabel').textContent=acMonthLabel(_acMonth);
  acRenderDraftBanner();
  acRenderCaseList();
}

// ── DRAFT ──
const AC_DRAFT_KEY='tl_acDraft';

function acGetDraft(){try{return JSON.parse(localStorage.getItem(AC_DRAFT_KEY)||'null');}catch(e){return null;}}
function acClearDraft(){localStorage.removeItem(AC_DRAFT_KEY);}

function acCaptureDraftState(){
  return {
    editId:_acEditId,
    month:_acMonth,
    caseType:document.querySelector('.ac-type-btn.active')?.dataset?.type||'replacement',
    collectionType:_acCollType,
    clientName:document.getElementById('ac_clientName')?.value||'',
    advisor:document.getElementById('ac_advisor')?.value||'',
    pills:{..._acPills},
    tris:{..._acTris},
    policies:_acPolicies.map(p=>({...p})),
    numAioCxl:document.getElementById('ac_aioCxl')?.value||'',
    affordFailed:!!document.getElementById('ac_affordFailed')?.checked,
    affordRetry:!!document.getElementById('ac_affordRetry')?.checked,
    highPrem:!!document.getElementById('ac_highPrem')?.checked,
    expenses:!!document.getElementById('ac_expenses')?.checked,
    qlinkAffordable:!!document.getElementById('ac_qlinkAffordable')?.checked,
    discEmail:!!document.getElementById('ac_discEmail')?.checked,
    compEmail:!!document.getElementById('ac_compEmail')?.checked,
    licenseExpiry:document.getElementById('ac_licenseExpiry')?.value||'',
    bankStatDate:document.getElementById('ac_bankStatDate')?.value||'',
    payslipDate:document.getElementById('ac_payslipDate')?.value||'',
    suppNotes:document.getElementById('ac_suppNotes')?.value||'',
    caseNotes:document.getElementById('ac_caseNotes')?.value||'',
    afterRep:document.querySelector('input[name="ac_afterRep"]:checked')?.value||'',
    qlSalary:document.getElementById('acql_salary')?.value||'',
    qlNewPremium:document.getElementById('acql_newpremium')?.value||'0',
    qlDeductions:_acQlDeductions.map(d=>({...d})),
    qlSkyPolicies:_acQlSkyPolicies.map(p=>({...p})),
    qlNotes:document.getElementById('ac_qlNotes')?.value||'',
    savedAt:new Date().toISOString(),
  };
}

function acSaveDraftAndExit(){
  const draft=acCaptureDraftState();
  if(!draft.clientName&&!draft.qlSalary&&!draft.policies.length&&!draft.qlDeductions.length){
    acCloseForm();return; // nothing worth saving
  }
  localStorage.setItem(AC_DRAFT_KEY,JSON.stringify(draft));
  acCloseForm();
  acRenderDraftBanner();
}

function acRenderDraftBanner(){
  const banner=document.getElementById('acDraftBanner');if(!banner)return;
  const draft=acGetDraft();
  if(!draft){banner.style.display='none';return;}
  const ago=acDraftAgo(draft.savedAt);
  const name=draft.clientName||'untitled case';
  banner.style.display='block';
  banner.innerHTML=`<div style="background:#fef9ec;border:1px solid #f5d98b;border-radius:12px;padding:12px 14px;">
    <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:8px;">
      <div>
        <div style="font-size:13px;font-weight:700;color:#92400e;">📝 Draft in progress</div>
        <div style="font-size:12px;color:#78350f;margin-top:2px;"><strong>${name}</strong>${draft.advisor?' · '+draft.advisor:''}</div>
        <div style="font-size:11px;color:#b45309;margin-top:1px;">Saved ${ago}</div>
      </div>
    </div>
    <div style="display:flex;gap:8px;margin-top:10px;">
      <button onclick="acContinueDraft()" style="flex:1;background:#c9922a;color:#fff;border:none;border-radius:9px;padding:9px;font-size:13px;font-weight:700;cursor:pointer;">▶ Continue</button>
      <button onclick="acDiscardDraft()" style="background:#f3f4f6;color:#374151;border:1px solid #e5e7eb;border-radius:9px;padding:9px 14px;font-size:12px;font-weight:700;cursor:pointer;">🗑 Discard</button>
    </div>
  </div>`;
}

function acDraftAgo(iso){
  if(!iso)return'';
  const diff=Math.round((Date.now()-new Date(iso).getTime())/1000);
  if(diff<60)return'just now';
  if(diff<3600)return Math.floor(diff/60)+' min ago';
  if(diff<86400)return Math.floor(diff/3600)+' hr ago';
  return Math.floor(diff/86400)+' day(s) ago';
}

function acContinueDraft(){
  const draft=acGetDraft();if(!draft)return;
  // If the draft is for a different month, switch to it
  if(draft.month)_acMonth=draft.month;
  // Open the form fresh (resets state)
  _acEditId=draft.editId||null;
  acOpenForm(_acEditId); // resets everything first
  // Then restore the draft state on top
  requestAnimationFrame(()=>acRestoreDraftState(draft));
}

function acRestoreDraftState(d){
  // Case type
  document.querySelectorAll('.ac-type-btn').forEach(b=>b.classList.toggle('active',b.dataset.type===d.caseType));
  document.getElementById('ac_repDocRows').style.display=(d.caseType==='replacement'||d.caseType==='both')?'block':'none';
  _acCollType=d.collectionType||'';
  document.querySelectorAll('[data-ctype]').forEach(b=>b.classList.toggle('active',b.dataset.ctype===_acCollType));
  // Basic fields
  const set=(id,v)=>{const el=document.getElementById(id);if(el)el.value=v||'';};
  set('ac_clientName',d.clientName);set('ac_advisor',d.advisor);
  set('ac_aioCxl',d.numAioCxl);set('ac_licenseExpiry',d.licenseExpiry);
  set('ac_bankStatDate',d.bankStatDate);set('ac_payslipDate',d.payslipDate);
  set('ac_suppNotes',d.suppNotes);set('ac_caseNotes',d.caseNotes);
  set('ac_qlNotes',d.qlNotes);
  // Checkboxes
  const chk=(id,v)=>{const el=document.getElementById(id);if(el)el.checked=!!v;};
  chk('ac_affordFailed',d.affordFailed);chk('ac_affordRetry',d.affordRetry);
  chk('ac_highPrem',d.highPrem);chk('ac_expenses',d.expenses);chk('ac_qlinkAffordable',d.qlinkAffordable);
  chk('ac_discEmail',d.discEmail);chk('ac_compEmail',d.compEmail);
  // Pills
  Object.entries(d.pills||{}).forEach(([g,v])=>{
    _acPills[g]=v;
    document.querySelectorAll(`[data-g="${g}"]`).forEach(b=>b.classList.toggle('active',b.dataset.v===v));
  });
  // Show risk row if needed
  if(d.pills?.cv==='completed')document.getElementById('ac_riskRow').style.display='block';
  // License expiry row
  if(d.pills?.idType==='license')document.getElementById('ac_licenseExpiryRow').style.display='block';
  // Tris
  Object.entries(d.tris||{}).forEach(([g,v])=>{
    _acTris[g]=v;
    document.querySelectorAll(`[data-g="${g}"].ac-tri`).forEach(b=>{b.className='ac-tri'+(b.dataset.v===v?` sel-${v}`:'');});
  });
  // Policies
  _acPolicies=(d.policies||[]).map(p=>({...p}));acRenderPolicies();
  // After replacement radio
  if(d.afterRep)document.querySelectorAll('input[name="ac_afterRep"]').forEach(r=>{r.checked=r.value===d.afterRep;});
  // Qlink calculator
  _acQlDeductions=(d.qlDeductions||[]).map(x=>({...x}));
  _acQlSkyPolicies=(d.qlSkyPolicies||[]).map(x=>({...x}));
  const sal=document.getElementById('acql_salary');if(sal)sal.value=d.qlSalary||'';
  const np=document.getElementById('acql_newpremium');if(np)np.value=d.qlNewPremium||'0';
  acQlinkRenderDeductions();acQlinkRenderSkyPolicies();acQlinkCalc_();
  // Validate dates
  acCheckDoc('bankStatDate','ac_bankStatWarn');acCheckDoc('payslipDate','ac_payslipWarn');
  if(d.licenseExpiry)acCheckLicense();
}

function acDiscardDraft(){
  if(!confirm('Discard the saved draft? This cannot be undone.'))return;
  acClearDraft();acRenderDraftBanner();
}

function acNavMonth(dir){
  const[y,m]=_acMonth.split('-').map(Number);
  const d=new Date(y,m-1+dir,1);
  _acMonth=acMonthKey(d);
  _acSearch='';_acFilterTag='';
  const si=document.getElementById('acSearchInput');if(si)si.value='';
  document.getElementById('acMonthLabel').textContent=acMonthLabel(_acMonth);
  acRenderCaseList();
}

function acApplyFilters(cases){
  return cases.filter(c=>{
    if(_acSearch){
      const q=_acSearch.trim();
      if(!(c.clientName||'').toLowerCase().includes(q)&&!(c.advisor||'').toLowerCase().includes(q))return false;
    }
    if(_acFilterTag==='passed'&&!c.overallPass)return false;
    if(_acFilterTag==='attention'&&c.overallPass)return false;
    if(_acFilterTag==='pending_docs'&&!acGetAlertList(c).some(a=>a.includes('pending')))return false;
    return true;
  });
}
function acRenderCaseList(){
  const allCases=acGetCases(_acMonth);
  const total=allCases.length,passed=allCases.filter(c=>c.overallPass).length,
        flagged=allCases.filter(c=>!c.overallPass).length,dc=allCases.filter(c=>c.status==='debicheck').length;
  const cxlOut=allCases.reduce((n,c)=>n+(c.policies||[]).filter(p=>(p.status||'replace')==='replace'&&!p.cxlPack).length,0);
  const schedOut=allCases.reduce((n,c)=>n+(c.policies||[]).filter(p=>(p.status||'replace')==='replace'&&!p.schedUploaded).length,0);
  document.getElementById('acStats').innerHTML=[
    {l:'Total',v:total,c:'#0d1f3c'},{l:'\u2705 Passed',v:passed,c:'#16a34a'},
    {l:'\u26a0\ufe0f Attention',v:flagged,c:'#d97706'},{l:'DebiCheck',v:dc,c:'#7c3aed'},
    {l:'\ud83d\udce6 CXL out',v:cxlOut,c:cxlOut>0?'#dc2626':'#16a34a'},{l:'\ud83d\udcc1 Sched out',v:schedOut,c:schedOut>0?'#dc2626':'#16a34a'}
  ].map(s=>`<div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;padding:8px;text-align:center;"><div style="font-size:18px;font-weight:800;color:${s.c};">${s.v}</div><div style="font-size:10px;color:#6b7280;font-weight:600;">${s.l}</div></div>`).join('');
  const _chips=[{v:'',l:'All'},{v:'passed',l:'\u2705 Passed'},{v:'attention',l:'\u274c Attention'},{v:'pending_docs',l:'\ud83d\udcc1 Docs pending'}];
  const chipEl=document.getElementById('acFilterChips');
  if(chipEl)chipEl.innerHTML=_chips.map(f=>`<button onclick="_acFilterTag='${f.v}';acRenderCaseList();" style="font-size:11px;font-weight:700;padding:5px 13px;border-radius:20px;border:1px solid ${_acFilterTag===f.v?'#0d1f3c':'#e5e7eb'};background:${_acFilterTag===f.v?'#0d1f3c':'#f9fafb'};color:${_acFilterTag===f.v?'#fff':'#6b7280'};cursor:pointer;white-space:nowrap;">${f.l}</button>`).join('');
  const cases=acApplyFilters(allCases);
  const hasFilter=!!(_acSearch||_acFilterTag);
  const reps=cases.filter(c=>c.caseType==='replacement'||c.caseType==='both');
  const newb=cases.filter(c=>c.caseType==='newbusiness');
  document.getElementById('acReplacementsList').innerHTML=reps.length?reps.map(acCaseCard).join(''):`<div style="color:#9ca3af;font-size:12px;padding:10px;text-align:center;">${hasFilter?'No matches':'No replacements this month'}</div>`;
  document.getElementById('acNewBizList').innerHTML=newb.length?newb.map(acCaseCard).join(''):`<div style="color:#9ca3af;font-size:12px;padding:10px;text-align:center;">${hasFilter?'No matches':'No new business this month'}</div>`;
}

function acGetAlertList(c){
  const al=[];
  if(c.impAlerts?.affordabilityFailed)al.push('\u203c\ufe0f Afford. Failed');
  if(c.impAlerts?.highPremiumValue)al.push('\u26a0\ufe0f High Premium');
  if(c.impAlerts?.expensesUnderstated)al.push('\u26a0\ufe0f Expenses');
  if(c.impAlerts?.qlinkAffordable)al.push('\u2705 Qlink Affordable');
  if(c.impAlerts?.affordabilityRetry)al.push('\u26a0\ufe0f Retry Limit');
  if(c.docs?.payslipDate&&acDocTooOld(c.docs.payslipDate))al.push('\ud83d\udcc4 Old Payslip');
  if(c.docs?.bankStatDate&&acDocTooOld(c.docs.bankStatDate))al.push('\ud83c\udfe6 Old Bank St.');
  if(c.docs?.licenseExpiry&&acLicenseExpired(c.docs.licenseExpiry))al.push('\ud83e\udeb2 License Exp');
  const _pols=c.policies||[];
  const _ms=_pols.filter(p=>(p.status||'replace')==='replace'&&!p.schedUploaded).length;
  const _mc=_pols.filter(p=>(p.status||'replace')==='replace'&&!p.cxlPack).length;
  const _mo=(c.collectionType==='muni')?_pols.filter(p=>(p.status||'replace')==='replace'&&!p.soMandate).length:0;
  const _mf=_pols.filter(p=>((p.status==='paidup'||p.status==='bank'))&&!p.formReceived).length;
  if(_ms)al.push('\ud83d\udcc1 '+_ms+' sched'+((_ms>1)?'s':'')+' pending');
  if(_mc)al.push('\ud83d\udce6 CXL pending');
  if(_mo)al.push('\ud83c\udfdb\ufe0f SO pending');
  if(_mf)al.push('\ud83d\udccb '+_mf+' form'+((_mf>1)?'s':'')+' pending');
  return al;
}
function acDocTooOld(d){if(!d)return false;const dt=new Date(d);const c=new Date();c.setMonth(c.getMonth()-3);return dt<c;}
function acLicenseExpired(d){if(!d)return false;return new Date(d)<new Date();}

function acCaseCard(c){
  const alerts=acGetAlertList(c);
  const pol=(c.policies||[]).length;
  const qStr=c.qlink?.result==='passed'?'\u2705':c.qlink?.result==='failed'?'\u274c':'\u2014';
  const collChip={gov_qlink:`<span style="font-size:9px;font-weight:700;padding:1px 7px;border-radius:8px;background:#eff6ff;color:#1d4ed8;border:1px solid #bfdbfe;">\ud83c\udfdb\ufe0f Gov - Qlink</span>`,debicheck:`<span style="font-size:9px;font-weight:700;padding:1px 7px;border-radius:8px;background:#f3e8ff;color:#6b21a8;border:1px solid #c4b5fd;">\ud83d\udcb3 DebiCheck</span>`,muni:`<span style="font-size:9px;font-weight:700;padding:1px 7px;border-radius:8px;background:#ecfdf5;color:#065f46;border:1px solid #6ee7b7;">\ud83c\udfd9\ufe0f Muni SO</span>`}[c.collectionType]||'';
  return `<div class="ac-case-card ${c.overallPass?'pass':c.status==='attention_needed'?'attention':'fail'}" onclick="acOpenDetail('${c.id}')">
    <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:8px;">
      <div style="min-width:0;">
        <div style="font-size:13px;font-weight:700;color:#0d1f3c;">${c.overallPass?'\u2705':'\u274c'} ${c.clientName||'\u2014'} x${pol}</div>
        <div style="font-size:11px;color:#6b7280;margin-top:1px;">${c.advisor||'\u2014'} \u00b7 Qlink ${qStr}${c.qlink?.available?' R'+parseFloat(c.qlink.available).toFixed(0):''}</div>
        <div style="margin-top:4px;display:flex;flex-wrap:wrap;gap:3px;">${collChip}${alerts.map(a=>`<span class="ac-alert-chip${a.includes('pending')?' pending':''}">${a}</span>`).join('')}</div>
      </div>
      <span class="ac-status ${c.status||'pending_approval'}">${AC_STATUSES[c.status]||'Pending'}</span>
    </div>
  </div>`;
}

function acOpenForm(editId){
  _acEditId=editId||null;
  _acPolicies=[];
  Object.keys(_acPills).forEach(k=>delete _acPills[k]);
  Object.keys(_acTris).forEach(k=>delete _acTris[k]);
  const sel=document.getElementById('ac_advisor');
  if(sel&&sel.options.length<=1){
    ADVISOR_LIST.forEach(a=>{const o=document.createElement('option');o.value=a.name;o.textContent=a.name;sel.appendChild(o);});
  }
  document.getElementById('ac_statusBtns').innerHTML=Object.entries(AC_STATUSES).map(([k,l])=>
    `<button class="ac-pill" data-g="status" data-v="${k}" onclick="acPill(this)" style="text-align:left;border-radius:8px;padding:8px 12px;font-size:12px;">${l}</button>`).join('');
  acQlinkReset();
  if(editId){
    const c=acGetCases(_acMonth).find(x=>x.id===editId);
    if(c){acFillForm(c);acQlinkRestore(c);}
    document.getElementById('acFormTitle').textContent='Edit Case';
  } else {
    document.getElementById('acFormTitle').textContent='New Case';
    ['ac_affordFailed','ac_affordRetry','ac_highPrem','ac_expenses','ac_qlinkAffordable','ac_discEmail','ac_compEmail'].forEach(id=>{const el=document.getElementById(id);if(el)el.checked=false;});
    ['ac_clientName','ac_qlNotes','ac_caseNotes','ac_suppNotes'].forEach(id=>{const el=document.getElementById(id);if(el)el.value='';});
    ['ac_aioCxl'].forEach(id=>{const el=document.getElementById(id);if(el)el.value='';});
    ['ac_bankStatDate','ac_payslipDate','ac_licenseExpiry'].forEach(id=>{const el=document.getElementById(id);if(el)el.value='';});
    document.querySelectorAll('input[name="ac_afterRep"]').forEach(r=>r.checked=false);
    document.querySelectorAll('.ac-type-btn').forEach((b,i)=>b.classList.toggle('active',i===0));
    document.querySelectorAll('.ac-tri').forEach(b=>b.className='ac-tri');
    document.querySelectorAll('.ac-pill').forEach(b=>b.classList.remove('sel','active'));
    document.getElementById('ac_licenseExpiryRow').style.display='none';
    document.getElementById('ac_qlFailSection').style.display='none';
    document.getElementById('ac_repDocRows').style.display='block';
    _acCollType='';document.querySelectorAll('[data-ctype]').forEach(b=>b.classList.remove('active'));
    _acPolicies=[];acRenderPolicies();
  }
  document.querySelectorAll('.page').forEach(el=>el.classList.remove('active'));
  document.getElementById('page-acform').classList.add('active');
  window.scrollTo(0,0);
}

function acFillForm(c){
  document.getElementById('ac_clientName').value=c.clientName||'';
  document.getElementById('ac_advisor').value=c.advisor||'';
  document.querySelectorAll('.ac-type-btn').forEach(b=>b.classList.toggle('active',b.dataset.type===c.caseType));
  _acCollType=c.collectionType||'';
  document.querySelectorAll('[data-ctype]').forEach(b=>b.classList.toggle('active',b.dataset.ctype===_acCollType));
  document.getElementById('ac_affordFailed').checked=!!c.impAlerts?.affordabilityFailed;
  document.getElementById('ac_affordRetry').checked=!!c.impAlerts?.affordabilityRetry;
  document.getElementById('ac_highPrem').checked=!!c.impAlerts?.highPremiumValue;
  document.getElementById('ac_expenses').checked=!!c.impAlerts?.expensesUnderstated;
  document.getElementById('ac_qlinkAffordable').checked=!!c.impAlerts?.qlinkAffordable;
  document.getElementById('ac_discEmail').checked=!!c.disclosureEmail;
  document.getElementById('ac_compEmail').checked=!!c.complianceEmail;
  const pillSet=(g,v)=>{if(!v)return;_acPills[g]=v;document.querySelectorAll(`[data-g="${g}"]`).forEach(b=>b.classList.toggle('active',b.dataset.v===v));};
  pillSet('cv',c.clientVerification);pillSet('bv',c.bankVerification);pillSet('risk',c.clientRisk);
  pillSet('qlResult',c.qlink?.result);pillSet('status',c.status);pillSet('idType',c.docs?.idType||'sa_id');
  _acPills.overall=c.overallPass?'pass':'fail';
  document.querySelectorAll('[data-g="overall"]').forEach(b=>b.classList.toggle('active',b.dataset.v===(c.overallPass?'pass':'fail')));
  const triSet=(g,v)=>{if(!v)return;_acTris[g]=v;document.querySelectorAll(`[data-g="${g}"].ac-tri`).forEach(b=>{b.className='ac-tri'+(b.dataset.v===v?` sel-${v}`:'');});};
  ['id','bankStat','payslip','repDisc','schedules','cxlPack','soMandates'].forEach(k=>triSet(k,c.docs?.[k]));
  document.getElementById('ac_licenseExpiry').value=c.docs?.licenseExpiry||'';
  document.getElementById('ac_bankStatDate').value=c.docs?.bankStatDate||'';
  document.getElementById('ac_payslipDate').value=c.docs?.payslipDate||'';
  document.getElementById('ac_suppNotes').value=c.docs?.supportingNotes||'';
  // Qlink calc state restored separately via acQlinkRestore(c)
  document.getElementById('ac_qlNotes').value=c.qlink?.notes||'';
  document.getElementById('ac_aioCxl').value=c.numAioCxl||'';
  document.getElementById('ac_caseNotes').value=c.caseNotes||'';
  document.querySelectorAll('input[name="ac_afterRep"]').forEach(r=>{r.checked=r.value===(c.qlink?.afterReplacement||'');});
  document.getElementById('ac_qlFailSection').style.display=c.qlink?.result==='failed'?'block':'none';
  document.getElementById('ac_licenseExpiryRow').style.display=c.docs?.idType==='license'?'block':'none';
  const isRep=c.caseType==='replacement'||c.caseType==='both';
  document.getElementById('ac_repDocRows').style.display=isRep?'block':'none';
  _acPolicies=(c.policies||[]).map(p=>({...p}));acRenderPolicies();acUpdatePolTotal();
}

function acCloseForm(){
  document.getElementById('page-acform').classList.remove('active');
  document.getElementById('page-appchecks').classList.add('active');
  acRenderDraftBanner();
}

function acSetType(t,btn){
  document.querySelectorAll('.ac-type-btn').forEach(b=>b.classList.remove('active'));
  btn.classList.add('active');
  document.getElementById('ac_repDocRows').style.display=(t==='replacement'||t==='both')?'block':'none';
}

function acPill(btn){
  const g=btn.dataset.g,v=btn.dataset.v;
  _acPills[g]=v;
  document.querySelectorAll(`[data-g="${g}"]`).forEach(b=>b.classList.toggle('active',b.dataset.v===v));
  if(g==='cv')document.getElementById('ac_riskRow').style.display=v==='completed'?'block':'none';
  if(g==='idType'){
    document.getElementById('ac_licenseExpiryRow').style.display=v==='license'?'block':'none';
    if(v!=='license'){document.getElementById('ac_licenseWarn').style.display='none';}
  }
  if(g==='qlResult')document.getElementById('ac_qlFailSection').style.display=v==='failed'?'block':'none';
}

function acTri(btn){
  const g=btn.dataset.g,v=btn.dataset.v;
  _acTris[g]=v;
  document.querySelectorAll(`[data-g="${g}"].ac-tri`).forEach(b=>{b.className='ac-tri'+(b.dataset.v===v?` sel-${v}`:'');});
}

function acCheckDoc(field,warnId){
  const dateId='ac_'+field;
  const inp=document.getElementById(dateId);const warn=document.getElementById(warnId);
  if(!inp||!warn)return;
  if(!inp.value){warn.style.display='none';return;}
  const old=acDocTooOld(inp.value);
  warn.style.display='block';warn.style.color=old?'#dc2626':'#16a34a';
  warn.textContent=old?'\u274c Older than 3 months':'\u2705 Within 3 months';
}

function acCheckLicense(){
  const v=document.getElementById('ac_licenseExpiry')?.value;
  const warn=document.getElementById('ac_licenseWarn');
  if(warn)warn.style.display=(v&&acLicenseExpired(v))?'block':'none';
}

function acSetCollType(t,btn){
  _acCollType=t;
  document.querySelectorAll('[data-ctype]').forEach(b=>b.classList.remove('active'));
  btn.classList.add('active');
  acRenderPolicies();
}
function acAddPolicy(){_acPolicies.push({number:'',premium:0,company:'',status:'replace',schedUploaded:false,cxlPack:false,formReceived:false,soMandate:false,fromQlink:false});acRenderPolicies();}
function acMarkAllPolicies(field){_acPolicies.filter(p=>(p.status||'replace')==='replace').forEach(p=>p[field]=true);acRenderPolicies();}
function acRenderPolicies(){
  const el=document.getElementById('ac_policiesList');if(!el)return;
  const isMuni=_acCollType==='muni';
  const _stOpts=[
    {v:'replace',l:'\ud83d\udd04 Replaced',bg:'#fee2e2',tc:'#991b1b',bc:'#fca5a5'},
    {v:'paidup', l:'\ud83d\udcb0 Paid Up', bg:'#f3e8ff',tc:'#6b21a8',bc:'#c4b5fd'},
    {v:'bank',   l:'\ud83c\udfe6 To Bank', bg:'#fef3c7',tc:'#92400e',bc:'#fde68a'},
    {v:'keep',   l:'\u2705 Kept',          bg:'#dcfce7',tc:'#166534',bc:'#86efac'},
  ];
  const _stMap=Object.fromEntries(_stOpts.map(s=>[s.v,s]));
  const _fChk=(done,lbl,i,field)=>`<label style="display:inline-flex;align-items:center;gap:4px;font-size:11px;font-weight:700;cursor:pointer;padding:3px 8px;border-radius:7px;border:1px solid ${done?'#86efac':'#fca5a5'};background:${done?'#f0fdf4':'#fff1f2'};color:${done?'#166534':'#991b1b'};"><input type="checkbox" ${done?'checked':''} onchange="_acPolicies[${i}].${field}=this.checked;acRenderPolicies();" style="width:14px;height:14px;cursor:pointer;accent-color:${done?'#16a34a':'#dc2626'};"/>${done?'\u2705':'\u26a0\ufe0f'} ${lbl}</label>`;
  // Bulk action bar \u2014 shown when \u22652 replace-status policies exist
  const _repPols=_acPolicies.filter(p=>(p.status||'replace')==='replace');
  const _allSchedDone=_repPols.every(p=>p.schedUploaded);
  const _allCxlDone=_repPols.every(p=>p.cxlPack);
  const _allSODone=_repPols.every(p=>p.soMandate);
  const _bulkBtn=(done,lbl,field)=>`<button onclick="acMarkAllPolicies('${field}')" ${done?'disabled':''} style="display:inline-flex;align-items:center;gap:5px;font-size:11px;font-weight:700;padding:5px 11px;border-radius:8px;border:1px solid ${done?'#86efac':'#fed7aa'};background:${done?'#f0fdf4':'#fff7ed'};color:${done?'#166534':'#c2410c'};cursor:${done?'default':'pointer'};">${done?'\u2705':'\ud83d\udccb'} ${lbl}</button>`;
  const bulkBar=_repPols.length>=2?`<div style="display:flex;flex-wrap:wrap;gap:6px;margin-bottom:10px;padding:8px 10px;background:#f8f7f4;border-radius:10px;border:1px solid #e8e4db;">
    <div style="font-size:10px;font-weight:700;color:#6b7280;width:100%;text-transform:uppercase;letter-spacing:.5px;margin-bottom:2px;">Mark all at once</div>
    ${_bulkBtn(_allSchedDone,'All schedules uploaded','schedUploaded')}
    ${_bulkBtn(_allCxlDone,'All CXL packs uploaded','cxlPack')}
    ${isMuni?_bulkBtn(_allSODone,'All SO mandates received','soMandate'):''}
  </div>`:'';
  el.innerHTML=_acPolicies.length?(bulkBar+_acPolicies.map((p,i)=>{
    const st=p.status||'replace';
    const so=_stMap[st]||_stMap.replace;
    const stBadge=`<span style="font-size:9px;font-weight:700;padding:2px 7px;border-radius:8px;background:${so.bg};color:${so.tc};border:1px solid ${so.bc};">${so.l}</span>`;
    const stRow=p.fromQlink?stBadge:`<div style="display:flex;gap:4px;flex-wrap:wrap;">${_stOpts.map(s=>`<button onclick="_acPolicies[${i}].status='${s.v}';acRenderPolicies();" style="font-size:10px;font-weight:700;padding:2px 8px;border-radius:7px;border:1px solid ${st===s.v?s.bc:'#e5e7eb'};background:${st===s.v?s.bg:'#f9fafb'};color:${st===s.v?s.tc:'#9ca3af'};cursor:pointer;">${s.l}</button>`).join('')}</div>`;
    let chks='';
    if(st==='replace'){chks=_fChk(!!p.schedUploaded,'Schedule',i,'schedUploaded')+' '+_fChk(!!p.cxlPack,'CXL Pack',i,'cxlPack')+(isMuni?' '+_fChk(!!p.soMandate,'SO Mandate',i,'soMandate'):'');}
    else if(st==='paidup')chks=_fChk(!!p.formReceived,'Paid Up / Surrender Form',i,'formReceived');
    else if(st==='bank')chks=_fChk(!!p.formReceived,'Bank / Debit Mandate Form',i,'formReceived');
    return `<div class="ac-policy-row" style="flex-direction:column;gap:5px;">
      <div style="display:flex;gap:5px;align-items:center;">
        <input value="${p.company||''}" placeholder="Company" oninput="_acPolicies[${i}].company=this.value" style="flex:2;border:1px solid #e5e7eb;border-radius:6px;padding:6px 8px;font-size:11px;"/>
        <input value="${p.number||''}" placeholder="IP number" oninput="_acPolicies[${i}].number=this.value" style="flex:2;border:1px solid #e5e7eb;border-radius:6px;padding:6px 8px;font-size:11px;font-family:monospace;"/>
        <span style="color:#6b7280;font-size:12px;">R</span>
        <input type="number" value="${p.premium||''}" placeholder="0" oninput="_acPolicies[${i}].premium=parseFloat(this.value)||0;acUpdatePolTotal();" style="width:72px;border:1px solid #e5e7eb;border-radius:6px;padding:6px 8px;font-size:12px;font-weight:700;color:#c9922a;"/>
        <button onclick="_acPolicies.splice(${i},1);acRenderPolicies();" style="background:none;border:none;color:#dc2626;cursor:pointer;font-size:16px;">\u2715</button>
      </div>
      <div style="padding:2px 2px;">${stRow}</div>
      ${chks?`<div style="display:flex;flex-wrap:wrap;gap:5px;padding:0 2px;">${chks}</div>`:''}
    </div>`;
  }).join('')):'<div style="color:#9ca3af;font-size:12px;text-align:center;padding:8px 0;">Tap + Add to add a policy</div>';
  acUpdatePolTotal();
}
function acUpdatePolTotal(){
  const total=_acPolicies.reduce((s,p)=>s+(+p.premium||0),0);
  const el=document.getElementById('ac_polTotal');
  if(el)el.textContent='R '+total.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g,',');
}

function acSaveForm(){
  const clientName=document.getElementById('ac_clientName')?.value?.trim();
  if(!clientName){alert('Please enter the client name.');return;}
  const caseType=document.querySelector('.ac-type-btn.active')?.dataset?.type||'replacement';
  const cases=acGetCases(_acMonth);
  const afterRep=document.querySelector('input[name="ac_afterRep"]:checked')?.value||'';
  const c={
    id:_acEditId||('ac_'+Date.now()),
    createdAt:_acEditId?(cases.find(x=>x.id===_acEditId)?.createdAt||new Date().toISOString()):new Date().toISOString(),
    createdBy:currentUser?.code,caseType,collectionType:_acCollType,clientName,
    advisor:document.getElementById('ac_advisor')?.value||'',
    impAlerts:{
      affordabilityFailed:!!document.getElementById('ac_affordFailed')?.checked,
      affordabilityRetry:!!document.getElementById('ac_affordRetry')?.checked,
      highPremiumValue:!!document.getElementById('ac_highPrem')?.checked,
      expensesUnderstated:!!document.getElementById('ac_expenses')?.checked,
      qlinkAffordable:!!document.getElementById('ac_qlinkAffordable')?.checked,
    },
    clientVerification:_acPills.cv||'not_started',clientRisk:_acPills.risk||'',
    bankVerification:_acPills.bv||'not_verified',
    disclosureEmail:!!document.getElementById('ac_discEmail')?.checked,
    complianceEmail:!!document.getElementById('ac_compEmail')?.checked,
    docs:{
      id:_acTris.id||'',idType:_acPills.idType||'sa_id',
      licenseExpiry:document.getElementById('ac_licenseExpiry')?.value||'',
      bankStat:_acTris.bankStat||'',bankStatDate:document.getElementById('ac_bankStatDate')?.value||'',
      payslip:_acTris.payslip||'',payslipDate:document.getElementById('ac_payslipDate')?.value||'',
      repDisc:_acTris.repDisc||'',schedules:_acTris.schedules||'',
      cxlPack:_acTris.cxlPack||'',soMandates:_acTris.soMandates||'',
      supportingNotes:document.getElementById('ac_suppNotes')?.value||'',
    },
    policies:_acPolicies.map(p=>({...p})),
    numAioCxl:+(document.getElementById('ac_aioCxl')?.value||0),
    qlink:{
      salary:document.getElementById('acql_salary')?.value||'',
      newPremium:document.getElementById('acql_newpremium')?.value||'0',
      available:_acQlAvailable?_acQlAvailable.toFixed(2):'',
      result:_acQlResult||'',afterReplacement:afterRep,
      notes:document.getElementById('ac_qlNotes')?.value||'',
    },
    overallPass:_acPills.overall!=='fail',
    status:_acPills.status||'pending_approval',
    caseNotes:document.getElementById('ac_caseNotes')?.value||'',
    qlDeductions:_acQlDeductions.map(d=>({...d})),
    qlSkyPolicies:_acQlSkyPolicies.map(p=>({...p})),
    comments:_acEditId?(cases.find(x=>x.id===_acEditId)?.comments||[]):[],
  };
  if(c.qlink.result==='failed'&&c.qlink.afterReplacement==='debicheck')c.status='debicheck';
  if(_acEditId){const idx=cases.findIndex(x=>x.id===_acEditId);if(idx>-1)cases[idx]=c;else cases.push(c);}
  else cases.push(c);
  acSaveCases(_acMonth,cases);
  acClearDraft();
  acCloseForm();acRenderCaseList();
  if(currentUser?.isOps&&!currentUser?.isManager){
    setTimeout(()=>{if(confirm('Case saved! Send WhatsApp summary to manager?'))window.open('https://wa.me/27676747722?text='+encodeURIComponent(acBuildWAMessage(c)),'_blank');},200);
  }
}

function acBuildWAMessage(c){
  if(!c)return'';
  const isMuni=c.collectionType==='muni';
  const collStr=c.collectionType==='gov_qlink'?'Gov - Qlink':c.collectionType==='debicheck'?'DebiCheck':c.collectionType==='muni'?'Muni Stop Order':'';
  const pol=(c.policies||[]).map(p=>{
    const chk=[p.schedUploaded?'\u2705 Sched':'\u2610 Sched',p.cxlPack?'\u2705 CXL':'\u2610 CXL'];
    if(isMuni)chk.push(p.soMandate?'\u2705 SO Mandate':'\u2610 SO Mandate');
    return `${p.company?p.company+' ':''}${p.number||'\u2014'} \u2014 R${(+p.premium).toFixed(2)} [${chk.join(' | ')}]`;
  }).join('\n');
  const total=(c.policies||[]).reduce((s,p)=>s+(+p.premium||0),0);
  const alerts=acGetAlertList(c);
  const qlRes=c.qlink?.result==='passed'?`\u2705 Passed (R${(+c.qlink.available).toFixed(2)} avail)`:c.qlink?.result==='failed'?`\u274c Failed \u2192 ${c.qlink.afterReplacement==='stop_order'?'Stop Order':c.qlink.afterReplacement==='debicheck'?'DebiCheck':'Still fails'}`:'Not checked';
  return `*App Check \u2014 ${acMonthLabel(_acMonth)}*\n\n*Client:* ${c.clientName||'\u2014'} \u2014 ${c.advisor||'\u2014'}\n*Type:* ${c.caseType==='replacement'?'Replacement':c.caseType==='newbusiness'?'New Business':'Both'}${collStr?' | '+collStr:''}\n\n*Policies:*\n${pol||'None'}\n*Total:* R ${total.toFixed(2)}\n\n*Qlink:* ${qlRes}\n*Status:* ${AC_STATUSES[c.status]||c.status}\n\n*Docs:* ID ${c.docs?.id==='yes'?'\u2705':'\u274c'} | Bank ${c.docs?.bankStat==='yes'?'\u2705':'\u274c'} (${c.docs?.bankStatDate||'\u2014'}) | Payslip ${c.docs?.payslip==='yes'?'\u2705':'\u274c'} (${c.docs?.payslipDate||'\u2014'}) | CXL Pack ${c.docs?.cxlPack==='yes'?'\u2705':'\u274c'}${alerts.length?'\n\n*Alerts:* '+alerts.join(', '):''}${c.qlink?.notes?'\n*Qlink notes:* '+c.qlink.notes:''}${c.caseNotes?'\n*Notes:* '+c.caseNotes:''}`;
}

function acOpenDetail(id){
  const c=acGetCases(_acMonth).find(x=>x.id===id);if(!c)return;
  _acDetailId=id;
  const alerts=acGetAlertList(c);
  const isMuni=c.collectionType==='muni';
  const collLabel={'gov_qlink':'\ud83c\udfdb\ufe0f Gov - Qlink','debicheck':'\ud83d\udcb3 DebiCheck','muni':'\ud83c\udfd9\ufe0f Muni Stop Order'}[c.collectionType]||'';
  const _chip=(done,lbl,okC,okB,okT,badC,badB,badT)=>
    `<span style="display:inline-flex;align-items:center;gap:3px;font-size:10px;font-weight:700;padding:2px 7px;border-radius:8px;border:1px solid ${done?okB:badB};background:${done?okC:badC};color:${done?okT:badT};">${done?'\u2705':'\u26a0\ufe0f'} ${lbl}</span>`;
  const _stDet={replace:{l:'\ud83d\udd04 Replaced',bg:'#fee2e2',tc:'#991b1b',bc:'#fca5a5'},paidup:{l:'\ud83d\udcb0 Paid Up',bg:'#f3e8ff',tc:'#6b21a8',bc:'#c4b5fd'},bank:{l:'\ud83c\udfe6 To Bank',bg:'#fef3c7',tc:'#92400e',bc:'#fde68a'},keep:{l:'\u2705 Kept',bg:'#dcfce7',tc:'#166534',bc:'#86efac'}};
  const pol=(c.policies||[]).map(p=>{
    const st=p.status||'replace';
    const sd=_stDet[st]||_stDet.replace;
    let chipsHtml='',outstanding=false;
    if(st==='replace'){
      const sOk=!!p.schedUploaded,cOk=!!p.cxlPack,soOk=!!p.soMandate;
      outstanding=!sOk||!cOk||(isMuni&&!soOk);
      chipsHtml=_chip(sOk,'Schedule','#dcfce7','#86efac','#166534','#fee2e2','#fca5a5','#991b1b')
        +' '+_chip(cOk,'CXL Pack','#dcfce7','#86efac','#166534','#fee2e2','#fca5a5','#991b1b')
        +(isMuni?' '+_chip(soOk,'SO Mandate','#f3e8ff','#c4b5fd','#6b21a8','#fee2e2','#fca5a5','#991b1b'):'');
    } else if(st==='paidup'||st==='bank'){
      outstanding=!p.formReceived;
      const fl=st==='paidup'?'Paid Up / Surrender Form':'Bank / Debit Mandate Form';
      chipsHtml=_chip(!!p.formReceived,fl,'#dcfce7','#86efac','#166534','#fee2e2','#fca5a5','#991b1b');
    }
    return `<div style="padding:6px 8px;margin-bottom:4px;border-radius:8px;border-left:3px solid ${outstanding?'#f97316':'#86efac'};background:${outstanding?'#fff7ed':'#f0fdf4'};">
      <div style="display:flex;justify-content:space-between;align-items:flex-start;gap:6px;">
        <div>
          <span style="font-size:9px;font-weight:700;padding:1px 6px;border-radius:6px;background:${sd.bg};color:${sd.tc};border:1px solid ${sd.bc};">${sd.l}</span>
          ${p.company?`<div style="font-size:10px;color:#6b7280;font-weight:600;margin-top:2px;">${p.company}</div>`:''}
          <div style="font-size:12px;font-family:monospace;font-weight:700;color:#0d1f3c;">${p.number||'\u2014'}</div>
        </div>
        <span style="font-size:12px;font-weight:700;white-space:nowrap;">R ${(+p.premium).toFixed(2)}</span>
      </div>
      ${chipsHtml?`<div style="display:flex;flex-wrap:wrap;gap:4px;margin-top:4px;">${chipsHtml}</div>`:''}
    </div>`;
  }).join('');
  const total=(c.policies||[]).reduce((s,p)=>s+(+p.premium||0),0);
  const docRows=[['ID ('+(c.docs?.idType==='license'?"Driver's Lic":'SA ID')+')','id'],['Bank Statement','bankStat'],['Payslip','payslip'],['Rep Disc','repDisc'],['CXL Pack (all)','cxlPack']];
  if(isMuni)docRows.push(['SO Mandates','soMandates']);
  const content=`<div style="display:flex;align-items:flex-start;justify-content:space-between;margin-bottom:10px;">
    <div style="flex:1;">
      <div style="font-size:14px;font-weight:700;color:#0d1f3c;margin-bottom:4px;">${c.clientName||'\u2014'} \u2014 ${c.advisor||'\u2014'}</div>
      <div style="display:flex;flex-wrap:wrap;gap:5px;">
        <span class="ac-status ${c.status||'pending_approval'}">${AC_STATUSES[c.status]||'Pending'}</span>
        ${collLabel?`<span style="font-size:10px;font-weight:700;padding:2px 8px;border-radius:10px;background:#eff6ff;color:#1d4ed8;border:1px solid #bfdbfe;">${collLabel}</span>`:''}
        ${alerts.map(a=>`<span class="ac-alert-chip${a.includes('pending')?' pending':''}">${a}</span>`).join('')}
      </div>
    </div>
    <button onclick="document.getElementById('acDetailPanel').style.display='none';" style="background:#f3f4f6;border:1px solid #e5e7eb;border-radius:8px;padding:5px 10px;font-size:12px;cursor:pointer;margin-left:8px;">\u2715</button>
  </div>
  <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:10px;">
    <div style="background:#f9fafb;border-radius:8px;padding:8px;"><div style="font-size:10px;color:#6b7280;font-weight:700;">CLIENT VERIF.</div><div style="font-size:12px;font-weight:700;margin-top:2px;">${c.clientVerification==='completed'?'\u2705 Done (Risk: '+(c.clientRisk||'\u2014').toUpperCase()+')':c.clientVerification==='in_progress'?'\u23f3 In Progress':'Not started'}</div></div>
    <div style="background:#f9fafb;border-radius:8px;padding:8px;"><div style="font-size:10px;color:#6b7280;font-weight:700;">BANK VERIF.</div><div style="font-size:12px;font-weight:700;margin-top:2px;">${c.bankVerification==='verified'?'\u2705 Verified':'Not verified'}</div></div>
  </div>
  <div style="font-size:10px;font-weight:700;color:#6b7280;text-transform:uppercase;margin-bottom:5px;">Documents</div>
  <div style="background:#f9fafb;border-radius:8px;padding:8px 10px;margin-bottom:10px;font-size:12px;">
    ${docRows.map(([l,k])=>`<div style="display:flex;justify-content:space-between;padding:2px 0;">${l}<span>${c.docs?.[k]==='yes'?'\u2705':c.docs?.[k]==='no'?'\u274c':c.docs?.[k]==='na'?'N/A':'\u2014'}</span></div>`).join('')}
    ${c.docs?.bankStatDate?`<div style="color:${acDocTooOld(c.docs.bankStatDate)?'#dc2626':'#16a34a'};font-size:11px;margin-top:3px;">Bank: ${c.docs.bankStatDate}${acDocTooOld(c.docs.bankStatDate)?' \u26a0\ufe0f':''}</div>`:''}
    ${c.docs?.payslipDate?`<div style="color:${acDocTooOld(c.docs.payslipDate)?'#dc2626':'#16a34a'};font-size:11px;">Payslip: ${c.docs.payslipDate}${acDocTooOld(c.docs.payslipDate)?' \u26a0\ufe0f':''}</div>`:''}
  </div>
  <div style="font-size:10px;font-weight:700;color:#6b7280;text-transform:uppercase;margin-bottom:5px;">Policies ${c.numAioCxl?'('+c.numAioCxl+' AIO CXL)':''}</div>
  <div style="margin-bottom:5px;">${pol||'<span style="color:#9ca3af;font-size:12px;">None</span>'}</div>
  <div style="display:flex;justify-content:space-between;font-size:13px;font-weight:700;padding:5px 0 10px;border-top:1px solid #e5e7eb;"><span>Total</span><span>R ${total.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g,',')}</span></div>
  <div style="background:${c.qlink?.result==='passed'?'#dcfce7':c.qlink?.result==='failed'?'#fee2e2':'#f9fafb'};border-radius:8px;padding:8px 10px;margin-bottom:10px;">
    <div style="font-size:13px;font-weight:700;">${c.qlink?.result==='passed'?'\u2705 Passed':c.qlink?.result==='failed'?'\u274c Failed':'Qlink \u2014'}</div>
    ${c.qlink?.available?`<div style="font-size:12px;margin-top:2px;">Available: R ${(+c.qlink.available).toLocaleString('en-ZA',{minimumFractionDigits:2})}</div>`:''}
    ${c.qlink?.afterReplacement?`<div style="font-size:12px;margin-top:2px;">${c.qlink.afterReplacement==='stop_order'?'\u2192 Stop Order':c.qlink.afterReplacement==='debicheck'?'\u2192 DebiCheck':'\u2192 Still fails'}</div>`:''}
    ${c.qlink?.notes?`<div style="font-size:11px;color:#6b7280;margin-top:3px;font-style:italic;">${c.qlink.notes}</div>`:''}
  </div>
  ${c.caseNotes?`<div style="background:#f9fafb;border-radius:8px;padding:8px 10px;font-size:12px;margin-bottom:10px;">${c.caseNotes}</div>`:''}
  <div style="font-size:10px;font-weight:700;color:#6b7280;text-transform:uppercase;margin-bottom:6px;">Comments</div>
  <div id="acDetailComments">${(c.comments||[]).map(cm=>`<div class="ac-comment"><div class="ac-comment-author">${cm.author} <span style="font-weight:400;color:#9ca3af;font-size:10px;">\u00b7 ${(cm.at||'').slice(0,10)}</span></div><div style="margin-top:2px;">${cm.text}</div></div>`).join('')||'<div style="color:#9ca3af;font-size:12px;margin-bottom:8px;">No comments.</div>'}</div>
  <div style="display:flex;gap:6px;margin-top:6px;">
    <input id="acCommentInput" placeholder="Add a comment\u2026" style="flex:1;padding:7px 10px;border:1px solid #e5e7eb;border-radius:8px;font-size:12px;" onkeydown="if(event.key==='Enter')acAddComment()"/>
    <button onclick="acAddComment()" style="background:#0d1f3c;color:#fff;border:none;border-radius:8px;padding:7px 12px;font-size:12px;font-weight:700;cursor:pointer;">Post</button>
  </div>
  <div style="display:flex;gap:8px;margin-top:10px;padding-top:10px;border-top:1px solid #f0f0f0;">
    <button onclick="acOpenForm('${id}')" style="flex:1;background:#f3f4f6;color:#374151;border:1px solid #e5e7eb;border-radius:10px;padding:10px;font-size:12px;font-weight:700;cursor:pointer;">\u270f\ufe0f Edit</button>
    <button onclick="acSendWA('${id}')" style="flex:1;background:#25d366;color:#fff;border:none;border-radius:10px;padding:10px;font-size:12px;font-weight:700;cursor:pointer;">\ud83d\udcf1 WhatsApp</button>
    <button onclick="acDeleteCase('${id}')" style="background:#fee2e2;color:#991b1b;border:none;border-radius:10px;padding:10px 12px;font-size:12px;font-weight:700;cursor:pointer;">\ud83d\uddd1\ufe0f</button>
  </div>`;
  let det=document.getElementById('acDetailPanel');
  if(!det){det=document.createElement('div');det.id='acDetailPanel';document.getElementById('page-appchecks').appendChild(det);}
  det.style.cssText='background:#fff;border:1px solid #e5e7eb;border-radius:16px;padding:16px;margin-top:10px;';
  det.innerHTML=content;
  det.style.display='block';
  setTimeout(()=>det.scrollIntoView({behavior:'smooth',block:'nearest'}),50);
}

function acAddComment(){
  const inp=document.getElementById('acCommentInput');if(!inp||!inp.value.trim())return;
  const cases=acGetCases(_acMonth);
  const c=cases.find(x=>x.id===_acDetailId);if(!c)return;
  if(!c.comments)c.comments=[];
  c.comments.push({author:currentUser?.name||'Unknown',text:inp.value.trim(),at:new Date().toISOString()});
  acSaveCases(_acMonth,cases);inp.value='';acOpenDetail(_acDetailId);
}

function acDeleteCase(id){
  if(!confirm('Delete this case? Cannot be undone.'))return;
  acSaveCases(_acMonth,acGetCases(_acMonth).filter(c=>c.id!==id));
  const det=document.getElementById('acDetailPanel');if(det)det.style.display='none';
  _acDetailId=null;acRenderCaseList();
}

function acSendWA(id){
  const c=acGetCases(_acMonth).find(x=>x.id===id);if(!c)return;
  window.open('https://wa.me/27676747722?text='+encodeURIComponent(acBuildWAMessage(c)),'_blank');
}

// ── APP CHECKS QLINK CALCULATOR ──
let _acQlDeductions=[];
let _acQlSkyPolicies=[];
let _acQlAvailable=0;
let _acQlResult=''; // 'passed'|'failed'

function acQlinkClear(){
  _acQlDeductions=[];_acQlSkyPolicies=[];_acQlAvailable=0;_acQlResult='';
  const sal=document.getElementById('acql_salary');if(sal)sal.value='';
  const np=document.getElementById('acql_newpremium');if(np)np.value='0';
  document.getElementById('acql_fspSelect').value='';
  document.getElementById('acql_addAmount').value='';
  document.getElementById('acql_manualWrap').style.display='none';
  acQlinkRenderDeductions();acQlinkRenderSkyPolicies();
  document.getElementById('acql_resultCard').style.display='none';
  document.getElementById('ac_qlFailSection').style.display='none';
}

function acQlinkAddFromDropdown(){
  const sel=document.getElementById('acql_fspSelect');
  const manInp=document.getElementById('acql_manualCompany');
  const amtInp=document.getElementById('acql_addAmount');
  let company=sel.value==='__manual__'?(manInp?.value?.trim()||''):sel.value;
  const amount=parseFloat(amtInp?.value)||0;
  if(!company||!amount){alert('Please select a company and enter an amount.');return;}
  _acQlDeductions.push({company,amount,status:'keep'});
  acQlinkRenderDeductions();acQlinkCalc_();
  sel.value='';if(manInp)manInp.value='';if(amtInp)amtInp.value='';
  document.getElementById('acql_manualWrap').style.display='none';
}

function acSyncPoliciesFromQlink(){
  // Sync replace/paidup/bank deductions — keep is excluded (no forms needed)
  const toSync=_acQlDeductions.filter(d=>d.status==='replace'||d.status==='paidup'||d.status==='bank');
  // Remove fromQlink entries whose deduction is gone or switched to keep
  _acPolicies=_acPolicies.filter(p=>{
    if(!p.fromQlink)return true;
    return toSync.some(d=>(d.company||'').trim().toLowerCase()===(p.company||'').trim().toLowerCase()&&(d.policy_number||'').trim()===(p.number||'').trim());
  });
  // Add new / update status+premium for existing
  toSync.forEach(d=>{
    const co=(d.company||'').trim().toLowerCase(),num=(d.policy_number||'').trim();
    const ex=_acPolicies.find(p=>p.fromQlink&&(p.company||'').trim().toLowerCase()===co&&(p.number||'').trim()===num);
    if(!ex){
      _acPolicies.push({company:d.company||'',number:d.policy_number||'',premium:d.amount||0,status:d.status,schedUploaded:false,cxlPack:false,formReceived:false,soMandate:false,fromQlink:true});
    } else {
      ex.status=d.status; // reflects status change in Qlink
      ex.premium=d.amount||0;
    }
  });
  acRenderPolicies();
}
function acQlinkRenderDeductions(){
  const el=document.getElementById('acql_deductionsList');if(!el)return;
  if(!_acQlDeductions.length){
    el.innerHTML='<div style="text-align:center;color:#9ca3af;font-size:12px;padding:8px;">No deductions added — upload payslip or add manually</div>';
    acSyncPoliciesFromQlink();
    return;
  }
  const statusOpts=[
    {v:'keep',l:'Keep',c:'#dcfce7',tc:'#166534'},
    {v:'replace',l:'Replace',c:'#fee2e2',tc:'#991b1b'},
    {v:'bank',l:'To bank',c:'#fef3c7',tc:'#92400e'},
    {v:'paidup',l:'Paid up',c:'#f3e8ff',tc:'#6b21a8'},
  ];
  el.innerHTML=_acQlDeductions.map((d,i)=>`
    <div style="background:#f8f7f4;border-radius:10px;padding:8px 10px;border:1px solid #e5e7eb;">
      <div style="display:flex;gap:6px;align-items:center;margin-bottom:6px;">
        <input value="${d.company}" placeholder="FSP / Company" oninput="_acQlDeductions[${i}].company=this.value;acQlinkCalc_();" style="flex:1;border:1px solid #e5e7eb;border-radius:6px;padding:5px 8px;font-size:12px;font-weight:600;color:#0d1f3c;background:#fff;"/>
        <span style="font-size:12px;color:#6b7280;">R</span>
        <input type="number" value="${d.amount||''}" placeholder="0" oninput="_acQlDeductions[${i}].amount=parseFloat(this.value)||0;acQlinkCalc_();" style="width:80px;border:1px solid #e5e7eb;border-radius:6px;padding:5px 8px;font-size:12px;font-weight:700;color:#c9922a;background:#fff;"/>
        <button onclick="_acQlDeductions.splice(${i},1);acQlinkRenderDeductions();acQlinkCalc_();" style="background:none;border:none;color:#dc2626;cursor:pointer;font-size:16px;line-height:1;">✕</button>
      </div>
      ${d.policy_number!==undefined?`<div style="margin-bottom:6px;"><input value="${d.policy_number||''}" placeholder="Policy / member number (optional)" oninput="_acQlDeductions[${i}].policy_number=this.value;" style="width:100%;box-sizing:border-box;border:1px solid #e5e7eb;border-radius:6px;padding:4px 8px;font-size:11px;color:#6b7280;background:#fff;"/></div>`:''}
      <div style="display:flex;gap:6px;">
        ${statusOpts.map(s=>`<label style="flex:1;display:flex;align-items:center;justify-content:center;gap:4px;font-size:10px;font-weight:700;color:${d.status===s.v?s.tc:'#6b7280'};cursor:pointer;background:${d.status===s.v?s.c:'#fff'};padding:4px 6px;border-radius:6px;border:1px solid ${d.status===s.v?s.c:'#e5e7eb'};white-space:nowrap;">
          <input type="radio" name="acql_st_${i}" value="${s.v}" ${d.status===s.v?'checked':''} onchange="_acQlDeductions[${i}].status=this.value;acQlinkRenderDeductions();acQlinkCalc_();" style="display:none;"/> ${s.l}
        </label>`).join('')}
      </div>
    </div>`).join('');
  acSyncPoliciesFromQlink();
}

function acQlinkAddSkyPolicy(){
  if(_acQlSkyPolicies.length>=8){alert('Maximum 8 Sky policies allowed.');return;}
  _acQlSkyPolicies.push({premium:0});acQlinkRenderSkyPolicies();
}
function acQlinkRenderSkyPolicies(){
  const el=document.getElementById('acql_skyList');
  const totalEl=document.getElementById('acql_skyTotal');
  const addBtn=document.getElementById('acql_skyAddBtn');
  if(!el)return;
  if(!_acQlSkyPolicies.length){
    el.innerHTML='<div style="text-align:center;color:#9ca3af;font-size:12px;padding:6px;">No Sky policies added — tap "+ Add policy" above</div>';
    if(totalEl)totalEl.style.display='none';
    const np=document.getElementById('acql_newpremium');if(np)np.value='0';
    acQlinkCalc_();return;
  }
  el.innerHTML=_acQlSkyPolicies.map((p,i)=>`
    <div style="display:flex;align-items:center;gap:6px;background:#f8f7f4;border-radius:8px;padding:7px 10px;border:1px solid #e5e7eb;">
      <span style="font-size:11px;font-weight:700;color:#6b7280;min-width:60px;">Policy ${i+1}</span>
      <span style="font-size:13px;color:#6b7280;">R</span>
      <input type="number" value="${p.premium||''}" placeholder="0" oninput="_acQlSkyPolicies[${i}].premium=parseFloat(this.value)||0;acQlinkCalcSkyTotal_();"
        style="flex:1;border:1px solid #e5e7eb;border-radius:6px;padding:6px 8px;font-size:13px;font-weight:700;color:#c9922a;background:#fff;"/>
      <button onclick="_acQlSkyPolicies.splice(${i},1);acQlinkRenderSkyPolicies();" style="background:none;border:none;color:#dc2626;cursor:pointer;font-size:16px;line-height:1;padding:0;">✕</button>
    </div>`).join('');
  if(addBtn)addBtn.style.display=_acQlSkyPolicies.length>=8?'none':'inline-block';
  acQlinkCalcSkyTotal_();
}
function acQlinkCalcSkyTotal_(){
  const total=_acQlSkyPolicies.reduce((s,p)=>s+(p.premium||0),0);
  const np=document.getElementById('acql_newpremium');if(np)np.value=total;
  const totalEl=document.getElementById('acql_skyTotal');
  const totalAmt=document.getElementById('acql_skyTotalAmt');
  if(totalEl)totalEl.style.display=_acQlSkyPolicies.length?'flex':'none';
  if(totalAmt)totalAmt.textContent='R '+total.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g,',');
  acQlinkCalc_();
}

function acQlinkCalc(){acQlinkCalc_();}
function acQlinkCalc_(){
  const salary=parseFloat(document.getElementById('acql_salary')?.value)||0;
  const newPrem=parseFloat(document.getElementById('acql_newpremium')?.value)||0;
  const resultCard=document.getElementById('acql_resultCard');
  const resultEl=document.getElementById('acql_result');
  if(!resultCard||!resultEl)return;
  if(!salary){resultCard.style.display='none';return;}
  resultCard.style.display='block';
  const maxAllowed=salary*0.15;
  const kept=_acQlDeductions.filter(d=>d.status==='keep');
  const replaced=_acQlDeductions.filter(d=>d.status==='replace');
  const banked=_acQlDeductions.filter(d=>d.status==='bank');
  const paidup=_acQlDeductions.filter(d=>d.status==='paidup');
  const keptTotal=kept.reduce((s,d)=>s+d.amount,0);
  const replacedTotal=replaced.reduce((s,d)=>s+d.amount,0);
  const bankTotal=banked.reduce((s,d)=>s+d.amount,0);
  const paidupTotal=paidup.reduce((s,d)=>s+d.amount,0);
  const spaceCreated=replacedTotal+bankTotal+paidupTotal;
  const available=maxAllowed-keptTotal;
  const afterNew=available-newPrem;
  const fits=newPrem>0?newPrem<=available:available>=0;
  const pct=salary?Math.round((keptTotal+newPrem)/salary*100):0;
  const colour=fits?'#16a34a':'#dc2626';
  const fmt=n=>'R '+n.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g,',');
  _acQlAvailable=available;
  _acQlResult=fits?'passed':'failed';
  document.getElementById('ac_qlFailSection').style.display=fits?'none':'block';
  let rows='';
  kept.forEach(d=>{rows+=`<div style="display:flex;justify-content:space-between;font-size:12px;padding:3px 0;border-bottom:1px solid #f0f0f0;"><span style="color:#374151;">✅ ${d.company||'Unknown'} (keep)</span><span style="font-weight:700;">${fmt(d.amount)}</span></div>`;});
  replaced.forEach(d=>{rows+=`<div style="display:flex;justify-content:space-between;font-size:12px;padding:3px 0;border-bottom:1px solid #f0f0f0;"><span style="color:#991b1b;text-decoration:line-through;">❌ ${d.company||'Unknown'} (cancelling)</span><span style="font-weight:700;color:#991b1b;">${fmt(d.amount)}</span></div>`;});
  banked.forEach(d=>{rows+=`<div style="display:flex;justify-content:space-between;font-size:12px;padding:3px 0;border-bottom:1px solid #f0f0f0;"><span style="color:#92400e;">🏦 ${d.company||'Unknown'} (to bank)</span><span style="font-weight:700;color:#92400e;">${fmt(d.amount)}</span></div>`;});
  paidup.forEach(d=>{rows+=`<div style="display:flex;justify-content:space-between;font-size:12px;padding:3px 0;border-bottom:1px solid #f0f0f0;"><span style="color:#6b21a8;">💤 ${d.company||'Unknown'} (paid up)</span><span style="font-weight:700;color:#6b21a8;">${fmt(d.amount)}</span></div>`;});
  resultEl.innerHTML=`
    <div style="margin-bottom:10px;">${rows}</div>
    <div style="background:#f8f7f4;border-radius:10px;padding:12px 14px;display:flex;flex-direction:column;gap:5px;">
      <div style="display:flex;justify-content:space-between;font-size:12px;"><span style="color:#6b7280;">Basic salary</span><span style="font-weight:700;">${fmt(salary)}</span></div>
      <div style="display:flex;justify-content:space-between;font-size:12px;"><span style="color:#6b7280;">15% maximum allowed</span><span style="font-weight:700;">${fmt(maxAllowed)}</span></div>
      <div style="display:flex;justify-content:space-between;font-size:12px;"><span style="color:#6b7280;">Kept deductions</span><span style="font-weight:700;color:#374151;">${fmt(keptTotal)}</span></div>
      ${spaceCreated>0?`<div style="display:flex;justify-content:space-between;font-size:12px;"><span style="color:#6b7280;">Space created</span><span style="font-weight:700;color:#16a34a;">+${fmt(spaceCreated)}</span></div>`:''}
      <div style="display:flex;justify-content:space-between;font-size:12px;"><span style="color:#6b7280;">Available space</span><span style="font-weight:700;color:#0d1f3c;">${fmt(available)}</span></div>
      ${newPrem?`<div style="display:flex;justify-content:space-between;font-size:12px;"><span style="color:#6b7280;">New Sky premium</span><span style="font-weight:700;color:#c9922a;">${fmt(newPrem)}</span></div>`:''}
      ${newPrem?`<div style="display:flex;justify-content:space-between;font-size:12px;"><span style="color:#6b7280;">Remaining after</span><span style="font-weight:700;color:${colour};">${fmt(afterNew)}</span></div>`:''}
    </div>
    <div style="margin-top:10px;background:${fits?'#dcfce7':'#fee2e2'};border-radius:10px;padding:12px 14px;text-align:center;">
      <div style="font-size:16px;font-weight:700;color:${colour};">${fits?'✅ Qlink passes':'❌ Qlink fails'}</div>
      <div style="font-size:12px;color:${colour};margin-top:2px;">${fits?`Total stop order: ${pct}% of basic salary.`:`Exceeds available space by ${fmt(Math.abs(afterNew))}. Move a policy to bank or debit order.`}</div>
      ${!fits?`<div style="font-size:11px;color:#991b1b;margin-top:6px;">A 3-month bank statement is required if switching to debit order.</div>`:''}
    </div>`;
}

function acQlinkReset(){
  _acQlDeductions=[];_acQlSkyPolicies=[];_acQlAvailable=0;_acQlResult='';
  const np=document.getElementById('acql_newpremium');if(np)np.value='0';
  const sal=document.getElementById('acql_salary');if(sal)sal.value='';
  const fsp=document.getElementById('acql_fspSelect');if(fsp)fsp.value='';
  const amt=document.getElementById('acql_addAmount');if(amt)amt.value='';
  const mw=document.getElementById('acql_manualWrap');if(mw)mw.style.display='none';
  const ps=document.getElementById('acql_payslipStatus');if(ps)ps.style.display='none';
  acQlinkRenderDeductions();acQlinkRenderSkyPolicies();
  const rc=document.getElementById('acql_resultCard');if(rc)rc.style.display='none';
  const fs=document.getElementById('ac_qlFailSection');if(fs)fs.style.display='none';
}

function acQlinkRestore(c){
  _acQlDeductions=(c.qlDeductions||[]).map(d=>({...d}));
  _acQlSkyPolicies=(c.qlSkyPolicies||[]).map(p=>({...p}));
  const sal=document.getElementById('acql_salary');if(sal)sal.value=c.qlink?.salary||'';
  const np=document.getElementById('acql_newpremium');if(np)np.value=c.qlink?.newPremium||'0';
  acQlinkRenderDeductions();acQlinkRenderSkyPolicies();acQlinkCalc_();
}

async function acQlinkHandlePayslip(input){
  const file=input.files[0];if(!file)return;
  const zone=document.getElementById('acql_dropZone');
  const statusEl=document.getElementById('acql_payslipStatus');
  zone.style.opacity='0.5';
  statusEl.style.display='block';
  statusEl.style.background='#fef9ec';statusEl.style.border='1px solid #f5d98b';statusEl.style.color='#92400e';
  statusEl.textContent='⏳ Analysing payslip with AI...';
  try{
    const b64=await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result.split(',')[1]);r.onerror=rej;r.readAsDataURL(file);});
    const mediaType=file.type||'image/jpeg';
    const prompt='This is a South African PERSAL payslip. Extract ALL of the following — do not truncate or summarise, return EVERY item you find:\n1. The basic salary (gross/basic, NOT nett).\n2. EVERY FSP insurance stop order deduction — extract ALL of them, up to 30. These are premiums paid to licensed FSPs for insurance products. INCLUDE: Metropolitan, Old Mutual, Old Mutual Group Schemes (may appear as OM Group Schemes or OMGS), Old Mutual Greenlight, Old Mutual Protect, Sanlam, Sanlam Sky (may appear as Channel Life, Sky, or Sky/Channel Life on the payslip), Momentum, Discovery, Liberty, Assupol, AVBOB, Workerslife, Clientele, 1Life, Emerald Life, Hollard, Absa Life, Absa Lipco, Standard Bank Insurance, FNB Life, Nedgroup, Legalwise, Legal and Tax, Capital Legacy, RMA (Road Accident), Accident insurance, Funeral cover, Life cover, Income protection, Disability cover.\n\nDO NOT INCLUDE: PAYE, income tax, pension fund, provident fund, medical aid, medical scheme, hospital plan, housing subsidy, housing loan, car allowance, transport, equipment deduction, salary sacrifice, union fees, NEHAWU, SADTU, POPCRU, NUM, garnishee orders, maintenance orders, municipality rates, electricity, water, any government department deductions, employer contributions.\n\n3. Policy/member number for each deduction if visible.\n\nReturn ONLY valid JSON — no explanation, no markdown, include ALL deductions found:\n{"basic_salary":15000,"deductions":[{"company":"Metropolitan","amount":350,"policy_number":"12345678"}]}\n\nUse null for policy_number if not visible. Return {"basic_salary":0,"deductions":[]} if unreadable.';
    const rawText=(await callClaudeVision(b64,mediaType,prompt,2048)).replace(/```json|```/g,'').trim();
    const parsed=JSON.parse(rawText);
    if(parsed.basic_salary){const s=document.getElementById('acql_salary');if(s){s.value=parsed.basic_salary;}}
    if(parsed.deductions?.length){
      _acQlDeductions=parsed.deductions.map(d=>({company:d.company||'',amount:parseFloat(d.amount)||0,status:'keep',policy_number:d.policy_number||''}));
      acQlinkRenderDeductions();
    }
    zone.style.opacity='1';
    const dCount=parsed.deductions?.length||0;
    if(dCount===0){
      statusEl.style.background='#fef9ec';statusEl.style.border='1px solid #f5d98b';statusEl.style.color='#92400e';
      statusEl.textContent='⚠️ No stop order deductions found automatically. Please add them manually below.';
    } else {
      statusEl.style.background='#f0fdf4';statusEl.style.border='1px solid #86efac';statusEl.style.color='#166534';
      const polFound=parsed.deductions.filter(d=>d.policy_number).length;
      statusEl.textContent=`✓ Found ${dCount} deduction${dCount!==1?'s':''}${parsed.basic_salary?' · Salary: R'+Number(parsed.basic_salary).toLocaleString():''}${polFound?' · '+polFound+' policy number'+(polFound!==1?'s':''):''} extracted.`;
    }
    acQlinkCalc_();
  }catch(e){
    zone.style.opacity='1';
    statusEl.style.background='#fef2f2';statusEl.style.border='1px solid #fca5a5';statusEl.style.color='#991b1b';
    const isQuota=e.message&&(e.message.includes('quota')||e.message.includes('429'));
    statusEl.textContent=isQuota?'AI analysis is temporarily unavailable — please add deductions manually.':'Could not read the payslip. Please add deductions manually.';
  }
  input.value='';
}

function loadPdfLib(){
  return new Promise((resolve,reject)=>{
    if(window.PDFLib){resolve();return;}
    const s=document.createElement('script');
    s.src='https://unpkg.com/pdf-lib@1.17.1/dist/pdf-lib.min.js';
    s.onload=resolve;s.onerror=reject;
    document.head.appendChild(s);
  });
}

/* ── PROSPECT MAP ── */
const PM_TYPES={
  school:{label:'School/College',icon:'🏫',color:'#1b3460',
    qs:['"amenity"="school"','"amenity"="college"','"amenity"="university"','"amenity"="kindergarten"'],
    detect:t=>['school','college','university','kindergarten'].includes(t.amenity)},
  police:{label:'SAPS',icon:'👮',color:'#dc2626',
    qs:['"amenity"="police"'],
    detect:t=>t.amenity==='police'},
  clinic:{label:'Clinic',icon:'🩺',color:'#16a34a',
    qs:['"amenity"="clinic"','"amenity"="health_post"','"amenity"="doctors"','"healthcare"="clinic"','"amenity"="pharmacy"'],
    detect:t=>['clinic','health_post','doctors','pharmacy'].includes(t.amenity)||t.healthcare==='clinic'},
  hospital:{label:'Hospital',icon:'🏥',color:'#9333ea',
    qs:['"amenity"="hospital"','"amenity"="nursing_home"'],
    detect:t=>['hospital','nursing_home'].includes(t.amenity)},
  prison:{label:'Correctional',icon:'⛓️',color:'#78350f',
    qs:['"amenity"="prison"','"amenity"="detention_centre"'],
    detect:t=>['prison','detention_centre'].includes(t.amenity)},
  government:{label:'Gov / Municipality',icon:'🏛️',color:'#c9922a',
    qs:['"office"="government"','"amenity"="townhall"','"office"="municipality"','"office"="administrative"','"office"="government_office"','"amenity"="community_centre"'],
    detect:t=>['government','municipality','administrative','government_office'].includes(t.office)||['townhall','community_centre'].includes(t.amenity)},
};
const PM_STAGES=['📍 Mapped','👣 Visited','🤝 PIC Met','📅 Meeting Booked','🎤 Presented','✅ LOAs Collected'];
const PM_STAGE_COLORS=['#6b7280','#2563eb','#7c3aed','#d97706','#0891b2','#16a34a'];
let _pmMap=null,_pmMapMarkers=[],_pmActiveTypes=new Set(['school']),_pmCenter=null;

function loadLeaflet(){
  return new Promise((resolve,reject)=>{
    if(window.L){resolve();return;}
    const lk=document.createElement('link');
    lk.rel='stylesheet';lk.href='https://unpkg.com/leaflet@1.9.4/dist/leaflet.css';
    document.head.appendChild(lk);
    const s=document.createElement('script');
    s.src='https://unpkg.com/leaflet@1.9.4/dist/leaflet.js';
    s.onload=resolve;s.onerror=reject;
    document.head.appendChild(s);
  });
}

function pmGetProspects(){return JSON.parse(localStorage.getItem('tl_prospects')||'[]');}
function pmSaveProspects(arr){localStorage.setItem('tl_prospects',JSON.stringify(arr));}

function pmDetectType(tags){
  for(const [key,cfg] of Object.entries(PM_TYPES)){
    if(cfg.detect(tags))return key;
  }
  return null;
}

async function renderProspectMap(){
  document.getElementById('pmStatus').textContent='Loading map…';
  await loadLeaflet();
  if(!_pmMap){
    _pmMap=L.map('pmMap').setView([-26.2041,28.0473],12);
    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{
      attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>',maxZoom:19
    }).addTo(_pmMap);
  }
  setTimeout(()=>{_pmMap.invalidateSize();},150);
  pmRenderPipeline();
  if(!_pmCenter){
    pmUseLocation();
  } else {
    document.getElementById('pmStatus').textContent='';
  }
}

function pmUseLocation(){
  if(!navigator.geolocation){
    document.getElementById('pmStatus').textContent='Geolocation not available — search for your area above.';
    return;
  }
  document.getElementById('pmStatus').textContent='📍 Getting your location…';
  navigator.geolocation.getCurrentPosition(
    pos=>{
      _pmCenter={lat:pos.coords.latitude,lon:pos.coords.longitude};
      _pmMap.setView([_pmCenter.lat,_pmCenter.lon],14);
      if(_pmMap._locMarker)_pmMap.removeLayer(_pmMap._locMarker);
      _pmMap._locMarker=L.circleMarker([_pmCenter.lat,_pmCenter.lon],{
        radius:10,fillColor:'#f59e0b',color:'#fff',weight:3,fillOpacity:1
      }).bindPopup('📍 Your location').addTo(_pmMap);
      pmLoadFacilities();
    },
    err=>{
      document.getElementById('pmStatus').textContent=
        err.code===1?'Location access denied — search for your area above.'
        :'Could not get location — search for your area above.';
    },
    {enableHighAccuracy:true,timeout:10000}
  );
}

function pmToggleFilter(btn){
  const t=btn.dataset.type;
  if(_pmActiveTypes.has(t)){
    if(_pmActiveTypes.size===1)return;
    _pmActiveTypes.delete(t);btn.classList.remove('active');
  }else{
    _pmActiveTypes.add(t);btn.classList.add('active');
  }
  if(_pmCenter)pmLoadFacilities();
}

async function pmSearchArea(){
  const q=document.getElementById('pmSearch').value.trim();
  if(!q)return;
  document.getElementById('pmStatus').textContent='Searching…';
  try{
    const res=await fetch('https://nominatim.openstreetmap.org/search?q='+encodeURIComponent(q+', South Africa')+'&format=json&limit=1',{headers:{'Accept-Language':'en'}});
    const data=await res.json();
    if(!data.length){document.getElementById('pmStatus').textContent='Area not found — try a suburb or city name.';return;}
    _pmCenter={lat:parseFloat(data[0].lat),lon:parseFloat(data[0].lon)};
    _pmMap.setView([_pmCenter.lat,_pmCenter.lon],14);
    await pmLoadFacilities();
  }catch(e){document.getElementById('pmStatus').textContent='Search failed — check your connection.';}
}

async function pmLoadFacilities(){
  if(!_pmCenter)return;
  const {lat,lon}=_pmCenter;
  _pmMapMarkers.forEach(m=>_pmMap.removeLayer(m));
  _pmMapMarkers=[];
  document.getElementById('pmStatus').textContent='Loading facilities…';
  const conditions=[..._pmActiveTypes].flatMap(t=>
    PM_TYPES[t].qs.flatMap(q=>[
      `node[${q}](around:10000,${lat},${lon});`,
      `way[${q}](around:10000,${lat},${lon});`
    ])
  ).join('');
  const overpassQ=`[out:json][timeout:30];(${conditions});out center;`;
  try{
    const res=await fetch('https://overpass-api.de/api/interpreter',{method:'POST',body:'data='+encodeURIComponent(overpassQ)});
    const data=await res.json();
    const els=data.elements||[];
    const existing=pmGetProspects();
    els.forEach(el=>{
      const elLat=el.lat||(el.center&&el.center.lat);
      const elLon=el.lon||(el.center&&el.center.lon);
      if(!elLat||!elLon)return;
      const name=(el.tags&&(el.tags.name||el.tags['name:en']))||'Unnamed facility';
      const type=pmDetectType(el.tags||{});
      if(!type||!_pmActiveTypes.has(type))return;
      const cfg=PM_TYPES[type];
      const alreadyAdded=existing.some(p=>Math.abs(p.lat-elLat)<0.0002&&Math.abs(p.lon-elLon)<0.0002);
      const marker=L.circleMarker([elLat,elLon],{
        radius:8,fillColor:alreadyAdded?'#16a34a':cfg.color,color:'#fff',weight:2,fillOpacity:0.88
      }).addTo(_pmMap);
      const safeN=name.replace(/'/g,"&#39;").replace(/"/g,"&quot;");
      marker.bindPopup(
        `<div style="min-width:160px"><b style="font-size:13px">${cfg.icon} ${safeN}</b><br>`+
        `<span style="font-size:11px;color:#6b7280">${cfg.label}</span><br><br>`+
        (alreadyAdded
          ?`<span style="font-size:11px;color:#16a34a;font-weight:700">✓ Already in pipeline</span>`
          :`<button onclick="pmAddToProspects('${safeN}','${type}',${elLat},${elLon})" style="background:#1b3460;color:#fff;border:none;border-radius:7px;padding:5px 12px;font-size:12px;font-weight:600;cursor:pointer;width:100%">+ Add to Pipeline</button>`
        )+'</div>'
      );
      _pmMapMarkers.push(marker);
    });
    document.getElementById('pmStatus').textContent=els.length
      ?`${els.length} facilit${els.length===1?'y':'ies'} found within 10 km — tap a pin to add`
      :'No facilities found in this area — try a different suburb or filter.';
  }catch(e){document.getElementById('pmStatus').textContent='Could not load facilities — try again.';}
}

function pmAddToProspects(name,type,lat,lon){
  const prospects=pmGetProspects();
  if(prospects.some(p=>Math.abs(p.lat-lat)<0.0002&&Math.abs(p.lon-lon)<0.0002)){
    if(_pmMap)_pmMap.closePopup();
    return;
  }
  const now=new Date();
  prospects.unshift({id:Date.now(),name,type,lat,lon,stage:0,addedAt:now.toISOString(),notes:''});
  pmSaveProspects(prospects);
  pmRenderPipeline();
  if(_pmMap){_pmMap.closePopup();pmLoadFacilities();}
}

function pmUpdateStage(id,stage){
  const p=pmGetProspects();
  const item=p.find(x=>x.id===id);
  if(item){item.stage=+stage;pmSaveProspects(p);pmRenderPipeline();}
}

function pmSaveNotes(id,val){
  const p=pmGetProspects();
  const item=p.find(x=>x.id===id);
  if(item){item.notes=val;pmSaveProspects(p);}
}

function pmRemoveProspect(id){
  pmSaveProspects(pmGetProspects().filter(x=>x.id!==id));
  pmRenderPipeline();
  if(_pmCenter)pmLoadFacilities();
}

function pmRenderPipeline(){
  const el=document.getElementById('pmPipeline');
  const cnt=document.getElementById('pmPipelineCount');
  if(!el)return;
  const prospects=pmGetProspects();
  if(cnt)cnt.textContent=prospects.length?`${prospects.length} prospect${prospects.length===1?'':'s'}`:'';
  if(!prospects.length){
    el.innerHTML='<div style="text-align:center;color:#9ca3af;font-size:13px;padding:24px 16px;background:#f9fafb;border-radius:12px;border:1px dashed #e5e7eb;">Search an area and tap a pin on the map to add facilities to your pipeline.</div>';
    return;
  }
  el.innerHTML=prospects.map(p=>{
    const cfg=PM_TYPES[p.type]||{icon:'📍',label:'Facility'};
    const stageColor=PM_STAGE_COLORS[p.stage]||'#6b7280';
    const added=new Date(p.addedAt);
    const dateStr=added.toLocaleDateString('en-ZA',{day:'numeric',month:'short'});
    return `<div class="pm-prospect-card">
      <div style="font-size:22px;margin-top:2px">${cfg.icon}</div>
      <div style="flex:1;min-width:0;">
        <div style="font-weight:700;font-size:13px;line-height:1.3;margin-bottom:2px;">${p.name}</div>
        <div style="font-size:11px;color:#6b7280;margin-bottom:5px;">${cfg.label} · Added ${dateStr}</div>
        <select onchange="pmUpdateStage(${p.id},this.value)" style="font-size:11px;font-weight:700;border:1px solid #e5e7eb;border-radius:7px;padding:3px 6px;color:${stageColor};background:#f9fafb;cursor:pointer;margin-bottom:6px;">
          ${PM_STAGES.map((s,i)=>`<option value="${i}" ${p.stage===i?'selected':''}>${s}</option>`).join('')}
        </select>
        <input type="text" placeholder="Notes (PIC name, number, etc.)" value="${(p.notes||'').replace(/"/g,'&quot;')}" onblur="pmSaveNotes(${p.id},this.value)" style="width:100%;font-size:11px;border:1px solid #e5e7eb;border-radius:7px;padding:4px 8px;box-sizing:border-box;color:#374151;">
      </div>
      <button onclick="pmRemoveProspect(${p.id})" style="background:none;border:none;color:#d1d5db;cursor:pointer;font-size:18px;padding:0;line-height:1;margin-top:2px;" title="Remove">✕</button>
    </div>`;
  }).join('');
}

function mdInit(){
  _mdFiles=[];
  mdRenderList();
}

function mdHandleDrop(e){
  e.preventDefault();
  document.getElementById('mdDropZone').style.borderColor='#e5e7eb';
  const files=Array.from(e.dataTransfer.files);
  mdPushFiles(files);
}

function openCameraCapture(cb){
  const inp=document.createElement('input');
  inp.type='file';inp.accept='image/*';inp.setAttribute('capture','environment');inp.style.display='none';
  document.body.appendChild(inp);
  inp.onchange=function(){if(this.files&&this.files.length)cb(this);setTimeout(()=>{try{inp.remove();}catch(e){}},0);};
  inp.click();
  setTimeout(()=>{try{inp.remove();}catch(e){}},30000);
}

function mdAddFiles(input){
  mdPushFiles(Array.from(input.files));
  input.value='';
}

function mdPushFiles(files){
  const allowed=['image/jpeg','image/jpg','image/png','application/pdf'];
  files.forEach(f=>{
    if(!allowed.includes(f.type)&&!f.name.match(/\.(jpg|jpeg|png|pdf)$/i))return;
    if(_mdFiles.length>=8)return;
    _mdFiles.push(f);
  });
  mdRenderList();
}

function mdRemoveFile(i){
  _mdFiles.splice(i,1);
  mdRenderList();
}

function loadPdfJs(){
  return new Promise((resolve,reject)=>{
    if(window.pdfjsLib){resolve();return;}
    const s=document.createElement('script');
    s.src='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js';
    s.onload=()=>{
      window.pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';
      resolve();
    };
    s.onerror=reject;
    document.head.appendChild(s);
  });
}

async function mdRasterizePdf(bytes,scale,quality){
  await loadPdfJs();
  const pdf=await window.pdfjsLib.getDocument({data:new Uint8Array(bytes)}).promise;
  const pages=[];
  for(let i=1;i<=pdf.numPages;i++){
    const page=await pdf.getPage(i);
    const vp=page.getViewport({scale});
    const canvas=document.createElement('canvas');
    canvas.width=Math.round(vp.width);canvas.height=Math.round(vp.height);
    await page.render({canvasContext:canvas.getContext('2d'),viewport:vp}).promise;
    const blob=await new Promise(res=>canvas.toBlob(res,'image/jpeg',quality));
    const ab=new Uint8Array(await blob.arrayBuffer());
    pages.push({w:Math.round(vp.width),h:Math.round(vp.height),ab});
  }
  return pages;
}

async function mdBuild(compress,onProg){
  await loadPdfLib();
  const {PDFDocument}=window.PDFLib;
  const merged=await PDFDocument.create();
  const A4W=595,A4H=842;
  const imgMax=compress?900:1600,imgQ=compress?0.60:0.82;
  const n=_mdFiles.length;
  for(let i=0;i<n;i++){
    const f=_mdFiles[i];
    const pct=5+Math.round((i/n)*88);
    if(onProg)onProg(pct,`${compress?'Compressing':'Processing'} file ${i+1} of ${n} — ${f.name.length>28?f.name.slice(0,26)+'…':f.name}`);
    const bytes=await f.arrayBuffer();
    const isPdf=f.type==='application/pdf'||f.name.toLowerCase().endsWith('.pdf');
    if(isPdf){
      if(compress){
        let pages;
        try{pages=await mdRasterizePdf(bytes,1.0,0.60);}catch(e){showAlert('Could not compress '+f.name+' — skipped.','error');continue;}
        for(const pg of pages){
          try{
            const img=await merged.embedJpg(new Uint8Array(pg.ab));
            const sc=Math.min(A4W/pg.w,A4H/pg.h,1);
            const pw=pg.w*sc,ph=pg.h*sc;
            const p=merged.addPage([A4W,A4H]);
            p.drawImage(img,{x:(A4W-pw)/2,y:(A4H-ph)/2,width:pw,height:ph});
          }catch(e){/* skip */}
        }
      } else {
        let src;
        try{src=await PDFDocument.load(new Uint8Array(bytes),{ignoreEncryption:true});}catch(e){showAlert('Could not read '+f.name+' — skipped.','error');continue;}
        try{
          const copied=await merged.copyPages(src,src.getPageIndices());
          copied.forEach(p=>merged.addPage(p));
        }catch(e){showAlert('Could not copy pages from '+f.name+' — skipped.','error');}
      }
    } else {
      try{
        const compBytes=await mdCompressImg(f,imgMax,imgQ);
        let img;
        const isPng=f.name.toLowerCase().endsWith('.png');
        if(isPng&&!compBytes){
          img=await merged.embedPng(new Uint8Array(bytes));
        } else {
          const src=compBytes?new Uint8Array(compBytes):new Uint8Array(bytes);
          try{img=await merged.embedJpg(src);}
          catch(e){img=await merged.embedPng(src);}
        }
        const sc=Math.min(A4W/img.width,A4H/img.height,1);
        const w=img.width*sc,h=img.height*sc;
        const p=merged.addPage([A4W,A4H]);
        p.drawImage(img,{x:(A4W-w)/2,y:(A4H-h)/2,width:w,height:h});
      }catch(e){showAlert('Could not embed image '+f.name+' — skipped.','error');}
    }
  }
  return await merged.save();
}

function mdMoveFile(i,dir){
  const j=i+dir;
  if(j<0||j>=_mdFiles.length)return;
  [_mdFiles[i],_mdFiles[j]]=[_mdFiles[j],_mdFiles[i]];
  mdRenderList();
}

function mdRenderList(){
  const el=document.getElementById('mdFileList');
  const btn=document.getElementById('mdMergeBtn');
  const fnWrap=document.getElementById('mdFilenameWrap');
  if(!el)return;
  if(!_mdFiles.length){
    el.innerHTML='';
    if(btn){btn.style.opacity='0.45';btn.style.pointerEvents='none';}
    if(fnWrap)fnWrap.style.display='none';
    return;
  }
  if(btn){btn.style.opacity='1';btn.style.pointerEvents='auto';}
  if(fnWrap)fnWrap.style.display='block';
  const n=_mdFiles.length;
  el.innerHTML=`<div style="margin-bottom:8px;">`+_mdFiles.map((f,i)=>{
    const isImg=f.type.startsWith('image/')||f.name.match(/\.(jpg|jpeg|png)$/i);
    const icon=isImg?'🖼️':'📄';
    const tag=isImg?'→ PDF':'PDF';
    const sz=(f.size/1024).toFixed(0);
    const upDis=i===0;const dnDis=i===n-1;
    const btnS='background:#fff;border:1px solid #e5e7eb;border-radius:5px;font-size:10px;line-height:1;padding:3px 5px;cursor:pointer;';
    return`<div style="display:flex;align-items:center;gap:8px;padding:9px 12px;background:#f9f9f9;border:1px solid #e5e7eb;border-radius:8px;margin-bottom:5px;">
      <div style="display:flex;flex-direction:column;gap:3px;flex-shrink:0;">
        <button onclick="mdMoveFile(${i},-1)" ${upDis?'disabled':''} style="${btnS}color:${upDis?'#d1d5db':'#374151'};">▲</button>
        <button onclick="mdMoveFile(${i},1)" ${dnDis?'disabled':''} style="${btnS}color:${dnDis?'#d1d5db':'#374151'};">▼</button>
      </div>
      <span style="font-size:10px;font-weight:700;color:#9ca3af;flex-shrink:0;min-width:12px;text-align:center;">${i+1}</span>
      <span style="font-size:18px;flex-shrink:0;">${icon}</span>
      <div style="flex:1;min-width:0;">
        <div style="font-size:12px;font-weight:700;color:#0d1f3c;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${f.name}</div>
        <div style="font-size:10px;color:#9ca3af;">${tag} · ${sz} KB</div>
      </div>
      ${isImg?`<button onclick="mdCropFile(${i})" title="Crop image" style="background:#f3f4f6;border:1px solid #e5e7eb;border-radius:6px;color:#374151;cursor:pointer;font-size:13px;padding:4px 7px;flex-shrink:0;">✂️</button>`:''}
      <button onclick="mdRemoveFile(${i})" style="background:none;border:none;color:#9ca3af;cursor:pointer;font-size:16px;line-height:1;flex-shrink:0;">✕</button>
    </div>`;
  }).join('')+`</div><div style="font-size:10px;color:#9ca3af;padding:0 2px;">${n}/8 files · ${n<8?'Tap above to add more':'Maximum reached'}</div>`;
}

function mdCropFile(i){
  const f=_mdFiles[i];
  if(!f||!(f.type.startsWith('image/')||f.name.match(/\.(jpg|jpeg|png)$/i)))return;
  let modal=document.getElementById('mdCropModal');
  if(!modal){
    modal=document.createElement('div');
    modal.id='mdCropModal';
    modal.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,0.88);z-index:9999;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:16px;box-sizing:border-box;';
    modal.innerHTML=`<div style="width:100%;max-width:460px;">
      <div style="color:#fff;font-size:15px;font-weight:700;margin-bottom:6px;text-align:center;">✂️ Crop Image</div>
      <div style="font-size:11px;color:#9ca3af;text-align:center;margin-bottom:10px;">Drag on the image to select the area to keep</div>
      <div style="position:relative;line-height:0;border-radius:8px;overflow:hidden;background:#000;">
        <canvas id="mdCropCanvas" style="display:block;max-width:100%;cursor:crosshair;touch-action:none;"></canvas>
      </div>
      <div id="mdCropDims" style="font-size:10px;color:#9ca3af;text-align:center;margin-top:8px;min-height:14px;"></div>
      <div style="display:flex;gap:10px;margin-top:12px;">
        <button onclick="mdCancelCrop()" style="flex:1;padding:12px;background:#374151;color:#fff;border:none;border-radius:10px;font-size:13px;font-weight:700;cursor:pointer;">Cancel</button>
        <button onclick="mdApplyCrop()" style="flex:1;padding:12px;background:#0d1f3c;color:#fff;border:none;border-radius:10px;font-size:13px;font-weight:700;cursor:pointer;">Apply Crop</button>
      </div>
    </div>`;
    document.body.appendChild(modal);
  } else {
    modal.style.display='flex';
  }
  const url=URL.createObjectURL(f);
  const img=new Image();
  img.onload=()=>{
    URL.revokeObjectURL(url);
    const canvas=document.getElementById('mdCropCanvas');
    const maxW=Math.min(window.innerWidth-48,428);
    const maxH=window.innerHeight*0.55;
    const scale=Math.min(maxW/img.width,maxH/img.height,1);
    const dw=Math.round(img.width*scale);
    const dh=Math.round(img.height*scale);
    canvas.width=dw;canvas.height=dh;
    _mdCropState={idx:i,img,scale,dispW:dw,dispH:dh,sel:{x:0,y:0,w:dw,h:dh},drag:null};
    mdCropAttach(canvas);
    mdCropDraw();
  };
  img.src=url;
}

function mdCropDraw(){
  const s=_mdCropState;if(!s)return;
  const canvas=document.getElementById('mdCropCanvas');
  if(!canvas)return;
  const ctx=canvas.getContext('2d');
  ctx.drawImage(s.img,0,0,s.dispW,s.dispH);
  ctx.fillStyle='rgba(0,0,0,0.52)';
  ctx.fillRect(0,0,s.dispW,s.dispH);
  const {x,y,w,h}=s.sel;
  if(w>1&&h>1){
    ctx.drawImage(s.img,x/s.scale,y/s.scale,w/s.scale,h/s.scale,x,y,w,h);
    ctx.strokeStyle='#fff';ctx.lineWidth=1.5;ctx.setLineDash([5,3]);
    ctx.strokeRect(x+0.5,y+0.5,w-1,h-1);ctx.setLineDash([]);
    const hs=7;ctx.fillStyle='#fff';
    [[x,y],[x+w,y],[x,y+h],[x+w,y+h]].forEach(([hx,hy])=>ctx.fillRect(hx-hs/2,hy-hs/2,hs,hs));
  }
  const d=document.getElementById('mdCropDims');
  if(d)d.textContent=(w>1&&h>1)?`${Math.round(w/s.scale)} × ${Math.round(h/s.scale)} px`:'';
}

function mdCropPos(canvas,e){
  const r=canvas.getBoundingClientRect();
  const cx=e.touches?e.touches[0].clientX:e.clientX;
  const cy=e.touches?e.touches[0].clientY:e.clientY;
  const sx=canvas.width/r.width,sy=canvas.height/r.height;
  return{x:Math.max(0,Math.min(canvas.width,(cx-r.left)*sx)),y:Math.max(0,Math.min(canvas.height,(cy-r.top)*sy))};
}

function mdCropAttach(canvas){
  const c=canvas;
  const down=e=>{e.preventDefault();const p=mdCropPos(c,e);_mdCropState.drag={sx:p.x,sy:p.y};};
  const move=e=>{
    e.preventDefault();if(!_mdCropState||!_mdCropState.drag)return;
    const p=mdCropPos(c,e);const{sx,sy}=_mdCropState.drag;
    _mdCropState.sel={x:Math.min(sx,p.x),y:Math.min(sy,p.y),w:Math.abs(p.x-sx),h:Math.abs(p.y-sy)};
    mdCropDraw();
  };
  const up=e=>{
    e.preventDefault();
    if(_mdCropState&&_mdCropState.sel.w<5){
      _mdCropState.sel={x:0,y:0,w:_mdCropState.dispW,h:_mdCropState.dispH};
      mdCropDraw();
    }
    if(_mdCropState)_mdCropState.drag=null;
  };
  c.addEventListener('mousedown',down);c.addEventListener('mousemove',move);c.addEventListener('mouseup',up);
  c.addEventListener('touchstart',down,{passive:false});c.addEventListener('touchmove',move,{passive:false});c.addEventListener('touchend',up,{passive:false});
}

function mdCancelCrop(){
  _mdCropState=null;
  const m=document.getElementById('mdCropModal');if(m)m.style.display='none';
}

async function mdApplyCrop(){
  const s=_mdCropState;
  if(!s||s.sel.w<2||s.sel.h<2)return;
  const cx=Math.round(s.sel.x/s.scale),cy=Math.round(s.sel.y/s.scale);
  const cw=Math.round(s.sel.w/s.scale),ch=Math.round(s.sel.h/s.scale);
  const out=document.createElement('canvas');
  out.width=cw;out.height=ch;
  out.getContext('2d').drawImage(s.img,cx,cy,cw,ch,0,0,cw,ch);
  const blob=await new Promise(res=>out.toBlob(res,'image/jpeg',0.92));
  const name=_mdFiles[s.idx].name.replace(/\.[^.]+$/,'')+'_cropped.jpg';
  _mdFiles[s.idx]=new File([blob],name,{type:'image/jpeg'});
  mdCancelCrop();
  mdRenderList();
}

function mdSetProgress(status,pct,msg){
  if(!status)return;
  status.innerHTML=`<div style="padding:4px 0;">
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:5px;">
      <span style="font-size:11px;color:#6b7280;">${msg}</span>
      <span style="font-size:11px;font-weight:700;color:#374151;">${Math.round(pct)}%</span>
    </div>
    <div style="background:#e5e7eb;border-radius:999px;height:7px;overflow:hidden;">
      <div style="background:linear-gradient(90deg,#1b4f8a,#c9922a);height:100%;width:${pct}%;border-radius:999px;transition:width 0.25s ease;"></div>
    </div>
  </div>`;
}

async function mdMerge(){
  if(!_mdFiles.length)return;
  const btn=document.getElementById('mdMergeBtn');
  const status=document.getElementById('mdStatus');
  btn.disabled=true;btn.textContent='Merging…';
  mdSetProgress(status,2,'Loading PDF engine — may take 10–30 sec for large files…');
  const dl=(out,mb,label)=>{
    const fnInput=document.getElementById('mdFileName');
    const rawName=(fnInput&&fnInput.value.trim())||'merged-document';
    const fname=rawName.toLowerCase().endsWith('.pdf')?rawName:rawName+'.pdf';
    const blob=new Blob([out],{type:'application/pdf'});
    const url=URL.createObjectURL(blob);
    const a=document.createElement('a');a.href=url;a.download=fname;
    document.body.appendChild(a);a.click();document.body.removeChild(a);
    setTimeout(()=>URL.revokeObjectURL(url),2000);
    if(status)status.innerHTML=`<div style="background:#dcfce7;border:1px solid #86efac;border-radius:8px;padding:10px 12px;font-size:12px;color:#166534;font-weight:600;">✓ Downloaded${label?' ('+label+')':''} — ${mb}MB · ${_mdFiles.length} file${_mdFiles.length!==1?'s':''} merged · saved as ${fname}</div>`;
  };
  try{
    const out=await mdBuild(false,(pct,msg)=>mdSetProgress(status,pct,msg));
    mdSetProgress(status,98,'Finalising…');
    const mb=(out.byteLength/(1024*1024)).toFixed(2);
    if(parseFloat(mb)>4.0){
      mdSetProgress(status,2,`📦 ${mb}MB — auto-compressing to fit 4MB IMP limit…`);
      btn.textContent='Compressing…';
      const outC=await mdBuild(true,(pct,msg)=>mdSetProgress(status,pct,msg));
      mdSetProgress(status,98,'Finalising compressed PDF…');
      const mbC=(outC.byteLength/(1024*1024)).toFixed(2);
      if(parseFloat(mbC)>4.0){
        if(status)status.innerHTML=`<div style="background:#fef2f2;border:1px solid #fca5a5;border-radius:8px;padding:10px 12px;font-size:12px;color:#991b1b;font-weight:600;">⚠️ Compressed file is still ${mbC}MB — still exceeds 4MB. Upload the bank statement or payslip separately to IMP.</div>`;
        btn.disabled=false;btn.textContent='Merge & Download PDF';return;
      }
      dl(outC,mbC,'compressed');
    } else {
      dl(out,mb,'');
    }
  } catch(err){
    if(status)status.innerHTML=`<div style="background:#fef2f2;border:1px solid #fca5a5;border-radius:8px;padding:10px 12px;font-size:12px;color:#991b1b;font-weight:600;">Error: ${err.message}</div>`;
  }
  btn.disabled=false;btn.textContent='Merge & Download PDF';
}

function mdCompressImg(file,maxPx,quality){
  if(maxPx===undefined)maxPx=1600;
  if(quality===undefined)quality=0.82;
  return new Promise(resolve=>{
    const url=URL.createObjectURL(file);
    const img=new Image();
    img.onload=()=>{
      URL.revokeObjectURL(url);
      let w=img.width,h=img.height;
      if(w>maxPx||h>maxPx){if(w>h){h=Math.round(h*maxPx/w);w=maxPx;}else{w=Math.round(w*maxPx/h);h=maxPx;}}
      const c=document.createElement('canvas');c.width=w;c.height=h;
      c.getContext('2d').drawImage(img,0,0,w,h);
      c.toBlob(b=>{
        if(!b){resolve(null);return;}
        const r=new FileReader();
        r.onload=e=>resolve(e.target.result);
        r.readAsArrayBuffer(b);
      },'image/jpeg',0.82);
    };
    img.onerror=()=>{URL.revokeObjectURL(url);resolve(null);};
    img.src=url;
  });
}

// ── SIGNATURE PAD ──
function sigInitCanvas(){
  const canvas=document.getElementById('sigCanvas');
  if(!canvas||canvas._sigReady)return;
  canvas._sigReady=true;
  const ctx=canvas.getContext('2d');
  let drawing=false,lx,ly;
  function pos(e){
    const r=canvas.getBoundingClientRect();
    const sx=canvas.width/r.width,sy=canvas.height/r.height;
    const t=e.touches?e.touches[0]:e;
    return[(t.clientX-r.left)*sx,(t.clientY-r.top)*sy];
  }
  canvas.addEventListener('mousedown',e=>{drawing=true;[lx,ly]=pos(e);});
  canvas.addEventListener('mousemove',e=>{
    if(!drawing)return;const[x,y]=pos(e);
    ctx.beginPath();ctx.moveTo(lx,ly);ctx.lineTo(x,y);
    ctx.strokeStyle='#0d1f3c';ctx.lineWidth=2.2;ctx.lineCap='round';ctx.lineJoin='round';ctx.stroke();
    [lx,ly]=[x,y];
  });
  canvas.addEventListener('mouseup',()=>drawing=false);
  canvas.addEventListener('mouseleave',()=>drawing=false);
  canvas.addEventListener('touchstart',e=>{e.preventDefault();drawing=true;[lx,ly]=pos(e);},{passive:false});
  canvas.addEventListener('touchmove',e=>{
    e.preventDefault();if(!drawing)return;const[x,y]=pos(e);
    ctx.beginPath();ctx.moveTo(lx,ly);ctx.lineTo(x,y);
    ctx.strokeStyle='#0d1f3c';ctx.lineWidth=2.2;ctx.lineCap='round';ctx.lineJoin='round';ctx.stroke();
    [lx,ly]=[x,y];
  },{passive:false});
  canvas.addEventListener('touchend',()=>drawing=false);
}
function sigLoadDisplay(){
  const code=currentUser?.code;if(!code)return;
  const saved=localStorage.getItem('tl_sig_'+code);
  const disp=document.getElementById('sigDisplay');
  const img=document.getElementById('sigImg');
  if(saved&&disp&&img){img.src=saved;disp.style.display='block';}
  else if(disp)disp.style.display='none';
}
function sigClearCanvas(){
  const c=document.getElementById('sigCanvas');if(c)c.getContext('2d').clearRect(0,0,c.width,c.height);
}
function sigSaveFromCanvas(){
  const c=document.getElementById('sigCanvas');if(!c)return;
  const d=c.getContext('2d').getImageData(0,0,c.width,c.height).data;
  if(![...d].some(x=>x!==0))return showAlert('Please draw your signature first.','error');
  localStorage.setItem('tl_sig_'+currentUser.code,c.toDataURL('image/png'));
  sigClearCanvas();sigLoadDisplay();showAlert('Signature saved.','success');
}
function sigClear(){
  if(!confirm('Remove your saved signature?'))return;
  localStorage.removeItem('tl_sig_'+currentUser.code);sigLoadDisplay();
}

