// ── NTU & PERSISTENCY DASHBOARD ─────────────────────────────────────────────
function getNTUCases(){try{return JSON.parse(localStorage.getItem('tl_ntu_cases')||'[]');}catch(e){return[];}}
function saveNTUCases(d){localStorage.setItem('tl_ntu_cases',JSON.stringify(d));}
function ntuLogCase(){
  const advisorSel=document.getElementById('ntu-advisor');
  const advCode=advisorSel?advisorSel.value:'';
  const advName=advisorSel&&advisorSel.selectedIndex>=0?advisorSel.options[advisorSel.selectedIndex].text:'';
  const type=document.getElementById('ntu-type').value;
  const client=document.getElementById('ntu-client').value.trim();
  const month=document.getElementById('ntu-month').value;
  if(!advCode||!client)return showAlert('Please select an advisor and enter client name.','error');
  const cases=getNTUCases();
  cases.push({id:Date.now()+'_'+Math.random().toString(36).slice(2),advisorCode:advCode,advisorName:advName,type,client,month,loggedAt:new Date().toISOString()});
  saveNTUCases(cases);
  document.getElementById('ntu-client').value='';
  renderNTUDash();
  showAlert('Case logged.','success');
}
function ntuDeleteCase(id){
  saveNTUCases(getNTUCases().filter(x=>x.id!==id));renderNTUDash();
}
function renderNTUDash(){
  const el=document.getElementById('ntuDashboard');if(!el)return;
  // Populate advisor dropdown
  const sel=document.getElementById('ntu-advisor');
  if(sel){
    const users=getUsers();
    const advisors=Object.values(users).filter(u=>!u.isOps&&!u.isManager).sort((a,b)=>a.name.localeCompare(b.name));
    sel.innerHTML='<option value="">Select advisor...</option>'+advisors.map(a=>`<option value="${a.code}">${a.name}</option>`).join('');
  }
  const allCCases=getCCases();
  const ntuCases=getNTUCases();
  const users=getUsers();
  const advisors=Object.values(users).filter(u=>!u.isOps&&!u.isManager);
  if(!advisors.length){el.innerHTML='<div style="text-align:center;color:#9ca3af;font-size:13px;padding:2rem;">No advisors found.</div>';return;}
  el.innerHTML=advisors.map(adv=>{
    const written=allCCases.filter(c=>c.advisorCode===adv.code).length;
    const ntu=ntuCases.filter(c=>c.advisorCode===adv.code&&c.type==='ntu').length;
    const lapsed=ntuCases.filter(c=>c.advisorCode===adv.code&&c.type==='lapse').length;
    const ntuPct=written>0?Math.round(ntu/written*100):0;
    const persistPct=written>0?Math.round((written-lapsed)/Math.max(written,1)*100):100;
    const ntuWarn=ntuPct>15;const persistWarn=persistPct<65;
    const ntuCol=ntuWarn?'#dc2626':'#16a34a';const persistCol=persistWarn?'#dc2626':'#16a34a';
    const recentNTU=ntuCases.filter(c=>c.advisorCode===adv.code).slice(-3).reverse();
    return`<div class="ntu-adv-card">
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:10px;">
        <div style="font-size:14px;font-weight:700;color:#0d1f3c;">${adv.name}</div>
        <div style="display:flex;gap:6px;">
          ${ntuWarn?'<div style="background:#fef2f2;color:#991b1b;font-size:10px;font-weight:700;padding:3px 8px;border-radius:20px;">⚠️ NTU HIGH</div>':''}
          ${persistWarn?'<div style="background:#fef2f2;color:#991b1b;font-size:10px;font-weight:700;padding:3px 8px;border-radius:20px;">⚠️ PERSIST LOW</div>':''}
        </div>
      </div>
      <div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:10px;margin-bottom:12px;">
        <div style="text-align:center;"><div style="font-size:18px;font-weight:800;color:#0d1f3c;">${written}</div><div style="font-size:10px;color:#9ca3af;font-weight:700;text-transform:uppercase;">Cases written</div></div>
        <div style="text-align:center;"><div style="font-size:18px;font-weight:800;color:${ntuCol};">${ntuPct}%</div><div style="font-size:10px;color:#9ca3af;font-weight:700;text-transform:uppercase;">NTU rate</div>
          <div class="ntu-bar-wrap"><div class="ntu-bar" style="width:${Math.min(ntuPct,100)}%;background:${ntuCol};"></div></div>
          <div style="font-size:9px;color:#9ca3af;margin-top:2px;">Target: below 15%</div>
        </div>
        <div style="text-align:center;"><div style="font-size:18px;font-weight:800;color:${persistCol};">${persistPct}%</div><div style="font-size:10px;color:#9ca3af;font-weight:700;text-transform:uppercase;">Persistency</div>
          <div class="ntu-bar-wrap"><div class="ntu-bar" style="width:${persistPct}%;background:${persistCol};"></div></div>
          <div style="font-size:9px;color:#9ca3af;margin-top:2px;">Target: above 65%</div>
        </div>
      </div>
      ${recentNTU.length?`<div style="border-top:1px solid #f4f2ed;padding-top:8px;"><div style="font-size:10px;font-weight:700;color:#9ca3af;text-transform:uppercase;letter-spacing:.5px;margin-bottom:6px;">Recent NTU / lapses</div>${recentNTU.map(c=>`<div style="display:flex;align-items:center;justify-content:space-between;padding:4px 0;"><div style="font-size:12px;font-weight:600;color:#0d1f3c;">${c.client} <span style="font-size:10px;color:${c.type==='ntu'?'#dc2626':'#d97706'};font-weight:700;">(${c.type==='ntu'?'NTU':'Lapsed'})</span></div><div style="display:flex;align-items:center;gap:6px;"><div style="font-size:10px;color:#9ca3af;">${c.month}</div><button onclick="ntuDeleteCase('${c.id}')" style="background:none;border:none;color:#9ca3af;cursor:pointer;font-size:12px;padding:2px;">✕</button></div></div>`).join('')}</div>`:''
    }</div>`;
  }).join('');
}
// ── END NTU & PERSISTENCY ────────────────────────────────────────────────────

// ── ROA COMPLIANCE CHECKLIST ─────────────────────────────────────────────────
function roaChecklistToggle(){
  const body=document.getElementById('roaChecklistBody');
  const chev=document.getElementById('roaChecklistChev');
  if(!body)return;
  const open=body.style.display!=='none';
  body.style.display=open?'none':'block';
  if(chev)chev.style.transform=open?'':'rotate(180deg)';
}
document.addEventListener('change',function(e){
  if(e.target&&e.target.classList.contains('roa-cl-cb')){
    const cbs=document.querySelectorAll('.roa-cl-cb');
    const done=[...cbs].filter(c=>c.checked).length;
    const total=cbs.length;
    const st=document.getElementById('roaClStatus');
    if(st){
      if(done===total)st.innerHTML='<span style="color:#16a34a;">✓ All '+total+' items checked — ROA is compliance-ready</span>';
      else st.innerHTML=`<span style="color:#d97706;">${done}/${total} items checked</span>`;
    }
  }
});
