// ── Replacement Disclosure & Client Acknowledgment ──

function _form_repl_disclosure(u,today){
  const advName=u.name||'';
  const clauses=[
    {n:'1.',bold:true, text:'I have voluntarily opted in to proceed with this replacement and confirm that this decision was made of my own free will.'},
    {n:'2.',bold:true, text:'I confirm that I have been fully informed of the implications of replacing my existing policy/policies.'},
    {n:'3.',bold:false,text:`<strong>I understand that:</strong><br>
      &nbsp;– Existing policies will be cancelled where applicable.<br>
      &nbsp;– The current insurer(s) may contact me via SMS, phone call, or other means to confirm cancellation and may attempt to retain my policy.<br>
      &nbsp;– The new policy may reflect as "new business" on systems, but I acknowledge that it forms part of a replacement as explained to me.`},
    {n:'4.',bold:false,text:`<strong>Waiting Periods – Disclosure and Understanding</strong><br>
      I confirm that waiting periods have been fully explained to me and that I understand the following:<br>
      &nbsp;– Waiting periods that have already been served on existing policies for the same lives and equivalent cover amounts will be waived under the replacement policy where applicable.<br>
      &nbsp;– Any new lives insured and/or additional or increased cover amounts that have not previously served a waiting period will be subject to new waiting periods, exclusions, or underwriting terms.<br>
      &nbsp;– I understand how these conditions apply specifically to my replacement.`},
    {n:'5.',bold:true, text:'I acknowledge that I may lose certain benefits, values, or features associated with my existing policy/policies, depending on the structure of the replacement.'},
    {n:'6.',bold:true, text:'I confirm that I have not been misled, pressured, or unduly influenced into making this decision.'},
    {n:'7.',bold:false,text:`<strong>Acknowledgment of External Policy Movement / Cancellation</strong><br>
      I acknowledge that this replacement involves the movement and/or cancellation of existing policies with external insurers where applicable, and I provide full consent for such cancellations to be processed.`},
    {n:'8.',bold:false,text:`<strong>Verification of Personal Details Across Policies</strong><br>
      I confirm that all my personal details, including but not limited to names, surnames, and dates of birth, have been reviewed and corrected where necessary on both previous and new policies to ensure accuracy and to prevent any potential claim-related issues.`},
    {n:'9.',bold:false,text:`<strong>Policy Classification and System Representation</strong><br>
      I understand that, due to system and administrative processes, my new policy may be reflected as "new business" when viewed on certain systems or when discussed with representatives who may have limited access to my full policy history.`},
    {n:'10.',bold:false,text:'I acknowledge that, despite this system classification, this policy forms part of a replacement of my previous policy/policies, and must be considered as such.'},
    {n:'11.',bold:false,text:'I confirm that the replacement process, including the implications, benefits, and potential disadvantages, has been fully explained to me by my financial advisor, and that I understand the nature of this transaction.'},
    {n:'12.',bold:false,text:'I further acknowledge that any information received from third parties or representatives who are not fully aware of my full replacement context should be considered in conjunction with the advice and documentation provided to me at the time of this replacement.'},
    {n:'13.',bold:false,text:'To avoid any confusion, administrative errors, or potential claim-related hurdles, I understand that it is advisable to contact the financial advisor and/or manager who assisted me with my replacement for clarification or guidance.'},
    {n:'14.',bold:true,text:'I confirm that I understand the advice provided to me and that I have had the opportunity to ask questions and receive satisfactory answers.'},
    {n:'15.',bold:true,text:'I hereby give full written consent to proceed with the replacement policy.'},
  ];
  return _fs()+`
  <div class="fd">
    <div style="text-align:center;text-decoration:underline;font-size:15px;font-weight:700;margin-bottom:20px;">Replacement Disclosure &amp; Client Acknowledgment</div>

    <p style="font-size:13px;line-height:1.9;margin-bottom:6px;">
      I, <input type="text" placeholder="Full Name" class="fu" style="width:220px;"> (Full Name),
    </p>
    <p style="font-size:13px;line-height:1.9;margin-bottom:16px;">
      ID Number <input type="text" placeholder="ID Number" class="fu" style="width:200px;">, hereby confirm that I have voluntarily elected and requested to replace my existing policy/policies with a new policy issued by Sanlam Sky.
    </p>

    <p style="font-size:13px;font-weight:600;margin-bottom:12px;">By signing this document, I acknowledge and confirm that:</p>

    ${clauses.map((c,i)=>`
      <div style="display:flex;align-items:flex-start;gap:10px;margin-bottom:12px;">
        <div style="flex-shrink:0;display:flex;flex-direction:column;align-items:center;gap:2px;">
          <canvas id="sig_rd_clause_${i}" data-sig="1" width="70" height="36" style="border:1.5px solid #555;border-radius:3px;cursor:crosshair;display:block;touch-action:none;background:#fff;"></canvas>
          <button class="no-print" onclick="clearCanvas('sig_rd_clause_${i}')" style="font-size:9px;color:#aaa;background:none;border:none;cursor:pointer;padding:0;line-height:1;">✕ clear</button>
        </div>
        <p style="font-size:12.5px;line-height:1.7;margin:0;flex:1;">${c.n} ${c.text}</p>
      </div>`).join('')}

    <div style="margin-top:24px;display:grid;grid-template-columns:1fr 1fr;gap:24px;">
      <div>
        <div style="font-size:12px;font-weight:600;margin-bottom:8px;">Client Signature:</div>
        ${_sigBlock('sig_rd_client',220,75)}
        <div class="ffr" style="margin-top:8px;"><label>Date:</label><input type="date" class="fu" value="${today}" style="flex:1;"></div>
      </div>
      <div>
        <div class="ffr"><label style="white-space:nowrap;">Financial Advisor Name:</label><input type="text" class="fu" style="flex:1;" value="${advName}"></div>
        <div style="font-size:12px;font-weight:600;margin:8px 0;">Advisor Signature:</div>
        ${_sigBlock('sig_rd_adv',220,75)}
        <div class="ffr" style="margin-top:8px;"><label>Date:</label><input type="date" class="fu" value="${today}" style="flex:1;"></div>
      </div>
    </div>
  </div>`;
}

// ── CANCELLATION PACK BUILDER ─────────────────────────────────────────────────
let _cpFiles={};
const _cpSlots=[
  {id:'cpID',   label:'Client ID / Driver\'s licence',       icon:'🪪', note:'Clear, legible copy'},
  {id:'cpLOA',  label:'Letter of Authority (LOA)',            icon:'✍️', note:'Signed by the client'},
  {id:'cpCancel',label:'Signed cancellation instruction',    icon:'📝', note:'Completed cancellation form or letter'},
  {id:'cpBank', label:'Bank statement (1 month)',             icon:'🏦', note:'1 month is sufficient'},
];
function cpInit(){
  const container=document.getElementById('cpSlotList');
  if(!container)return;
  _cpFiles={};
  container.innerHTML=_cpSlots.map(s=>`
    <div id="cpslot_${s.id}" style="display:flex;align-items:center;gap:10px;background:#f9fafb;border:1.5px solid #e5e7eb;border-radius:10px;padding:10px 12px;transition:border-color .2s;">
      <span style="font-size:20px;flex-shrink:0;">${s.icon}</span>
      <div style="flex:1;min-width:0;">
        <div style="font-size:12px;font-weight:700;color:#0d1f3c;">${s.label}</div>
        <div id="cpst_${s.id}" style="font-size:10px;color:#9ca3af;margin-top:1px;">${s.note}</div>
      </div>
      <label style="background:#0d1f3c;color:#fff;font-size:11px;font-weight:700;padding:6px 12px;border-radius:7px;cursor:pointer;flex-shrink:0;white-space:nowrap;">
        Upload
        <input type="file" accept=".pdf,.jpg,.jpeg,.png" style="display:none;" onchange="cpFileAdded('${s.id}',this)">
      </label>
    </div>`).join('');
  const btn=document.getElementById('cpBuildBtn');
  if(btn){btn.textContent='Build Cancellation Pack';btn.style.opacity='0.45';btn.style.pointerEvents='none';}
  const st=document.getElementById('cpStatus');if(st)st.innerHTML='';
  cpCheckReady();
}
function cpFileAdded(slotId,input){
  const file=input.files[0];if(!file)return;
  _cpFiles[slotId]=file;
  const stEl=document.getElementById('cpst_'+slotId);
  const slotEl=document.getElementById('cpslot_'+slotId);
  if(stEl){stEl.textContent='✅ '+file.name;stEl.style.color='#16a34a';}
  if(slotEl)slotEl.style.borderColor='#86efac';
  cpCheckReady();
}
function cpCheckReady(){
  const allReady=_cpSlots.every(s=>_cpFiles[s.id]);
  const btn=document.getElementById('cpBuildBtn');
  if(btn){btn.style.opacity=allReady?'1':'0.45';btn.style.pointerEvents=allReady?'auto':'none';}
}
async function cpBuild(){
  const PL=window.PDFLib;
  const statusEl=document.getElementById('cpStatus');
  const btn=document.getElementById('cpBuildBtn');
  if(!PL||!PL.PDFDocument){
    if(statusEl)statusEl.innerHTML='<div style="color:#dc2626;font-size:12px;font-weight:700;">⚠️ PDF library not loaded — check your internet connection and try again.</div>';
    return;
  }
  btn.textContent='Building…';btn.style.opacity='0.7';btn.style.pointerEvents='none';
  if(statusEl)statusEl.innerHTML='';
  try{
    const merged=await PL.PDFDocument.create();
    for(const s of _cpSlots){
      const file=_cpFiles[s.id];if(!file)continue;
      const buf=await file.arrayBuffer();
      if(file.type==='application/pdf'||file.name.toLowerCase().endsWith('.pdf')){
        const src=await PL.PDFDocument.load(buf,{ignoreEncryption:true});
        const pages=await merged.copyPages(src,src.getPageIndices());
        pages.forEach(p=>merged.addPage(p));
      } else {
        const pg=merged.addPage([595,842]);
        let img;
        if(file.type==='image/png'||file.name.toLowerCase().endsWith('.png')){
          img=await merged.embedPng(buf);
        } else {
          img=await merged.embedJpg(buf);
        }
        const scaled=img.scaleToFit(555,802);
        pg.drawImage(img,{x:(595-scaled.width)/2,y:(842-scaled.height)/2,width:scaled.width,height:scaled.height});
      }
    }
    const bytes=await merged.save();
    const blob=new Blob([bytes],{type:'application/pdf'});
    const url=URL.createObjectURL(blob);
    const a=document.createElement('a');
    const name=(document.getElementById('cpFileName')?.value||'cancellation-pack').replace(/\.pdf$/i,'');
    a.href=url;a.download=name+'.pdf';a.click();
    setTimeout(()=>URL.revokeObjectURL(url),8000);
    if(statusEl)statusEl.innerHTML='<div style="color:#16a34a;font-size:12px;font-weight:700;margin-top:4px;">✅ Pack saved to your Downloads folder.</div>';
    btn.textContent='✅ Pack Downloaded';btn.style.opacity='1';btn.style.pointerEvents='auto';
  }catch(e){
    if(statusEl)statusEl.innerHTML='<div style="color:#dc2626;font-size:12px;">Error: '+e.message+'</div>';
    btn.textContent='Build Cancellation Pack';btn.style.opacity='1';btn.style.pointerEvents='auto';
  }
}
// ── END CANCELLATION PACK BUILDER ─────────────────────────────────────────────

// ── CLAIM PACK BUILDER ────────────────────────────────────────────────────────
const _claimSlots=[
  {id:'clID',      label:'Claimant ID (certified copy)',             icon:'🪪', note:'Certified copy of the person receiving the payout'},
  {id:'clDecID',   label:'Deceased ID (certified copy)',             icon:'🪪', note:'Certified copy of the life assured who passed'},
  {id:'clDeathDocs',label:'Death documents (from funeral parlour)',  icon:'📜', note:'Death cert, notice of death, BI-1663 etc. — provided by the funeral parlour'},
  {id:'clBank',    label:'Bank statement (not older than 3 months)', icon:'🏦', note:'Claimant\'s bank account — for payout'},
  {id:'clForm',    label:'Completed claim form',                     icon:'✍️', note:'Sanlam Sky form or the external company\'s claim form'},
];
const _claimReplacementSlots=[
  {id:'clPrevCover',  label:'Proof of previous cover (policy schedule)', icon:'📄', note:'Policy schedule of the replaced cover'},
  {id:'clPrevCancel', label:'Proof of cancellation of replaced cover',   icon:'🗑️', note:'Cancellation letter or confirmation'},
];
const _claimUnnatSlots=[
  {id:'clPoliceReport',  label:'Police report',              icon:'🚔', note:'Report from the investigating police station'},
  {id:'clSanlamForm',    label:'Sanlam police report form',  icon:'📋', note:'Sanlam\'s own form for unnatural death claims'},
];
let _claimFiles={};
let _claimIsReplacement=false;
let _claimIsUnnatural=false;

function _claimRenderExtraSlots(containerId,slots,borderColor){
  const container=document.getElementById(containerId);
  if(!container)return;
  container.innerHTML=slots.map(s=>`
    <div id="clslot_${s.id}" style="display:flex;align-items:center;gap:10px;background:#fff;border:1.5px solid ${borderColor};border-radius:10px;padding:10px 12px;transition:border-color .2s;">
      <span style="font-size:20px;flex-shrink:0;">${s.icon}</span>
      <div style="flex:1;min-width:0;">
        <div style="font-size:12px;font-weight:700;color:#0d1f3c;">${s.label}</div>
        <div id="clst_${s.id}" style="font-size:10px;color:#9ca3af;margin-top:1px;">${s.note}</div>
      </div>
      <label style="background:#0d1f3c;color:#fff;font-size:11px;font-weight:700;padding:6px 12px;border-radius:7px;cursor:pointer;flex-shrink:0;white-space:nowrap;">
        Upload
        <input type="file" accept=".pdf,.jpg,.jpeg,.png" style="display:none;" onchange="claimFileAdded('${s.id}',this)">
      </label>
    </div>`).join('');
}

function claimInit(){
  const container=document.getElementById('claimSlotList');
  if(!container)return;
  _claimFiles={};
  _claimIsReplacement=false;
  _claimIsUnnatural=false;
  ['claimRepToggle','claimUnnatToggle'].forEach(id=>{const el=document.getElementById(id);if(el)el.checked=false;});
  ['claimRepSlots','claimUnnatSlots'].forEach(id=>{const el=document.getElementById(id);if(el)el.style.display='none';});
  container.innerHTML=_claimSlots.map(s=>`
    <div id="clslot_${s.id}" style="display:flex;align-items:center;gap:10px;background:#f9fafb;border:1.5px solid #e5e7eb;border-radius:10px;padding:10px 12px;transition:border-color .2s;">
      <span style="font-size:20px;flex-shrink:0;">${s.icon}</span>
      <div style="flex:1;min-width:0;">
        <div style="font-size:12px;font-weight:700;color:#0d1f3c;">${s.label}</div>
        <div id="clst_${s.id}" style="font-size:10px;color:#9ca3af;margin-top:1px;">${s.note}</div>
      </div>
      <label style="background:#0d1f3c;color:#fff;font-size:11px;font-weight:700;padding:6px 12px;border-radius:7px;cursor:pointer;flex-shrink:0;white-space:nowrap;">
        Upload
        <input type="file" accept=".pdf,.jpg,.jpeg,.png" style="display:none;" onchange="claimFileAdded('${s.id}',this)">
      </label>
    </div>`).join('');
  _claimRenderExtraSlots('claimRepSlotList',_claimReplacementSlots,'#fed7aa');
  _claimRenderExtraSlots('claimUnnatSlotList',_claimUnnatSlots,'#fca5a5');
  const btn=document.getElementById('claimBuildBtn');
  if(btn){btn.textContent='Build Claim Pack';btn.style.opacity='0.45';btn.style.pointerEvents='none';}
  const st=document.getElementById('claimStatus');if(st)st.innerHTML='';
  claimCheckReady();
}
function claimToggleReplacement(cb){
  _claimIsReplacement=cb.checked;
  const repSlots=document.getElementById('claimRepSlots');
  if(repSlots)repSlots.style.display=_claimIsReplacement?'block':'none';
  if(!_claimIsReplacement){
    _claimReplacementSlots.forEach(s=>{
      delete _claimFiles[s.id];
      const stEl=document.getElementById('clst_'+s.id);
      const slotEl=document.getElementById('clslot_'+s.id);
      if(stEl){stEl.textContent=s.note;stEl.style.color='#9ca3af';}
      if(slotEl)slotEl.style.borderColor='#fed7aa';
    });
  }
  claimCheckReady();
}
function claimToggleUnnatural(cb){
  _claimIsUnnatural=cb.checked;
  const unnatSlots=document.getElementById('claimUnnatSlots');
  if(unnatSlots)unnatSlots.style.display=_claimIsUnnatural?'block':'none';
  if(!_claimIsUnnatural){
    _claimUnnatSlots.forEach(s=>{
      delete _claimFiles[s.id];
      const stEl=document.getElementById('clst_'+s.id);
      const slotEl=document.getElementById('clslot_'+s.id);
      if(stEl){stEl.textContent=s.note;stEl.style.color='#9ca3af';}
      if(slotEl)slotEl.style.borderColor='#fca5a5';
    });
  }
  claimCheckReady();
}
function claimFileAdded(slotId,input){
  const file=input.files[0];if(!file)return;
  _claimFiles[slotId]=file;
  const stEl=document.getElementById('clst_'+slotId);
  const slotEl=document.getElementById('clslot_'+slotId);
  if(stEl){stEl.textContent='✅ '+file.name;stEl.style.color='#16a34a';}
  if(slotEl)slotEl.style.borderColor='#86efac';
  claimCheckReady();
}
function claimCheckReady(){
  const baseReady=_claimSlots.every(s=>_claimFiles[s.id]);
  const repReady=!_claimIsReplacement||_claimReplacementSlots.every(s=>_claimFiles[s.id]);
  const unnatReady=!_claimIsUnnatural||_claimUnnatSlots.every(s=>_claimFiles[s.id]);
  const btn=document.getElementById('claimBuildBtn');
  if(btn){btn.style.opacity=(baseReady&&repReady&&unnatReady)?'1':'0.45';btn.style.pointerEvents=(baseReady&&repReady&&unnatReady)?'auto':'none';}
}
async function claimBuild(){
  const PL=window.PDFLib;
  const statusEl=document.getElementById('claimStatus');
  const btn=document.getElementById('claimBuildBtn');
  if(!PL||!PL.PDFDocument){
    if(statusEl)statusEl.innerHTML='<div style="color:#dc2626;font-size:12px;font-weight:700;">⚠️ PDF library not loaded — check your internet connection and try again.</div>';
    return;
  }
  btn.textContent='Building…';btn.style.opacity='0.7';btn.style.pointerEvents='none';
  if(statusEl)statusEl.innerHTML='';
  try{
    const merged=await PL.PDFDocument.create();
    const activeSlots=[..._claimSlots,...(_claimIsReplacement?_claimReplacementSlots:[]),...(_claimIsUnnatural?_claimUnnatSlots:[])];
    for(const s of activeSlots){
      const file=_claimFiles[s.id];if(!file)continue;
      const buf=await file.arrayBuffer();
      if(file.type==='application/pdf'||file.name.toLowerCase().endsWith('.pdf')){
        const src=await PL.PDFDocument.load(buf,{ignoreEncryption:true});
        const pages=await merged.copyPages(src,src.getPageIndices());
        pages.forEach(p=>merged.addPage(p));
      } else {
        const pg=merged.addPage([595,842]);
        let img;
        if(file.type==='image/png'||file.name.toLowerCase().endsWith('.png')){
          img=await merged.embedPng(buf);
        } else {
          img=await merged.embedJpg(buf);
        }
        const scaled=img.scaleToFit(555,802);
        pg.drawImage(img,{x:(595-scaled.width)/2,y:(842-scaled.height)/2,width:scaled.width,height:scaled.height});
      }
    }
    const bytes=await merged.save();
    const blob=new Blob([bytes],{type:'application/pdf'});
    const url=URL.createObjectURL(blob);
    const a=document.createElement('a');
    const name=(document.getElementById('claimFileName')?.value||'claim-pack').replace(/\.pdf$/i,'');
    a.href=url;a.download=name+'.pdf';a.click();
    setTimeout(()=>URL.revokeObjectURL(url),8000);
    if(statusEl)statusEl.innerHTML='<div style="color:#16a34a;font-size:12px;font-weight:700;margin-top:4px;">✅ Claim pack saved to your Downloads folder.</div>';
    btn.textContent='✅ Pack Downloaded';btn.style.opacity='1';btn.style.pointerEvents='auto';
  }catch(e){
    if(statusEl)statusEl.innerHTML='<div style="color:#dc2626;font-size:12px;">Error: '+e.message+'</div>';
    btn.textContent='Build Claim Pack';btn.style.opacity='1';btn.style.pointerEvents='auto';
  }
}
function claimCopyMsg(){
  const el=document.getElementById('claimMsg');
  const btn=document.getElementById('claimCopyBtn');
  if(!el||!btn)return;
  navigator.clipboard.writeText(el.innerText).then(()=>{
    btn.textContent='✅ Copied!';
    setTimeout(()=>{btn.textContent='📋 Copy message';},2200);
  }).catch(()=>{
    const ta=document.createElement('textarea');ta.value=el.innerText;document.body.appendChild(ta);ta.select();document.execCommand('copy');document.body.removeChild(ta);
    btn.textContent='✅ Copied!';setTimeout(()=>{btn.textContent='📋 Copy message';},2200);
  });
}
// ── END CLAIM PACK BUILDER ────────────────────────────────────────────────────

// ── UNLOCK PDF ────────────────────────────────────────────────────────────────
let _updfFiles=[];

function updfHandleFile(file){if(file)updfHandleFiles([file]);}
function updfHandleFiles(files){
  const pdfs=Array.from(files).filter(f=>f.type==='application/pdf'||f.name.toLowerCase().endsWith('.pdf'));
  if(!pdfs.length)return;
  pdfs.forEach(f=>{
    const id='updf_'+Date.now()+'_'+Math.random().toString(36).slice(2);
    _updfFiles.push({id,file:f,bytes:null,status:'pending'});
  });
  updfRenderList();
  document.getElementById('updfDropZone').style.display='none';
}
function updfHandleDrop(e){
  e.preventDefault();
  document.getElementById('updfDropZone').style.borderColor='#e5e7eb';
  const files=e.dataTransfer?.files;
  if(files&&files.length)updfHandleFiles(files);
}
function updfRenderList(){
  const list=document.getElementById('updfFileList');
  const addBtn=document.getElementById('updfAddMoreBtn');
  const unlockBtn=document.getElementById('updfUnlockAllBtn');
  if(!list)return;
  if(!_updfFiles.length){list.innerHTML='';if(addBtn)addBtn.style.display='none';if(unlockBtn)unlockBtn.style.display='none';return;}
  list.innerHTML=_updfFiles.map(entry=>{
    const name=entry.file.name;
    const size=(entry.file.size/1024).toFixed(1)+' KB';
    let statusHtml='';
    if(entry.status==='unlocking')statusHtml=`<div id="updfSt_${entry.id}" style="font-size:11px;color:#075985;padding:4px 0;">Unlocking…</div>`;
    else if(entry.status==='done')statusHtml=`<div style="font-size:11px;color:#16a34a;padding:4px 0;">✅ Unlocked — <button onclick="updfDownloadFile('${entry.id}')" style="background:none;border:none;color:#065f46;font-weight:700;cursor:pointer;font-size:11px;text-decoration:underline;">Download</button></div>`;
    else if(entry.status==='pwd_needed')statusHtml=`<div style="margin-top:6px;"><div style="font-size:11px;color:#92400e;margin-bottom:4px;">🔐 Enter password:</div><div style="display:flex;gap:6px;"><input id="updfPwd_${entry.id}" type="password" placeholder="PDF password…" style="flex:1;padding:7px 10px;font-size:12px;border:1px solid #e5e7eb;border-radius:8px;" onkeydown="if(event.key==='Enter')updfUnlockFile('${entry.id}')"/><button onclick="updfUnlockFile('${entry.id}')" style="background:#0d1f3c;color:#fff;border:none;border-radius:8px;padding:7px 14px;font-size:12px;font-weight:700;cursor:pointer;">Unlock</button></div><div id="updfSt_${entry.id}" style="font-size:11px;color:#dc2626;padding:4px 0;display:none;"></div></div>`;
    else if(entry.status==='error')statusHtml=`<div style="font-size:11px;color:#dc2626;padding:4px 0;">❌ ${entry.error||'Could not process'}</div>`;
    return`<div style="background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:10px 14px;margin-bottom:8px;">
      <div style="display:flex;align-items:center;gap:10px;">
        <span style="font-size:20px;flex-shrink:0;">📄</span>
        <div style="flex:1;min-width:0;"><div style="font-size:13px;font-weight:700;color:#0d1f3c;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${name}</div><div style="font-size:11px;color:#9ca3af;">${size}</div></div>
        ${entry.status==='pending'||entry.status==='pwd_needed'?`<button onclick="updfRemoveFile('${entry.id}')" style="background:none;border:none;color:#9ca3af;font-size:18px;cursor:pointer;flex-shrink:0;line-height:1;">✕</button>`:''}
      </div>
      ${statusHtml}
    </div>`;
  }).join('');
  const pending=_updfFiles.filter(e=>e.status==='pending'||e.status==='pwd_needed').length;
  if(unlockBtn){unlockBtn.style.display=pending?'block':'none';unlockBtn.textContent=`🔓 Unlock All (${pending} PDF${pending===1?'':'s'})`;}
  if(addBtn)addBtn.style.display='block';
  const rb=document.getElementById('updfResetBtn');if(rb)rb.style.display='block';
}
function updfRemoveFile(id){
  _updfFiles=_updfFiles.filter(e=>e.id!==id);
  if(!_updfFiles.length){document.getElementById('updfDropZone').style.display='';updfReset();}
  else updfRenderList();
}
async function updfUnlockFile(id){
  const entry=_updfFiles.find(e=>e.id===id);if(!entry)return;
  const pwd=(document.getElementById('updfPwd_'+id)?.value.trim())||'';
  entry.status='unlocking';updfRenderList();
  const stEl=document.getElementById('updfSt_'+id);
  try{
    await Promise.all([_loadPdfJs(),loadPdfLib()]);
    const {PDFDocument}=window.PDFLib;
    const bytes=await entry.file.arrayBuffer();
    let pdfJsDoc;
    try{pdfJsDoc=await window.pdfjsLib.getDocument({data:new Uint8Array(bytes),password:pwd}).promise;}
    catch(err){
      const isPassErr=err?.name==='PasswordException'||/PasswordException/i.test(err?.name||'');
      if(isPassErr){entry.status='pwd_needed';updfRenderList();const st=document.getElementById('updfSt_'+id);if(st){st.style.display='block';st.textContent=pwd?'❌ Incorrect password — try again.':'';}return;}
      throw err;
    }
    const total=pdfJsDoc.numPages;
    const newDoc=await PDFDocument.create();
    for(let i=1;i<=total;i++){
      if(stEl)stEl.textContent=`Rendering page ${i} of ${total}…`;
      const pg=await pdfJsDoc.getPage(i);
      const vp=pg.getViewport({scale:2});
      const canvas=document.createElement('canvas');canvas.width=vp.width;canvas.height=vp.height;
      await pg.render({canvasContext:canvas.getContext('2d'),viewport:vp}).promise;
      const dataUrl=canvas.toDataURL('image/jpeg',0.92);
      const b64=dataUrl.split(',')[1];
      const imgBytes=Uint8Array.from(atob(b64),c=>c.charCodeAt(0));
      const img=await newDoc.embedJpg(imgBytes);
      const w=vp.width/2,h=vp.height/2;
      const newPg=newDoc.addPage([w,h]);newPg.drawImage(img,{x:0,y:0,width:w,height:h});
    }
    entry.bytes=await newDoc.save();
    entry.status='done';updfRenderList();
  }catch(e){entry.status='error';entry.error=e.message||'Could not process this PDF.';updfRenderList();}
}
async function updfUnlockAll(){
  const pending=_updfFiles.filter(e=>e.status==='pending'||e.status==='pwd_needed');
  for(const entry of pending)await updfUnlockFile(entry.id);
}
function updfDownloadFile(id){
  const entry=_updfFiles.find(e=>e.id===id);if(!entry||!entry.bytes)return;
  const blob=new Blob([entry.bytes],{type:'application/pdf'});
  const url=URL.createObjectURL(blob);
  const a=document.createElement('a');a.href=url;a.download=entry.file.name.replace(/\.pdf$/i,'')+'-unlocked.pdf';a.click();
  setTimeout(()=>URL.revokeObjectURL(url),8000);
}
function updfDownload(){const done=_updfFiles.find(e=>e.status==='done');if(done)updfDownloadFile(done.id);}
function updfReset(){
  _updfFiles=[];
  document.getElementById('updfInput').value='';
  document.getElementById('updfFileList').innerHTML='';
  const dz=document.getElementById('updfDropZone');if(dz)dz.style.display='';
  const ab=document.getElementById('updfAddMoreBtn');if(ab)ab.style.display='none';
  const ub=document.getElementById('updfUnlockAllBtn');if(ub)ub.style.display='none';
  const rb=document.getElementById('updfResetBtn');if(rb)rb.style.display='none';
}
// ── END UNLOCK PDF ────────────────────────────────────────────────────────────

// ── REPLACEMENT CASE FORM ────────────────────────────────────────────────────
const RF_MEMBER_TYPES=['Main Life','Spouse','Child','Extended Family','Other'];
const RF_RELATIONSHIPS=['Self','Spouse / Partner','Child','Parent','Sibling','Grandparent','Grandchild','Parent-in-law','Sibling-in-law','Aunt / Uncle','Nephew / Niece','Extended — Verified Blood Relative'];
let _rfState={id:null,cases:[],advisorSig:null,clientSig:null,members:[],competitors:[]};

// Competitor multi-select
function rfToggleCompDropdown(){
  const dd=document.getElementById('rfCompDropdown');
  if(!dd)return;
  if(dd.style.display==='none'){rfRenderCompDropdown();dd.style.display='block';}
  else dd.style.display='none';
}
function rfRenderCompDropdown(){
  const dd=document.getElementById('rfCompDropdown');if(!dd)return;
  const sel=_rfState.competitors||[];
  dd.innerHTML=INSURER_LIST.map(c=>`
    <label style="display:flex;align-items:center;gap:8px;padding:7px 12px;cursor:pointer;background:${sel.includes(c)?'#f0fdf4':'#fff'};" onclick="rfToggleComp(this,event)">
      <input type="checkbox" ${sel.includes(c)?'checked':''} value="${c.replace(/"/g,'&quot;')}" style="accent-color:#059669;width:14px;height:14px;flex-shrink:0;pointer-events:none;"/>
      <span style="font-size:12px;color:#0d1f3c;">${c}</span>
    </label>`).join('');
}
function rfToggleComp(labelEl,e){
  e.preventDefault();e.stopPropagation();
  const cb=labelEl.querySelector('input[type=checkbox]');if(!cb)return;
  const c=cb.value;
  const sel=_rfState.competitors||[];
  const idx=sel.indexOf(c);
  if(idx>=0)sel.splice(idx,1);else sel.push(c);
  _rfState.competitors=sel;
  rfRenderCompDropdown();rfUpdateCompLabel();
}
function rfUpdateCompLabel(){
  const sel=_rfState.competitors||[];
  const lbl=document.getElementById('rfCompLabel');if(!lbl)return;
  if(!sel.length){lbl.textContent='Select companies…';lbl.style.color='#9ca3af';}
  else{lbl.textContent=sel.join(', ');lbl.style.color='#0d1f3c';}
}
document.addEventListener('click',function(e){
  const wrap=document.getElementById('rfCompWrap');
  if(wrap&&!wrap.contains(e.target)){const dd=document.getElementById('rfCompDropdown');if(dd)dd.style.display='none';}
});

async function rfInit(){
  document.getElementById('rfDate').value=new Date().toISOString().slice(0,10);
  document.getElementById('rfAdvSigName').textContent=currentUser?.name||'';
  if(!_rfState.members.length)_rfState.members=[{type:'Main Life',name:'',oldCover:'',newCover:'',relationship:'Self',insurable:'yes',notes:''}];
  rfUpdateCompLabel();
  renderReplMembers();
  // Defer sig pad setup — canvas needs one paint cycle to get real dimensions
  setTimeout(()=>{
    _rfInitSigPad('rfAdvisorSigCanvas');
    if(!_rfState.id){
      _rfClearSig('rfAdvisorSigCanvas');
      _rfState.advisorSig=null;
      _rfState.clientSig=null;
      rfUpdateClientSigUI();
    }
  },80);
  await rfLoadCases();
  renderReplCases();
}

function rfNewCase(){
  _rfState.id=null;_rfState.advisorSig=null;_rfState.clientSig=null;_rfState.competitors=[];
  _rfState.members=[{type:'Main Life',name:'',oldCover:'',newCover:'',relationship:'Self',insurable:'yes',notes:''}];
  ['rfClientName','rfClientId','rfClientPhone','rfCompetitorPolicy','rfBudget','rfPremium','rfBasicSalary','rfRoaText'].forEach(id=>{const e=document.getElementById(id);if(e)e.value='';});
  rfUpdateCompLabel();
  document.getElementById('rfDate').value=new Date().toISOString().slice(0,10);
  document.getElementById('rfIsPersal').checked=false;rfTogglePersal();
  ['rfChkPersal','rfChkAfford','rfChkMandate','rfChkWaiting','rfChkLoss','rfChkProof'].forEach(id=>{const e=document.getElementById(id);if(e)e.checked=false;});
  document.getElementById('rfStatus').textContent='New Case';
  renderReplMembers();
  setTimeout(()=>{_rfInitSigPad('rfAdvisorSigCanvas');_rfClearSig('rfAdvisorSigCanvas');},50);
  rfUpdateClientSigUI();
  document.getElementById('page-replform').scrollTop=0;
}

async function rfLoadCases(){
  if(!window.FB_READY)return;
  try{_rfState.cases=await window.FB.getReplCases(currentUser.code);}catch(e){
    // Index may not exist yet — surface the error in console but don't crash
    console.warn('rfLoadCases:',e?.message||e);
    _rfState.cases=[];
  }
}

function renderReplCases(){
  const el=document.getElementById('rfCasesList');if(!el)return;
  if(!_rfState.cases.length){el.innerHTML='<div style="font-size:11px;color:#9ca3af;padding:6px 0;">No saved cases yet — tap + New Case to start.</div>';return;}
  el.innerHTML=_rfState.cases.map(c=>`
    <div class="rf-case-item ${c.status==='signed'?'rf-case-signed':''}" onclick="rfLoadCase('${c.id}')">
      <div style="min-width:0;">
        <div style="font-size:12px;font-weight:700;color:#0d1f3c;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${c.clientName||'Unknown Client'}</div>
        <div style="font-size:10px;color:#6b7280;">${c.date||''} · ${(c.competitors&&c.competitors.length?c.competitors.join(', '):c.competitor)||'N/A'} · ${c.status==='signed'?'<span style="color:#059669;">✅ Signed</span>':'📝 Draft'}</div>
      </div>
      <button onclick="event.stopPropagation();rfDeleteCase('${c.id}')" style="background:none;border:none;color:#d1d5db;font-size:18px;cursor:pointer;flex-shrink:0;line-height:1;" title="Delete">✕</button>
    </div>`).join('');
}

async function rfLoadCase(id){
  const c=_rfState.cases.find(x=>x.id===id);if(!c)return;
  _rfState.id=id;_rfState.advisorSig=c.advisorSig||null;_rfState.clientSig=c.clientSig||null;
  _rfState.members=c.members&&c.members.length?c.members:[{type:'Main Life',name:'',oldCover:'',newCover:'',relationship:'Self',insurable:'yes',notes:''}];
  _rfState.competitors=c.competitors||(c.competitor?c.competitor.split(', ').filter(Boolean):[]);
  rfUpdateCompLabel();
  const sv=(eid,v)=>{const e=document.getElementById(eid);if(e)e.value=v||'';};
  sv('rfClientName',c.clientName);sv('rfClientId',c.clientId);sv('rfClientPhone',c.clientPhone);
  sv('rfCompetitorPolicy',c.competitorPolicy);sv('rfDate',c.date);
  sv('rfBudget',c.budgetDeclared);sv('rfPremium',c.finalPremium);sv('rfBasicSalary',c.basicSalary);sv('rfRoaText',c.roaText);
  const persalEl=document.getElementById('rfIsPersal');if(persalEl){persalEl.checked=!!c.isPersal;rfTogglePersal();}
  const chkMap={rfChkPersal:'persalChecked',rfChkAfford:'affordChecked',rfChkMandate:'mandateChecked',rfChkWaiting:'waitingChecked',rfChkLoss:'lossChecked',rfChkProof:'proofChecked'};
  Object.entries(chkMap).forEach(([eid,key])=>{const e=document.getElementById(eid);if(e)e.checked=!!c[key];});
  rfUpdateQlink();
  renderReplMembers();
  setTimeout(()=>{
    _rfInitSigPad('rfAdvisorSigCanvas');
    _rfClearSig('rfAdvisorSigCanvas');
    if(c.advisorSig){const img=new Image();img.onload=()=>{const cv=document.getElementById('rfAdvisorSigCanvas');if(cv)cv.getContext('2d').drawImage(img,0,0,cv.width/window.devicePixelRatio,cv.height/window.devicePixelRatio);};img.src=c.advisorSig;}
  },50);
  rfUpdateClientSigUI();
  document.getElementById('rfStatus').textContent=c.status==='signed'?'✅ Signed':'📝 Draft';
  document.getElementById('page-replform').scrollTop=0;
  showAlert('Loaded: '+(c.clientName||'case'),'success');
}

function rfTogglePersal(){
  const isP=document.getElementById('rfIsPersal')?.checked;
  const s=document.getElementById('rfPersalSection');if(s)s.style.display=isP?'block':'none';
  rfUpdateQlink();
}
function rfUpdateQlink(){
  const b=parseFloat(document.getElementById('rfBasicSalary')?.value||0);
  const el=document.getElementById('rfQlinkCap');if(el)el.textContent=b>0?'R'+( b*0.15).toFixed(2):'R0.00';
}

function renderReplMembers(){
  const el=document.getElementById('rfMembersList');if(!el)return;
  el.innerHTML=_rfState.members.map((m,i)=>`
    <div class="rf-member-card">
      <button onclick="rfRemoveMember(${i})" style="position:absolute;top:8px;right:8px;background:none;border:none;color:#d1d5db;font-size:18px;cursor:pointer;line-height:1;" title="Remove">✕</button>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:8px;padding-right:24px;">
        <div><label>MEMBER TYPE</label>
          <select id="rfMT_${i}">${RF_MEMBER_TYPES.map(t=>`<option value="${t}"${m.type===t?' selected':''}>${t}</option>`).join('')}</select>
        </div>
        <div><label>FULL NAME</label><input id="rfMN_${i}" type="text" value="${m.name||''}" placeholder="Name"/></div>
      </div>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:8px;">
        <div><label>OLD COVER (R)</label><input id="rfMO_${i}" type="number" value="${m.oldCover||''}" placeholder="0" inputmode="decimal"/></div>
        <div><label>NEW COVER (R)</label><input id="rfMNC_${i}" type="number" value="${m.newCover||''}" placeholder="0" inputmode="decimal"/></div>
      </div>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:8px;">
        <div><label>RELATIONSHIP</label>
          <select id="rfMR_${i}" style="width:100%;padding:8px 10px;font-size:13px;border:1px solid #e5e7eb;border-radius:8px;background:#f9f9f9;color:#0d1f3c;">
            ${RF_RELATIONSHIPS.map(r=>`<option value="${r}"${(m.relationship||'Self')===r?' selected':''}>${r}</option>`).join('')}
          </select>
        </div>
        <div><label>INSURABLE INTEREST</label>
          <select id="rfMI_${i}">
            <option value="yes"${m.insurable==='yes'?' selected':''}>✅ Yes — Verified</option>
            <option value="no"${m.insurable==='no'?' selected':''}>❌ No — Cannot add</option>
            <option value="removed"${m.insurable==='removed'?' selected':''}>🚫 Removed</option>
          </select>
        </div>
      </div>
      <div><label>VARIANCE / NOTES</label><input id="rfMV_${i}" type="text" value="${m.notes||''}" placeholder="e.g. Like-for-like waived; extra R10k = 6-month wait"/></div>
    </div>`).join('');
}

function rfAddMember(){
  _rfState.members.push({type:'Spouse',name:'',oldCover:'',newCover:'',relationship:'',insurable:'yes',notes:''});
  renderReplMembers();
}
function rfRemoveMember(i){
  if(_rfState.members.length<=1)return showToast('At least one member required.','error');
  _rfState.members.splice(i,1);renderReplMembers();
}
function rfReadMembers(){
  return _rfState.members.map((_,i)=>({
    type:document.getElementById(`rfMT_${i}`)?.value||'',
    name:document.getElementById(`rfMN_${i}`)?.value||'',
    oldCover:document.getElementById(`rfMO_${i}`)?.value||'',
    newCover:document.getElementById(`rfMNC_${i}`)?.value||'',
    relationship:document.getElementById(`rfMR_${i}`)?.value||'',
    insurable:document.getElementById(`rfMI_${i}`)?.value||'yes',
    notes:document.getElementById(`rfMV_${i}`)?.value||''
  }));
}
function rfReadForm(){
  const gv=id=>document.getElementById(id)?.value?.trim()||'';
  const gc=id=>!!document.getElementById(id)?.checked;
  return{
    clientName:gv('rfClientName'),clientId:gv('rfClientId'),clientPhone:gv('rfClientPhone'),
    competitors:_rfState.competitors||[],competitor:(_rfState.competitors||[]).join(', '),
    competitorPolicy:gv('rfCompetitorPolicy'),
    date:gv('rfDate')||new Date().toISOString().slice(0,10),
    budgetDeclared:gv('rfBudget'),finalPremium:gv('rfPremium'),
    isPersal:gc('rfIsPersal'),basicSalary:gv('rfBasicSalary'),
    qlinkCap:document.getElementById('rfQlinkCap')?.textContent||'',
    persalChecked:gc('rfChkPersal'),affordChecked:gc('rfChkAfford'),mandateChecked:gc('rfChkMandate'),
    waitingChecked:gc('rfChkWaiting'),lossChecked:gc('rfChkLoss'),proofChecked:gc('rfChkProof'),
    members:rfReadMembers(),roaText:gv('rfRoaText'),
    advisorCode:currentUser?.code||'',advisorName:currentUser?.name||''
  };
}

function rfGenerateROA(){
  const d=rfReadForm();
  if(!d.clientName)return showToast('Please enter client name first.','error');
  const members=d.members;
  const removed=members.filter(m=>m.insurable==='removed'||parseFloat(m.newCover||0)===0);
  const increased=members.filter(m=>m.insurable!=='removed'&&parseFloat(m.newCover||0)>parseFloat(m.oldCover||0));
  const fmt=v=>v?'R'+parseFloat(v).toLocaleString('en-ZA'):'[Amount]';
  let t=`REPLACEMENT ADVICE, JUSTIFICATION & AFFORDABILITY ANALYSIS\n`;
  t+=`Client: ${d.clientName} | ID: ${d.clientId||'N/A'} | Date: ${d.date}\n`;
  t+=`Competitor: ${d.competitor||'N/A'} | Policy No: ${d.competitorPolicy||'N/A'}\n\n`;
  t+=`A straight, identical like-for-like replacement was presented to the client to preserve existing cover terms and ensure a 100% waiver of waiting periods. However, using the Client Needs & Affordability Declaration Form (attached), the client explicitly instructed a structural change to their risk profile.\n\n`;
  t+=`1. AFFORDABILITY & BUDGET RECONCILIATION:\n`;
  t+=`The client declared a comfortable monthly budget of ${fmt(d.budgetDeclared)}. `;
  const b=parseFloat(d.budgetDeclared||0),p=parseFloat(d.finalPremium||0);
  if(p>0&&b>0&&p<=b)t+=`The final proposed premium of ${fmt(d.finalPremium)} sits safely within the client's declared affordability threshold, mitigating the risk of early policy lapse.\n\n`;
  else if(p>0&&b>0&&p>b)t+=`The final premium of ${fmt(d.finalPremium)} exceeds the client's initial target of ${fmt(d.budgetDeclared)}. The client was counselled on this gap but explicitly chose to override their initial limit to ensure essential family members were not left uninsured. The client confirmed the additional premium is sustainable.\n\n`;
  else t+=`The final proposed premium of ${fmt(d.finalPremium)} [sits within / exceeds] the client's declared affordability threshold.\n\n`;
  if(d.isPersal)t+=`For Persal Case: The proposed premium of ${fmt(d.finalPremium)} complies fully with the statutory 15% QLink ceiling (${d.qlinkCap}), calculated strictly against the client's Basic Salary of ${fmt(d.basicSalary)} (excluding allowances) per their current payslip. The premium has been aligned with the client's true household cash flow limits rather than maximising the system's legal ceiling blindly.\n\n`;
  t+=`2. RATIONALE FOR RESTRUCTURING & INSURABLE INTEREST:\n`;
  if(removed.length>0)t+=`The client requested removal of ${removed.map(m=>m.name||m.type).join(', ')} who now hold independent insurance. `;
  if(increased.length>0)t+=`The client requested increased cover for ${increased.map(m=>`${m.name||m.type} (${fmt(m.oldCover)} → ${fmt(m.newCover)})`).join(', ')}. `;
  t+=`Insurable interest has been verified for all customised listings. It is therefore in the client's financial interest to replace the policy under this new structure.\n\n`;
  t+=`3. EXPLICIT MATERIAL DISADVANTAGES DISCLOSED:\n`;
  increased.forEach(m=>{const diff=parseFloat(m.newCover||0)-parseFloat(m.oldCover||0);t+=`• Waiting Periods: The existing active base cover of ${fmt(m.oldCover)} on ${m.name||m.type} is transferred with waiting periods waived. The newly requested increase of R${diff.toLocaleString('en-ZA')} is subject to a new 6-month waiting period for natural death.\n`;});
  removed.forEach(m=>{t+=`• Forfeiture of Active Cover: Removing ${m.name||m.type} results in the immediate termination of their active risk cover. The client acknowledges forfeiting a benefit that has already served its waiting period.\n`;});
  t+=`• Proof of Cancellation: If a natural death claim arises within the first 6 months, the underwriter requires written proof of the previous policy's cancellation.\n\n`;
  t+=`4. CLIENT CONFIRMATION:\nThe client has validated these instructions by signing the Client Needs & Affordability Declaration Form, confirming that the suitability of the new layout and affordability profile outweighs the benefits forfeited from the replaced active policy.\n\nIndependent Contractor: ${d.advisorName} | Date: ${d.date}`;
  const el=document.getElementById('rfRoaText');if(el)el.value=t;
}

// Signature pad
function _rfInitSigPad(canvasId){
  const cv=document.getElementById(canvasId);if(!cv)return;
  const dpr=window.devicePixelRatio||1;
  const rect=cv.getBoundingClientRect();
  const w=Math.round(rect.width||300),h=Math.round(rect.height||120);
  cv.width=w*dpr;cv.height=h*dpr;
  const ctx=cv.getContext('2d');ctx.scale(dpr,dpr);
  ctx.strokeStyle='#1d4ed8';ctx.lineWidth=2.5;ctx.lineCap='round';ctx.lineJoin='round';
  let drawing=false,lx=0,ly=0;
  function pos(e){const r=cv.getBoundingClientRect();const t=e.touches?e.touches[0]:e;return[(t.clientX-r.left),(t.clientY-r.top)];}
  function start(e){e.preventDefault();drawing=true;[lx,ly]=pos(e);}
  function draw(e){e.preventDefault();if(!drawing)return;const[x,y]=pos(e);ctx.beginPath();ctx.moveTo(lx,ly);ctx.lineTo(x,y);ctx.stroke();[lx,ly]=[x,y];}
  function stop(){drawing=false;}
  cv.onmousedown=start;cv.onmousemove=draw;cv.onmouseup=stop;cv.onmouseleave=stop;
  cv.addEventListener('touchstart',start,{passive:false});
  cv.addEventListener('touchmove',draw,{passive:false});
  cv.addEventListener('touchend',stop);
}
function _rfClearSig(canvasId){const cv=document.getElementById(canvasId);if(cv)cv.getContext('2d').clearRect(0,0,cv.width,cv.height);}
function _rfSigEmpty(canvasId){const cv=document.getElementById(canvasId);if(!cv)return true;return !cv.getContext('2d').getImageData(0,0,cv.width,cv.height).data.some(v=>v>0);}
function rfClearAdvisorSig(){_rfClearSig('rfAdvisorSigCanvas');_rfState.advisorSig=null;}
function rfClearClientSig(){_rfState.clientSig=null;rfUpdateClientSigUI();}
function rfUpdateClientSigUI(){
  const img=document.getElementById('rfClientSigImg');
  const prev=document.getElementById('rfClientSigPreview');
  const clrBtn=document.getElementById('rfClearClientSigBtn');
  const hasSig=!!_rfState.clientSig;
  if(img){img.src=hasSig?_rfState.clientSig:'';img.style.display=hasSig?'block':'none';}
  if(prev)prev.style.display=hasSig?'block':'none';
  if(clrBtn)clrBtn.style.display=hasSig?'block':'none';
}

// Client signing overlay
function rfClientSign(){
  const ov=document.getElementById('rfClientSigOverlay');if(!ov)return;
  ov.style.display='flex';
  setTimeout(()=>{_rfClearSig('rfClientSigCanvas');_rfInitSigPad('rfClientSigCanvas');},100);
}
function rfClientSignCancel(){const ov=document.getElementById('rfClientSigOverlay');if(ov)ov.style.display='none';}
function rfClientSignDone(){
  if(_rfSigEmpty('rfClientSigCanvas'))return showToast('Please sign before confirming.','error');
  _rfState.clientSig=document.getElementById('rfClientSigCanvas').toDataURL('image/png');
  document.getElementById('rfClientSigOverlay').style.display='none';
  rfUpdateClientSigUI();
  showToast('Client signature captured ✓','success');
}

// Save
async function rfSave(){
  const d=rfReadForm();
  if(!d.clientName){
    const f=document.getElementById('rfClientName');
    if(f){f.style.border='2px solid #dc2626';f.focus();setTimeout(()=>f.style.border='',2000);}
    return showToast('Please enter client name first.','error');
  }
  const saveBtn=document.querySelector('[onclick="rfSave()"]');
  if(saveBtn){saveBtn.textContent='💾 Saving…';saveBtn.disabled=true;}
  const cv=document.getElementById('rfAdvisorSigCanvas');
  if(cv&&!_rfSigEmpty('rfAdvisorSigCanvas'))_rfState.advisorSig=cv.toDataURL('image/png');
  const id=_rfState.id||(Date.now()+'_'+Math.random().toString(36).slice(2));
  _rfState.id=id;
  const payload={...d,id,advisorSig:_rfState.advisorSig||null,clientSig:_rfState.clientSig||null,status:(_rfState.advisorSig&&_rfState.clientSig)?'signed':'draft'};
  try{
    if(!window.FB_READY)throw new Error('Not connected to Firebase — please try again.');
    // Strip base64 signatures from Firebase payload — they can exceed 1MB doc limit
    const {advisorSig:_as,clientSig:_cs,...fbPayload}=payload;
    await window.FB.saveReplCase(id,fbPayload);
    await rfLoadCases();renderReplCases();
    document.getElementById('rfStatus').textContent=payload.status==='signed'?'✅ Signed':'💾 Saved';
    showToast('Case saved ✓','success');
  }catch(e){
    console.error('rfSave:',e);
    showToast('Save failed: '+(e.message||e),'error');
  }finally{
    if(saveBtn){saveBtn.textContent='💾 Save Draft';saveBtn.disabled=false;}
  }
}

async function rfDeleteCase(id){
  if(!confirm('Delete this case?'))return;
  try{
    if(!window.FB_READY)throw new Error('Not connected');
    await window.FB.deleteReplCase(id);
    _rfState.cases=_rfState.cases.filter(c=>c.id!==id);
    if(_rfState.id===id)rfNewCase();
    renderReplCases();showToast('Case deleted.','info');
  }catch(e){showToast('Delete failed: '+(e.message||e),'error');}
}

// PDF export via print window
function rfExportPDF(){
  const d=rfReadForm();
  if(!d.clientName)return showToast('Please enter client name first.','error');
  logActivity('CASE_PDF','Case form: '+d.clientName);
  const cv=document.getElementById('rfAdvisorSigCanvas');
  if(cv&&!_rfSigEmpty('rfAdvisorSigCanvas'))_rfState.advisorSig=cv.toDataURL('image/png');
  d.advisorSig=_rfState.advisorSig;d.clientSig=_rfState.clientSig;
  const w=window.open('','_blank','width=900,height=700');
  if(!w)return showToast('Please allow pop-ups to export PDF.','error');
  w.document.write(_rfBuildPrintHTML(d));
  w.document.close();w.focus();
  setTimeout(()=>w.print(),700);
}

function _rfBuildPrintHTML(d){
  const chk=v=>v?'<span style="color:#059669;font-weight:bold;">☑</span>':'<span style="color:#9ca3af;">☐</span>';
  const fmt=v=>v?'R'+parseFloat(v).toLocaleString('en-ZA'):'—';
  const ins=v=>v==='removed'?'🚫 Removed':v==='no'?'❌ No — Cannot add':'✅ Yes — Verified';
  const members=d.members||[];
  return`<!DOCTYPE html><html><head><meta charset="UTF-8"/>
<title>Replacement Case — ${d.clientName}</title>
<style>
*{box-sizing:border-box;margin:0;padding:0;}
body{font-family:Arial,Helvetica,sans-serif;font-size:11px;color:#111;padding:16px;line-height:1.55;}
.hdr{background:#0d1f3c;color:#fff;padding:12px 16px;border-radius:6px;margin-bottom:14px;}
.hdr .lbl{font-size:9px;color:#f5d98b;font-weight:bold;text-transform:uppercase;letter-spacing:1px;}
.hdr .ttl{font-size:15px;font-weight:bold;margin:3px 0;}
.hdr .meta{font-size:9px;color:rgba(255,255,255,.7);margin-top:3px;}
.sec{border:1px solid #e5e7eb;border-radius:6px;margin-bottom:12px;overflow:hidden;}
.sec-hd{font-size:10px;font-weight:bold;color:#fff;padding:6px 10px;}
.sec-body{padding:10px;}
table{width:100%;border-collapse:collapse;font-size:10px;}
th{background:#1d4ed8;color:#fff;padding:5px 7px;text-align:left;}
td{padding:5px 7px;border:1px solid #e5e7eb;vertical-align:top;}
tr:nth-child(even) td{background:#f9fafb;}
.chk-row{display:flex;gap:7px;padding:5px 0;border-bottom:1px solid #f3f4f6;align-items:flex-start;}
.chk-row:last-child{border-bottom:none;}
.roa{white-space:pre-wrap;font-size:10px;line-height:1.7;background:#f9fafb;border:1px solid #e5e7eb;border-radius:4px;padding:10px;font-family:Arial,sans-serif;}
.sig-box{display:inline-block;width:220px;margin-right:20px;vertical-align:top;text-align:center;}
.sig-img{width:220px;height:70px;object-fit:contain;border:1px solid #e5e7eb;border-radius:4px;display:block;}
.sig-empty{width:220px;height:70px;border:1px solid #e5e7eb;border-radius:4px;display:flex;align-items:center;justify-content:center;color:#9ca3af;font-size:10px;}
.sig-lbl{font-size:9px;color:#374151;border-top:1.5px solid #374151;margin-top:5px;padding-top:3px;}
.warn{background:#fef9ec;border:1px solid #f5d98b;border-radius:4px;padding:6px 10px;font-size:10px;color:#92400e;margin:8px 0;}
@media print{body{padding:0;}@page{margin:12mm;size:A4;}}
</style></head><body>
<div class="hdr">
  <div class="lbl">📝 Team Buffalos — Smart Replacement</div>
  <div class="ttl">Client Needs &amp; Affordability Declaration Form</div>
  <div class="meta">Client: <b>${d.clientName}</b> &nbsp;|&nbsp; ID: ${d.clientId||'N/A'} &nbsp;|&nbsp; Phone: ${d.clientPhone||'N/A'} &nbsp;|&nbsp; Date: ${d.date}</div>
  <div class="meta">Competitor(s): ${d.competitor||'N/A'} &nbsp;|&nbsp; Policy No: ${d.competitorPolicy||'N/A'} &nbsp;|&nbsp; Independent Contractor: ${d.advisorName}</div>
</div>

<div class="sec"><div class="sec-hd" style="background:#1d4ed8;">Part A — Affordability, Budget &amp; Persal Cap Declaration</div><div class="sec-body">
<table style="margin-bottom:10px;">
  <tr><th>Item</th><th>Value</th></tr>
  <tr><td>Declared Monthly Budget</td><td><b>${fmt(d.budgetDeclared)}</b></td></tr>
  <tr><td>Final Proposed Monthly Premium</td><td><b>${fmt(d.finalPremium)}</b></td></tr>
  ${d.isPersal?`<tr><td>Basic Salary (excl. allowances)</td><td>${fmt(d.basicSalary)}</td></tr><tr><td>15% QLink Cap</td><td>${d.qlinkCap}</td></tr>`:''}
</table>
<div class="chk-row">${chk(d.isPersal&&d.persalChecked)} <span><b>Persal Cap Compliance:</b> ${d.isPersal?'I confirm the proposed premium falls safely below the statutory 15% QLink restriction based strictly on my Basic Salary.':'<em>Not applicable — not a Persal client.</em>'}</span></div>
<div class="chk-row">${chk(d.affordChecked)} <span><b>Affordability Confirmation:</b> I have reviewed my monthly income and expenses and can comfortably afford this premium on an ongoing, long-term basis without financial distress.</span></div>
<div class="chk-row">${chk(d.mandateChecked)} <span><b>Replacement Mandate:</b> My new policy provides immediate cover upon approval. I authorise the FSP to handle cancellation of my previous policy/policies.</span></div>
</div></div>

<div class="sec"><div class="sec-hd" style="background:#065f46;">Part B — Policy Reconciliation &amp; Insurable Interest Table</div><div class="sec-body">
<table>
  <tr><th>Member / Name</th><th>Old Cover</th><th>New Cover</th><th>Relationship</th><th>Insurable Interest</th><th>Variance &amp; Notes</th></tr>
  ${members.map(m=>`<tr><td><b>${m.type}</b>${m.name?'<br><span style="font-weight:normal;">'+m.name+'</span>':''}</td><td>${fmt(m.oldCover)}</td><td>${parseFloat(m.newCover||0)===0&&m.insurable==='removed'?'<span style="color:#dc2626;">Removed</span>':fmt(m.newCover)}</td><td>${m.relationship||'—'}</td><td>${ins(m.insurable)}</td><td style="font-size:9px;">${m.notes||'—'}</td></tr>`).join('')}
</table>
<div class="warn">⚠️ <b>Insurable Interest Mandate:</b> Sharing a Clan Name (Isiduko / Sereto) does NOT constitute insurable interest. Only direct blood relatives or legal dependants may be listed.</div>
</div></div>

<div class="sec"><div class="sec-hd" style="background:#7c3aed;">Part C — Mandatory FAIS Statutory Disclosures</div><div class="sec-body">
<div class="chk-row">${chk(d.waitingChecked)} <span><b>Waiting Period Differentiation:</b> Any increase in cover amounts above current policy limits is NOT waived and is subject to standard statutory waiting periods for natural death.</span></div>
<div class="chk-row">${chk(d.lossChecked)} <span><b>Irrevocable Loss of Benefits:</b> Removing or reducing previously covered lives voluntarily forfeits their existing active cover. They must serve full waiting periods as new entrants if re-added.</span></div>
<div class="chk-row">${chk(d.proofChecked)} <span><b>6-Month Claim Warning:</b> If a natural death claim occurs within the first 6 months of this policy, written proof that the previous policy was successfully cancelled must be provided.</span></div>
</div></div>

${d.roaText?`<div class="sec"><div class="sec-hd" style="background:#92400e;">Record of Advice (ROA) — Compliance Boilerplate</div><div class="sec-body"><div class="roa">${d.roaText.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')}</div></div></div>`:''}

<div class="sec"><div class="sec-hd" style="background:#374151;">📋 File Checklist</div><div class="sec-body">
<div class="chk-row">☐ <span>Copy of the original insurer's <b>active policy schedule</b>.</span></div>
<div class="chk-row">☐ <span>Signed &amp; ticked <b>Client Needs &amp; Affordability Declaration Form</b> (this document).</span></div>
<div class="chk-row">☐ <span>Fully completed <b>ROA</b> containing the mandatory boilerplate replacement text.</span></div>
<div class="chk-row">☐ <span>The <b>new policy application</b> captured on the system matching the declaration sheet perfectly.</span></div>
</div></div>

<div class="sec"><div class="sec-hd" style="background:#0d1f3c;">Signatures</div><div class="sec-body" style="padding-top:12px;">
<div class="sig-box">
  ${d.advisorSig?`<img src="${d.advisorSig}" class="sig-img" alt="Advisor Signature"/>`:'<div class="sig-empty">Not signed</div>'}
  <div class="sig-lbl">Independent Contractor: <b>${d.advisorName}</b></div>
</div>
<div class="sig-box">
  ${d.clientSig?`<img src="${d.clientSig}" class="sig-img" alt="Client Signature"/>`:'<div class="sig-empty">Client not signed</div>'}
  <div class="sig-lbl">Client: <b>${d.clientName}</b></div>
</div>
<div style="margin-top:14px;font-size:9px;color:#9ca3af;border-top:1px solid #f3f4f6;padding-top:8px;">Generated by <b>Team Buffalos</b> Hub · ${new Date().toLocaleString('en-ZA')} · This document is the official signed declaration for this replacement case and must be uploaded to iManagePro under Supporting Documents.</div>
</div></div>
</body></html>`;
}
// ── END REPLACEMENT CASE FORM ─────────────────────────────────────────────────

// ── REPLACEMENT PRESENTATION ──────────────────────────────────────────────────
const REPL_SLIDES = [
  {
    bg:'#064e3b', accent:'#6ee7b7',
    subtitle:'Step 1 of 8 — Open the Conversation',
    title:'Build the Relationship First',
    say:'Good day. My name is [Your Name] — I\'m an independent contractor with Team Buffalos.\n\nThank you for your time today. I\'m not here to sell you something new. I\'m here to make sure your family is properly protected with what you already have — and only look at alternatives if it genuinely makes sense for you.\n\nCan I take about 10 minutes to go through your current cover with you?'
  },
  {
    bg:'#1e3a5f', accent:'#93c5fd',
    subtitle:'Step 2 of 8 — Understand What They Have',
    title:'Tell Me About Your Current Policy',
    say:'Do you have your policy schedule or document here? Let me ask you three questions:\n\n• Who is currently covered on this policy?\n• What is the payout amount for each person?\n• Do you know which company it\'s with and how long you\'ve had it?\n\nMost clients I sit with can\'t answer all three — and that\'s not their fault. That\'s exactly what I\'m here to help with.'
  },
  {
    bg:'#4a1942', accent:'#f0abfc',
    subtitle:'Step 3 of 8 — Make the Problems Visible',
    title:'Here\'s What I Find Most Often',
    bullets:[
      '"Your main member is covered for R10,000 — but a funeral today costs R30,000 to R50,000."',
      '"A child turned 21 and aged off the policy automatically. You had no idea — they have zero cover right now."',
      '"Someone was added who doesn\'t qualify under insurable interest rules. Their claim could be rejected."',
      '"Your premium has gone up three times but the cover amount has never been reviewed."'
    ]
  },
  {
    bg:'#7c2d12', accent:'#fdba74',
    subtitle:'Step 4 of 8 — Anchor to Reality',
    title:'What a Funeral Actually Costs Today',
    say:'Let me give you some numbers so we\'re talking about the same thing.\n\nA traditional burial — tent, chairs, catering, hearse, tombstone, post-funeral meal — easily runs R30,000 to R50,000. In many communities, the expectation is R80,000 or more.\n\nCremation is cheaper — typically R8,000 to R15,000 — but that\'s not always the family\'s choice.\n\nLook at your current cover amount. Is that enough for the funeral your family would expect?'
  },
  {
    bg:'#065f46', accent:'#a7f3d0',
    subtitle:'Step 5 of 8 — Present the Solution',
    title:'Here\'s What We Can Do for You',
    say:'Through Sanlam Sky, we can build one plan that covers you, your spouse, your children, and your parents — all in a single policy.\n\nThe payout comes within 48 hours of a valid claim. There are no medical exams — just a straightforward application. And your premium is fixed — no surprise increases down the line.\n\nI build the plan around your budget. Not the other way around.'
  },
  {
    bg:'#1e3a5f', accent:'#93c5fd',
    subtitle:'Step 6 of 8 — Be Upfront About the Waiting Period',
    title:'One Thing I Need to Be Honest About',
    say:'Every insurer in South Africa has a 6-month waiting period for natural death on a new policy. Not just us — every single one. That\'s regulated by law.\n\nSo here is what we do: we never cancel your old policy until your new one is confirmed active and your first debit order has cleared. You run both for a short overlap period.\n\nI will tell you exactly when it is safe to cancel the old one. Your family will never be without cover. That is my commitment to you.'
  },
  {
    bg:'#3b0764', accent:'#c4b5fd',
    subtitle:'Step 7 of 8 — Establish Real Affordability',
    title:'What\'s Comfortable for You Each Month?',
    say:'I need you to answer this honestly — not what you\'re currently paying, but what is the maximum you would be comfortable paying for this cover on an ongoing basis?\n\nI\'m going to go through your bank statements with you so we can confirm the number is real. A policy that lapses because it\'s unaffordable protects nobody.\n\nI would rather put you on less cover that stays on the books than more cover that falls away in six months.'
  },
  {
    bg:'#14532d', accent:'#86efac',
    subtitle:'Step 8 of 8 — Close the Conversation',
    title:'So, Where Do We Go From Here?',
    say:'Based on what we\'ve looked at today, I can put together cover that actually makes sense for your family.\n\nIf you\'re happy to move forward, we complete the application together right now — about 20 minutes. I handle everything: the paperwork, notifying your current insurer, and setting up your debit order correctly.\n\nAll I need from you is your ID, your current policy schedule, and your latest bank statement.\n\nAny questions before we start?'
  }
];

let _replSlideIdx=0;
function replPresentationInit(){
  _replSlideIdx=0;
  replRenderSlide();
}
function replRenderSlide(){
  const slides=REPL_SLIDES;
  const s=slides[_replSlideIdx];
  const track=document.getElementById('replSlideTrack');
  if(!track)return;
  const bulletsHtml=s.bullets?`<ul style="margin:0;padding:0;list-style:none;display:flex;flex-direction:column;gap:8px;">${s.bullets.map(b=>`<li style="font-size:12.5px;color:rgba(255,255,255,0.9);line-height:1.6;padding:9px 12px;background:rgba(255,255,255,0.08);border-radius:8px;border-left:3px solid ${s.accent};">${b}</li>`).join('')}</ul>`:'';
  const bodyHtml=s.body?`<div style="font-size:13px;color:rgba(255,255,255,0.85);line-height:1.8;white-space:pre-wrap;">${s.body}</div>`:'';
  const sayHtml=s.say?`<div><div style="font-size:9px;font-weight:700;color:${s.accent};text-transform:uppercase;letter-spacing:1px;margin-bottom:6px;">🗣 Say this</div><div style="background:rgba(255,255,255,0.1);border-left:4px solid ${s.accent};border-radius:0 10px 10px 0;padding:14px 16px;font-size:13px;color:#fff;line-height:1.9;white-space:pre-wrap;">${s.say}</div></div>`:'';
  track.innerHTML=`<div style="background:${s.bg};padding:28px 22px;min-height:320px;display:flex;flex-direction:column;justify-content:space-between;">
    <div>
      <div style="font-size:10px;font-weight:700;color:${s.accent};text-transform:uppercase;letter-spacing:1.2px;margin-bottom:6px;">${s.subtitle}</div>
      <div style="font-size:20px;font-weight:700;color:#fff;margin-bottom:16px;line-height:1.3;">${s.title}</div>
      ${bodyHtml}${bulletsHtml}${sayHtml}
    </div>
    <div style="margin-top:18px;font-size:10px;color:rgba(255,255,255,0.35);text-align:right;">Slide ${_replSlideIdx+1} / ${slides.length}</div>
  </div>`;
  // dots
  const dots=document.getElementById('replSlideDots');
  if(dots)dots.innerHTML=slides.map((_,i)=>`<div onclick="replGoSlide(${i})" style="width:${i===_replSlideIdx?'18px':'7px'};height:7px;border-radius:10px;background:${i===_replSlideIdx?'#6d28d9':'#d1d5db'};cursor:pointer;transition:all .2s;"></div>`).join('');
  const counter=document.getElementById('replSlideCounter');
  if(counter)counter.textContent=(_replSlideIdx+1)+' of '+slides.length;
}
function replSlide(dir){_replSlideIdx=Math.max(0,Math.min(REPL_SLIDES.length-1,_replSlideIdx+dir));replRenderSlide();}
function replGoSlide(i){_replSlideIdx=i;replRenderSlide();}
// ── END REPLACEMENT PRESENTATION ──────────────────────────────────────────────

// ── MEETING AGENDA BUILDER ────────────────────────────────────────────────────
function _agendaKey(){
  const d=new Date();return'tl_agenda_notes_'+d.getFullYear()+String(d.getMonth()+1).padStart(2,'0');
}
function agendaGetNotes(){try{return JSON.parse(localStorage.getItem(_agendaKey())||'[]');}catch(e){return[];}}
function agendaSaveNotes(notes){try{localStorage.setItem(_agendaKey(),JSON.stringify(notes));}catch(e){}}
function agendaRenderNotes(){
  const notes=agendaGetNotes();
  const list=document.getElementById('agendaNotesList');
  if(!list)return;
  if(!notes.length){list.innerHTML='<div style="font-size:11px;color:#9ca3af;font-style:italic;">No notes yet — tap quick-add chips above or type a custom note.</div>';return;}
  list.innerHTML=notes.map((n,i)=>`<div style="display:flex;align-items:flex-start;gap:8px;background:#f9fafb;border:1px solid #e5e7eb;border-radius:8px;padding:8px 10px;">
    <span style="font-size:11px;color:#6b7280;margin-top:1px;flex-shrink:0;">${i+1}.</span>
    <span style="flex:1;font-size:12px;color:#0d1f3c;line-height:1.5;">${n}</span>
    <button onclick="agendaDeleteNote(${i})" style="background:none;border:none;color:#9ca3af;cursor:pointer;font-size:13px;flex-shrink:0;padding:0;">&#x2715;</button>
  </div>`).join('');
}
function agendaToggleCat(id){
  const el=document.getElementById(id);
  if(!el)return;
  const open=el.style.display==='flex';
  el.style.display=open?'none':'flex';
  const arrow=document.getElementById(id+'Arrow');
  if(arrow)arrow.textContent=open?'▾':'▴';
}
function agendaQuickAdd(text){
  const notes=agendaGetNotes();
  if(notes.includes(text)){showAlert('Already added','info');return;}
  notes.push(text);agendaSaveNotes(notes);agendaRenderNotes();
  showAlert('Added','success');
}
function agendaAddNote(){
  const inp=document.getElementById('agendaNoteInput');
  if(!inp||!inp.value.trim())return;
  const notes=agendaGetNotes();notes.push(inp.value.trim());agendaSaveNotes(notes);
  inp.value='';agendaRenderNotes();
}
function agendaDeleteNote(i){const notes=agendaGetNotes();notes.splice(i,1);agendaSaveNotes(notes);agendaRenderNotes();}
function agendaClearNotes(){if(confirm('Clear all notes for this month?')){agendaSaveNotes([]);agendaRenderNotes();}}
async function agendaGenerate(){
  const notes=agendaGetNotes();
  if(!notes.length)return showAlert('Add at least one note before generating.','error');
  const meetingType=document.getElementById('agendaMeetingType')?.value||'Team Buffalos';
  const date=document.getElementById('agendaDate')?.value||'';
  const time=document.getElementById('agendaTime')?.value||'';
  const venue=document.getElementById('agendaVenue')?.value||'Izulu Boardroom';
  const btn=document.getElementById('agendaGenerateBtn');
  if(btn){btn.disabled=true;btn.textContent='Generating…';}
  let dateStr='To be confirmed';
  if(date){const dp=date.split('-');dateStr=dp[2]+'/'+dp[1]+'/'+dp[0];}
  const timeStr=time||'TBC';
  const prompt=`You are creating a professional monthly meeting agenda for the "${meetingType}" team meeting. This is a Sanlam Sky financial advisory team (Izulu region, Eastern Cape) managed by Purshiville Nortje (Key Individual).

Meeting details:
- Meeting: ${meetingType} Monthly Meeting
- Date: ${dateStr}
- Time: ${timeStr}
- Venue: ${venue}

Points and notes gathered this month to discuss:
${notes.map((n,i)=>`${i+1}. ${n}`).join('\n')}

Instructions:
- Group related points under clear section headings (e.g. Production, Team Updates, Compliance, Process, Incentives, Training, Cancellations, Targets)
- Assign realistic time allocations to each section (e.g. 5 min, 10 min, 15 min)
- Start with a welcome / opening, end with action items and next meeting date
- Keep the tone professional but motivational — this team has a buffalo culture (persistent, collective, powerful)
- Format for easy reading at the meeting — use numbered items and clear section breaks
- Return plain text only — no markdown symbols, no asterisks, no hashtags. Use UPPERCASE for section headings.`;
  try{
    const result=await callClaudeVisionMulti([],prompt,2048);
    const out=document.getElementById('agendaOutput');
    const txt=document.getElementById('agendaOutputText');
    if(out)out.style.display='block';
    if(txt)txt.value=result;
    if(out)out.scrollIntoView({behavior:'smooth',block:'start'});
  }catch(e){showAlert('Could not generate agenda — please try again.','error');}
  finally{if(btn){btn.disabled=false;btn.textContent='✨ Generate Agenda';}}
}
function agendaCopyOutput(){
  const txt=document.getElementById('agendaOutputText')?.value||'';
  navigator.clipboard.writeText(txt).then(()=>showAlert('Agenda copied to clipboard','success')).catch(()=>showAlert('Copy failed','error'));
}
function agendaClearOutput(){
  const out=document.getElementById('agendaOutput');
  const txt=document.getElementById('agendaOutputText');
  if(out)out.style.display='none';
  if(txt)txt.value='';
}
function agendaExportPDF(){
  const txt=document.getElementById('agendaOutputText')?.value||'';
  if(!txt.trim())return showAlert('Generate an agenda first.','error');
  logActivity('AGENDA_PDF',(document.getElementById('agendaMeetingType')?.value||'Meeting')+' agenda exported');
  const meetingType=document.getElementById('agendaMeetingType')?.value||'Meeting';
  const date=document.getElementById('agendaDate')?.value||'';
  let dateStr='';
  if(date){const dp=date.split('-');dateStr=dp[2]+'/'+dp[1]+'/'+dp[0];}
  const docTitle=`${meetingType} Agenda${dateStr?' — '+dateStr:''}`;
  const win=window.open('','_blank');
  if(!win)return showAlert('Pop-up blocked — please allow pop-ups and try again.','error');
  win.document.write(`<!DOCTYPE html><html><head><meta charset="UTF-8"><title>${docTitle}</title><style>
    body{font-family:'Helvetica Neue',Arial,sans-serif;font-size:13px;color:#111;margin:40px 50px;line-height:1.8;}
    h1{font-size:17px;font-weight:700;color:#0d1f3c;margin:0 0 4px;}
    .sub{font-size:11px;color:#6b7280;margin-bottom:28px;}
    pre{white-space:pre-wrap;word-wrap:break-word;font-family:inherit;font-size:13px;line-height:1.8;margin:0;}
    @media print{body{margin:20px 30px;}@page{margin:15mm 20mm;}}
  </style></head><body>
    <h1>${docTitle}</h1>
    <div class="sub">Team Buffalos — Sanlam Sky | Generated ${new Date().toLocaleDateString('en-ZA')}</div>
    <pre>${txt.replace(/</g,'&lt;').replace(/>/g,'&gt;')}</pre>
    <script>window.onload=function(){window.print();}<\/script>
  </body></html>`);
  win.document.close();
}
async function agendaScheduleMeeting(){
  const meetingType=document.getElementById('agendaMeetingType')?.value||'Team Buffalos';
  const date=document.getElementById('agendaDate')?.value||'';
  const time=document.getElementById('agendaTime')?.value||'';
  const venue=document.getElementById('agendaVenue')?.value||'Izulu Boardroom';
  if(!date)return showAlert('Please set a meeting date first.','error');
  const dp=date.split('-');
  const dateStr=dp[2]+'/'+dp[1]+'/'+dp[0];
  const timeStr=time||'TBC';
  const venueStr=venue||'Izulu Boardroom';
  const title=`${meetingType} Monthly Meeting`;
  const body=`Date: ${dateStr}\nTime: ${timeStr}\nVenue: ${venueStr}\n\nAll advisors are expected to attend. Please diarise accordingly.`;
  // Post notice to all advisors
  await postNotice('info',title,body,'ALL','');
  // Add to Herd Calendar
  const id='mtg_'+Date.now()+'_'+Math.random().toString(36).slice(2);
  const newEv={id,advisorCode:'ALL',advisorName:'All advisors',title,date,startTime:time||'',endTime:'',type:'meeting',location:venueStr,notes:'Scheduled from Meeting Agenda Builder',status:'confirmed',reminderSent:[]};
  const events=diaryGetEvents();events.push(newEv);diarySaveEvents(events);
  if(window.FB_READY)window.FB.saveCalEvent(id,newEv).catch(()=>{});
  logActivity('CALENDAR_ADD',`Meeting scheduled: "${title}" on ${date}`);
  showAlert(`Meeting scheduled — notice sent to all advisors and added to Herd Calendar.`,'success');
}
// ── PRODUCTION SNAPSHOT ──────────────────────────────────────────────────────
function _snapPeriod(){
  const m=document.getElementById('snapPeriodMonth');
  const y=document.getElementById('snapPeriodYear');
  if(m&&y&&m.value&&y.value)return y.value+'-'+m.value;
  const now=new Date();return now.getFullYear()+'-'+String(now.getMonth()+1).padStart(2,'0');
}
function renderProdSnap(){
  const el=document.getElementById('prodSnapContent');if(!el)return;
  const period=_snapPeriod();
  let raw={advisors:{}};
  // Prefer in-memory stats (Firebase-synced); fall back to localStorage
  if(window._currentPeriodStats&&Object.keys(window._currentPeriodStats.advisors||{}).length&&getStatsPeriod()===period){
    raw=window._currentPeriodStats;
  } else {
    try{raw=JSON.parse(localStorage.getItem('tl_prod_stats_'+period)||'{}');}catch(e){}
  }
  const adData=raw.advisors||{};
  const advisors=ADVISOR_LIST.filter(a=>!REVOKED_CODES.has(a.code));
  const pct=(a,b)=>b?Math.round(a/b*100):0;
  const tl=(p)=>p>=100?'#16a34a':p>=80?'#d97706':'#dc2626';
  const tlBg=(p)=>p>=100?'#dcfce7':p>=80?'#fef3c7':'#fee2e2';
  const ntuCol=(v)=>v<=15?'#16a34a':v<=20?'#d97706':'#dc2626';
  const persCol=(v)=>v>=65?'#16a34a':v>=55?'#d97706':'#dc2626';
  let totC=0,totTC=0,totP=0,totTP=0;
  advisors.forEach(a=>{const d=adData[a.code]||{};totC+=d.actualCases||0;totTC+=d.targetCases||0;totP+=d.actualPremium||0;totTP+=d.targetPremium||0;});
  const teamCP=pct(totC,totTC);const teamPP=pct(totP,totTP);
  const cards=advisors.map(a=>{
    const d=adData[a.code];
    if(!d||(!d.targetCases&&!d.targetPremium))return`<div style="padding:10px 14px;background:#f9fafb;border-radius:12px;border:1px solid #f3f4f6;display:flex;justify-content:space-between;align-items:center;opacity:.5;"><span style="font-size:13px;font-weight:600;color:#0d1f3c;">${a.name}</span><span style="font-size:10px;color:#9ca3af;">No stats</span></div>`;
    const cp=pct(d.actualCases||0,d.targetCases||0);
    const pp=pct(d.actualPremium||0,d.targetPremium||0);
    const overall=Math.round((cp+pp)/2);
    const chip=(label,val,color)=>`<span style="font-size:10px;font-weight:700;padding:2px 7px;border-radius:10px;background:#f3f4f6;color:${color};">${label} ${val}%</span>`;
    const metrics=[
      d.ntu4Month!=null?chip('4M NTU',d.ntu4Month,ntuCol(d.ntu4Month)):'',
      d.ntu15Month!=null?chip('15M NTU',d.ntu15Month,ntuCol(d.ntu15Month)):'',
      d.persistency!=null?chip('Pers',d.persistency,persCol(d.persistency)):''
    ].filter(Boolean).join('');
    return`<div style="padding:12px 14px;background:#fff;border-radius:12px;border:1px solid #e5e7eb;box-shadow:0 1px 3px rgba(0,0,0,.04);">
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:8px;">
        <span style="font-size:13px;font-weight:700;color:#0d1f3c;">${a.name}</span>
        <span style="font-size:10px;font-weight:700;padding:2px 9px;border-radius:20px;background:${tlBg(overall)};color:${tl(overall)};">${overall}%</span>
      </div>
      <div style="margin-bottom:5px;">
        <div style="display:flex;justify-content:space-between;font-size:10px;color:#6b7280;margin-bottom:3px;"><span>Cases</span><span style="font-weight:700;color:${tl(cp)};">${d.actualCases||0} / ${d.targetCases||0}</span></div>
        <div style="height:5px;background:#f3f4f6;border-radius:3px;overflow:hidden;"><div style="height:100%;width:${Math.min(cp,100)}%;background:${tl(cp)};border-radius:3px;"></div></div>
      </div>
      <div style="margin-bottom:6px;">
        <div style="display:flex;justify-content:space-between;font-size:10px;color:#6b7280;margin-bottom:3px;"><span>Monthly Premium</span><span style="font-weight:700;color:${tl(pp)};">R${(d.actualPremium||0).toLocaleString()} / R${(d.targetPremium||0).toLocaleString()}</span></div>
        <div style="height:5px;background:#f3f4f6;border-radius:3px;overflow:hidden;"><div style="height:100%;width:${Math.min(pp,100)}%;background:${tl(pp)};border-radius:3px;"></div></div>
      </div>
      ${metrics?`<div style="display:flex;gap:5px;flex-wrap:wrap;">${metrics}</div>`:''}
    </div>`;
  }).join('');
  el.innerHTML=`
    <div style="background:linear-gradient(135deg,#0c4a6e,#0369a1);border-radius:14px;padding:14px 16px;margin-bottom:12px;">
      <div style="color:#bae6fd;font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.5px;margin-bottom:10px;">Team Total — ${formatPeriodLabel(period)}</div>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:8px;">
        <div>
          <div style="color:rgba(255,255,255,.55);font-size:10px;margin-bottom:2px;">Cases</div>
          <div style="color:#fff;font-size:18px;font-weight:700;line-height:1;">${totC} <span style="font-size:11px;color:rgba(255,255,255,.45);">/ ${totTC}</span></div>
          <div style="font-size:10px;font-weight:700;margin-top:3px;color:${teamCP>=100?'#86efac':teamCP>=80?'#fde68a':'#fca5a5'};">${teamCP}% of target</div>
        </div>
        <div>
          <div style="color:rgba(255,255,255,.55);font-size:10px;margin-bottom:2px;">Monthly Premium</div>
          <div style="color:#fff;font-size:16px;font-weight:700;line-height:1;">R${totP.toLocaleString()} <span style="font-size:10px;color:rgba(255,255,255,.45);">/ R${totTP.toLocaleString()}</span></div>
          <div style="font-size:10px;font-weight:700;margin-top:3px;color:${teamPP>=100?'#86efac':teamPP>=80?'#fde68a':'#fca5a5'};">${teamPP}% · API R${(totP*12).toLocaleString()}</div>
        </div>
      </div>
      <div style="height:6px;background:rgba(255,255,255,.15);border-radius:3px;overflow:hidden;">
        <div style="height:100%;width:${Math.min(Math.round((teamCP+teamPP)/2),100)}%;background:${Math.round((teamCP+teamPP)/2)>=100?'#86efac':Math.round((teamCP+teamPP)/2)>=80?'#fde68a':'#fca5a5'};border-radius:3px;"></div>
      </div>
    </div>
    <div style="display:flex;flex-direction:column;gap:8px;">${cards}</div>`;
}
// ── END MEETING AGENDA BUILDER ────────────────────────────────────────────────

function rgFaqToggle(btn){
  const body=btn.nextElementSibling;
  const arrow=btn.querySelector('span:last-child');
  const open=body.style.display!=='none';
  body.style.display=open?'none':'block';
  if(arrow)arrow.textContent=open?'▾':'▴';
}

// ── FICA / SUBMISSION CHECKLIST ──────────────────────────────────────────────
const _FICA_NB=[
  {id:'f1',text:'Certified copy of client\'s ID document'},
  {id:'f2',text:'Latest payslip (not older than 3 months)'},
  {id:'f3',text:'3-month bank statement'},
  {id:'f4',text:'Signed application form — completed by client'},
  {id:'f5',text:'ROA (Record of Advice) captured in IMP'},
];
const _FICA_REP=[
  ..._FICA_NB,
  {id:'f6',text:'Competitor policy schedule(s) for all policies being cancelled',tag:'Replacement only'},
  {id:'f7',text:'Signed Client Declaration Form — Parts A, B & C',tag:'Replacement only'},
  {id:'f8',text:'ROA with replacement boilerplate text (§3 wording) entered in IMP',tag:'Replacement only'},
];
let _ficaMode='nb';
function ficaSetMode(mode){
  _ficaMode=mode;
  const nb=document.getElementById('ficaTabNB'),rp=document.getElementById('ficaTabRP');
  if(nb){nb.style.background=mode==='nb'?'#0d1f3c':'#f4f2ed';nb.style.color=mode==='nb'?'#f5d98b':'#6b7280';}
  if(rp){rp.style.background=mode==='rep'?'#0d1f3c':'#f4f2ed';rp.style.color=mode==='rep'?'#f5d98b':'#6b7280';}
  ficaRender();
}
function ficaRender(){
  const items=_ficaMode==='rep'?_FICA_REP:_FICA_NB;
  const tot=document.getElementById('ficaTotal');if(tot)tot.textContent=items.length;
  const list=document.getElementById('ficaList');if(!list)return;
  list.innerHTML=items.map((item,i)=>`<label style="display:flex;align-items:flex-start;gap:12px;padding:13px 16px;${i>0?'border-top:1px solid #f4f2ed;':''}cursor:pointer;"><input type="checkbox" id="fc_${item.id}" onchange="ficaUpdate()" style="width:18px;height:18px;cursor:pointer;accent-color:#0d1f3c;flex-shrink:0;margin-top:2px;"><div><div style="font-size:13px;color:#0d1f3c;line-height:1.4;">${item.text}</div>${item.tag?`<div style="font-size:10px;color:#059669;font-weight:700;margin-top:2px;">+ ${item.tag.toUpperCase()}</div>`:''}</div></label>`).join('');
  ficaUpdate();
}
function ficaUpdate(){
  const items=_ficaMode==='rep'?_FICA_REP:_FICA_NB;
  const done=items.filter(item=>{const el=document.getElementById('fc_'+item.id);return el&&el.checked;}).length;
  const doneEl=document.getElementById('ficaDone');if(doneEl)doneEl.textContent=done;
  const prog=document.getElementById('ficaProgress');
  if(prog){const all=done===items.length&&items.length>0;prog.style.background=all?'#dcfce7':'#f4f2ed';prog.style.borderLeft=all?'4px solid #16a34a':'none';prog.style.borderRadius='12px';}
}
function ficaReset(){
  const items=_ficaMode==='rep'?_FICA_REP:_FICA_NB;
  items.forEach(item=>{const el=document.getElementById('fc_'+item.id);if(el)el.checked=false;});
  ficaUpdate();
}
// ── END FICA CHECKLIST ────────────────────────────────────────────────────────

// ── WORKSITE PIPELINE ─────────────────────────────────────────────────────────
const WS_STAGES=['🎯 Identified','👋 Approached','🤝 PIC Met','✅ Access Approved','🔥 Active','💤 Inactive'];
const WS_STAGE_COLORS=['#6b7280','#2563eb','#7c3aed','#d97706','#16a34a','#9ca3af'];
function wsGetAll(){try{return JSON.parse(localStorage.getItem('tl_ws_'+(currentUser?.code||'x'))||'[]');}catch(e){return[];}}
function wsSaveAll(arr){localStorage.setItem('tl_ws_'+(currentUser?.code||'x'),JSON.stringify(arr));}
function wsAdd(){
  const name=(document.getElementById('ws-name')?.value||'').trim();
  const pic=(document.getElementById('ws-pic')?.value||'').trim();
  const phone=(document.getElementById('ws-phone')?.value||'').trim();
  const headcount=parseInt(document.getElementById('ws-headcount')?.value||'0')||0;
  if(!name)return showAlert('Please enter the company name.','error');
  const ws=wsGetAll();
  ws.unshift({id:Date.now()+'_'+Math.random().toString(36).slice(2),name,pic,phone,headcount,stage:0,notes:'',addedAt:new Date().toISOString()});
  wsSaveAll(ws);
  ['ws-name','ws-pic','ws-phone','ws-headcount'].forEach(id=>{const el=document.getElementById(id);if(el)el.value='';});
  renderWorksites();showAlert('Worksite added!','success');
}
function wsUpdateStage(id,stage){
  const ws=wsGetAll();const w=ws.find(x=>x.id===id);
  if(w){w.stage=+stage;wsSaveAll(ws);renderWorksites();}
}
function wsDelete(id){
  if(!confirm('Remove this worksite?'))return;
  wsSaveAll(wsGetAll().filter(x=>x.id!==id));renderWorksites();
}
function wsSaveNotes(id,val){
  const ws=wsGetAll();const w=ws.find(x=>x.id===id);if(w){w.notes=val;wsSaveAll(ws);}
}
function renderWorksites(){
  const ws=wsGetAll();
  const statsEl=document.getElementById('wsStats');
  if(statsEl){
    const active=ws.filter(w=>w.stage===4).length;
    const pipeline=ws.filter(w=>w.stage>=0&&w.stage<=3).length;
    statsEl.innerHTML=[{label:'Total',val:ws.length,col:'#0d1f3c'},{label:'Active',val:active,col:'#16a34a'},{label:'In Pipeline',val:pipeline,col:'#d97706'}].map(s=>`<div style="background:#fff;border:1px solid #e8e4db;border-radius:12px;padding:12px;text-align:center;"><div style="font-size:22px;font-weight:800;color:${s.col};">${s.val}</div><div style="font-size:10px;color:#9ca3af;font-weight:700;text-transform:uppercase;letter-spacing:.5px;">${s.label}</div></div>`).join('');
  }
  const el=document.getElementById('wsList');if(!el)return;
  if(!ws.length){el.innerHTML='<div style="text-align:center;color:#9ca3af;font-size:13px;padding:2rem;background:#f9fafb;border-radius:12px;border:1px dashed #e5e7eb;">No worksites added yet — add your first commercial worksite above.</div>';return;}
  el.innerHTML=ws.map(w=>{
    const sc=WS_STAGE_COLORS[w.stage]||'#6b7280';
    const dateStr=new Date(w.addedAt).toLocaleDateString('en-ZA',{day:'numeric',month:'short'});
    return`<div class="full-card" style="margin-bottom:10px;padding:0;overflow:hidden;"><div style="padding:12px 14px;"><div style="display:flex;align-items:flex-start;justify-content:space-between;gap:8px;margin-bottom:8px;"><div style="min-width:0;"><div style="font-size:14px;font-weight:700;color:#0d1f3c;">${w.name}</div>${w.pic?`<div style="font-size:11px;color:#6b7280;margin-top:2px;">👤 ${w.pic}${w.phone?` · <a href="tel:${w.phone}" style="color:#c9922a;text-decoration:none;">${w.phone}</a>`:''}</div>`:''} ${w.headcount?`<div style="font-size:11px;color:#6b7280;margin-top:1px;">👥 ~${w.headcount} employees</div>`:''}<div style="font-size:10px;color:#9ca3af;margin-top:2px;">Added ${dateStr}</div></div><button onclick="wsDelete('${w.id}')" style="background:none;border:none;color:#d1d5db;cursor:pointer;font-size:18px;flex-shrink:0;padding:0;">✕</button></div><select onchange="wsUpdateStage('${w.id}',this.value)" style="font-size:12px;font-weight:700;border:1.5px solid ${sc};border-radius:8px;padding:5px 8px;color:${sc};background:#f9fafb;cursor:pointer;margin-bottom:8px;width:100%;">${WS_STAGES.map((s,i)=>`<option value="${i}" ${w.stage===i?'selected':''}>${s}</option>`).join('')}</select><input type="text" placeholder="Notes — PIC contact, access terms, best days to visit..." value="${(w.notes||'').replace(/"/g,'&quot;')}" onblur="wsSaveNotes('${w.id}',this.value)" style="width:100%;font-size:12px;border:1px solid #e5e7eb;border-radius:8px;padding:6px 10px;box-sizing:border-box;color:#374151;background:#f9fafb;"></div></div>`;
  }).join('');
}
// ── END WORKSITE PIPELINE ─────────────────────────────────────────────────────

// ── HUB TOUR ────────────────────────────────────────────────────────────────
let _tourIdx=0,_tourActive=false,_tourSteps=[];
const TOUR_STEPS=[
  // ── Introduction ────────────────────────────────────────────────────────────────
  {page:'hub',target:null,title:'Welcome to the Hub Tour 🦬',text:'This tour follows the exact process you use to find clients, run appointments, and get paid — in the right order. 7 phases covering every tool. Tap Next to start, or Skip any time.',pos:'center',phase:'Introduction'},
  // ── Phase 1 — Know Your Obligations ────────────────────────────────────────────
  {page:'standard',target:'#stdBufHero',title:'The Standard — Your Minimum',text:'Before anything else, know the rules. The Standard sets minimum production, attendance expectations, and the consequences for falling short. Read this and own it.',pos:'bottom',phase:'Phase 1 of 7 — Know Your Obligations'},
  {page:'fitproper',target:'#fpRingCircle',title:'Fit & Proper — Stay Compliant',text:'Your compliance ring tracks RE5, qualifications, CPD hours, PST per product, COB modules, and FAIS registration. You cannot legally give advice without meeting these. Keep the ring at 100% at all times.',pos:'bottom',phase:'Phase 1 of 7 — Know Your Obligations'},
  {page:'hub',target:'#aiFab',title:'Need Answers — Your First Call When Stuck',text:"Ask anything — product rules, compliance questions, how a tool works. But it goes further: say \"book an appointment with [name] on [date]\" and it adds it to your Herd Calendar; say \"add [name] as a referral from [client]\" and it logs it in your Referral Tracker; say \"take me to the ROA tool\" and it navigates straight there. Available 24/7 — voice, text, or photo.",pos:'top',phase:'Phase 1 of 7 — Know Your Obligations'},
  // ── Phase 2 — Learn the Playbook ───────────────────────────────────────────────
  {page:'guides',target:'#mainGuideCard',title:'The Guide — Read This First',text:'Open before your first appointment. The Guide covers your full business model, commission structure, Sanlam Sky product range, compliance rules, and a complete 12-step process for getting paid. Bookmark it now — you will come back to it every week.',pos:'bottom',phase:'Phase 2 of 7 — Learn the Playbook'},
  {page:'guides',target:'#mainGuideCard',title:'§01–02 — Your Business & Commission',text:'Section 01 covers the 3 departments of your business (Sales, Admin, Lapse Management — 33% each) and your minimum monthly target: 15 cases and R8,000 in risk premiums. Section 02 breaks down commission rates, the first-year advance formula, clawback timelines, and the monthly cut-off schedule.',pos:'bottom',phase:'Phase 2 of 7 — Learn the Playbook'},
  {page:'guides',target:'#mainGuideCard',title:'§06 — Know Your Products',text:'Section 06 covers the full Sanlam Sky product range: Value Funeral Plan, Enhanced Priority, All-in-One, Immediate Life Cover, and Essential Med. Includes cross-selling strategy and replacement restrictions. You cannot advise on a product you have not studied.',pos:'bottom',phase:'Phase 2 of 7 — Learn the Playbook'},
  {page:'guides',target:'#mainGuideCard',title:'§07 — The 12 Steps to Getting Paid',text:'The most important chapter. It maps the complete sales cycle: Map your area → Visit the facility → Meet the PIC → Confirm → Follow up → Present → Collect LOAs → Get schedules → Portfolio review → Close & submit → Capture on Connect Me → Initiate cancellations. The rest of this tour follows that exact sequence.',pos:'bottom',phase:'Phase 2 of 7 — Learn the Playbook'},
  {page:'replpresentation',target:'#replSlideContainer',title:'Client Prospect Presentation — Rehearse Before You Go',text:"A slide-by-slide deck built from The Guide's scripts. Slide 1 opens the conversation, Slide 8 closes it. Go through this before your first group appointment to rehearse exactly what to say at each step.",pos:'bottom',phase:'Phase 2 of 7 — Learn the Playbook'},
  // ── Phase 3 — Daily Starting Point ─────────────────────────────────────────────
  {page:'hub',target:'#hubRemindersSection',title:'Home — Your Daily Brief',text:'Every morning starts here. Production cut-off countdown, next QLink run date, pre-cancellation alerts, and personal reminders. Only shows what needs your attention today — nothing clutter.',pos:'bottom',phase:'Phase 3 of 7 — Daily Starting Point'},
  {page:'hub',target:'#noticeBoardSection',title:'Notice Board — Stay Informed',text:"Manager posts here when something important happens: QLink runs, pre-can deadlines, team updates. Amber means unread. You'll also receive these in your Inbox so nothing slips through.",pos:'bottom',phase:'Phase 3 of 7 — Daily Starting Point'},
  {page:'hub',target:'#bdayManagerHubSection',title:'Team Birthdays',text:'Any team member with a birthday in the next 7 days gets a card here. Visible to all advisors. A quick message goes a long way.',pos:'bottom',phase:'Phase 3 of 7 — Daily Starting Point'},
  {page:'hub',target:'#inboxBtn',title:'Inbox — Your Messages',text:'All notices sent to you land here. The Unread tab shows new messages highlighted in amber. Tap any item to read it. Tap the bell icon in the top bar to open your inbox from anywhere on the hub.',pos:'bottom',phase:'Phase 3 of 7 — Daily Starting Point'},
  {page:'hub',target:'#hubTop3',title:'Advisors of the Month — Previous Period',text:"Top 3 advisors by premium for the previous completed production month, plus your own card showing your cases and premium vs target for the current period. Use this every morning to know where you stand and who to benchmark against.",pos:'bottom',phase:'Phase 3 of 7 — Daily Starting Point'},
  {page:'opsland',target:'#page-opsland',title:'Operations — Manager Command Centre',text:'Daily command centre: pre-cancellation management, insurer portals, team management tools, and meeting minutes. Start every management day here before doing anything else.',pos:'bottom',phase:'Phase 3 of 7 — Daily Starting Point',managerOnly:true},
  {page:'dailyops',target:'#page-dailyops',title:'Notices & WhatsApp Templates',text:'Post notices to the whole team or a specific advisor. QLink type auto-fills the Connect Me link; Pre-Cancellations auto-fills the Pavlov report. WhatsApp Templates has 10+ pre-written client messages ready to send.',pos:'bottom',phase:'Phase 3 of 7 — Daily Starting Point',managerOnly:true},
  // ── Phase 4 — Find Business ─────────────────────────────────────────────────────
  {page:'prospectmap',target:'#page-prospectmap',title:'Prospect Map — Track Your Facilities',text:'Map every facility where you prospect. Record the contact person, headcount, and access notes. Plan your week by facility: who to see, what the opportunity is, and how to get access.',pos:'bottom',phase:'Phase 4 of 7 — Find Business'},
  {page:'referrals',target:'#page-referrals',title:'Referral Tracker — 1 Name = 2 Names',text:'Every client you see must give you 2 referrals before you leave. Log them here with name, phone number, facility, and relationship to the referring client. This is your pipeline between appointments.',pos:'bottom',phase:'Phase 4 of 7 — Find Business'},
  {page:'referrals',target:'#refList',title:'Referral Pipeline — Work Your List',text:'Referrals grouped by the client who gave them. Update the status (Pipeline → Contacted → Converted → Lost) and log every contact attempt with date, time, and notes. A referral not followed up is a case lost.',pos:'top',phase:'Phase 4 of 7 — Find Business'},
  {page:'worksites',target:'#wsList',title:'Worksite Pipeline — Commercial Employers',text:'Log every company or employer you approach for group access. Move them through 6 stages from Identified → Approached → PIC Met → Access Approved → Active → Inactive. PIC name, phone, headcount, and notes stored per worksite — your entire commercial pipeline at a glance.',pos:'bottom',phase:'Phase 4 of 7 — Find Business'},
  {page:'termcal',target:'#page-termcal',title:'Herd Strategy — Your Field Diary',text:'Book and manage appointments with date, start time, and end time. Your manager reviews team diaries to plan the week and identify gaps. A full diary means a full pipeline.',pos:'bottom',phase:'Phase 4 of 7 — Find Business'},
  // ── Phase 5 — In the Appointment ───────────────────────────────────────────────
  {page:'policyreview',target:'#page-policyreview',title:'Policy Summary — Read the Existing Policy',text:"Upload the client's competitor policy schedule and the AI extracts every life, cover amount, premium, and benefit. Use this before every replacement to spot gaps, data errors, and over/under-coverage before you quote.",pos:'bottom',phase:'Phase 5 of 7 — In the Appointment'},
  {page:'unlockpdf',target:'#page-unlockpdf',title:'Unlock PDF — Remove the Password First',text:'Competitor policy schedules often arrive password-protected. Unlock them here before running Policy Summary AI or packing for IMP submission. Supports multiple files at once — each with its own password.',pos:'bottom',phase:'Phase 5 of 7 — In the Appointment'},
  {page:'qlink',target:'#page-qlink',title:'QLink Calculator — Check the 15% Bracket',text:"For every Persal client, enter their Basic Salary and all existing stop order deductions. Shows exactly how much QLink space is available within the statutory 15% cap. Run this before quoting — never guess the space.",pos:'bottom',phase:'Phase 5 of 7 — In the Appointment'},
  {page:'roa',target:'#roaBtnNew',title:'ROA Tool — New Business',text:'For first-time Sanlam Sky policies. Enter client name, plan, lives, and cover amounts. Generates the §3 boilerplate ROA text with all disclosures filled in. Copy directly into IMP — no typing from scratch.',pos:'bottom',phase:'Phase 5 of 7 — In the Appointment'},
  {page:'roa',target:'#roaBtnRep',title:'ROA Tool — Replacement',text:'For cases where a client cancels an existing policy. Select the reason, fill in cancelled and new policies. Handles all waiting period scenarios (waived, 6-month, residual carry-over) and includes the "benefits may differ" disclosure.',pos:'bottom',phase:'Phase 5 of 7 — In the Appointment'},
  // ── Phase 6 — Pack & Submit ────────────────────────────────────────────────────
  {page:'fica',target:'#ficaList',title:'FICA Checklist — Before You Pack',text:"Run through this before submitting any case. New Business needs 5 documents; Replacement needs 8. Tick each off as you pack the file. The bar turns green when all items are confirmed — that's your signal you're clear to submit.",pos:'bottom',phase:'Phase 6 of 7 — Pack & Submit'},
  {page:'canpack',target:'#page-canpack',title:'Merge Docs — Build the IMP Pack',text:'Combine your signed declaration form, ROA, and policy schedule into a single PDF for IMP submission. This is the §8 file checklist in practice. Auto-compresses to stay within the 4MB IMP limit.',pos:'bottom',phase:'Phase 6 of 7 — Pack & Submit'},
  {page:'cancellations',target:'#page-cancellations',title:'Cancellations — Know the Right Form',text:"When a pre-cancellation appears on your name, find the insurer here. Each shows exactly what's required: AL9 form, own form, or own letter. Capital Legacy has its own section — never use the standard IMP letter for them.",pos:'bottom',phase:'Phase 6 of 7 — Pack & Submit'},
  {page:'replform',target:'#page-replform',title:'Replacement Form — Full Digital Case Capture',text:'Capture the complete replacement case digitally: client info, competitor insurer, cover amounts, insurable interest, affordability declaration, and digital signatures from both advisor and client. Exports a compliant PDF.',pos:'bottom',phase:'Phase 6 of 7 — Pack & Submit',managerOnly:true},
  {page:'appchecks',target:'#page-appchecks',title:'App Checks — Track the Case to Paid',text:'Track submitted cases from Pending Approval through Spotcheck to Approved. Log all policies per case and monitor each through the pipeline. This is how you know a case is progressing and when commission will run.',pos:'bottom',phase:'Phase 6 of 7 — Pack & Submit',managerOnly:true},
  // ── Phase 7 — Support & Resources ─────────────────────────────────────────────
  {page:'guides',target:'#page-guides',title:'Resources & Training — Everything in One Place',text:'All reference material: Product Resources (guides and forms in Drive), The Guide (full FSP guide), Smart Replacement Training Guide, and the Client Prospect Presentation.',pos:'bottom',phase:'Phase 7 of 7 — Support & Resources'},
  {page:'directory',target:'#page-directory',title:'Directory — Every Contact You Need',text:"Search for any team member, insurer cancellation number, or FSP email instantly. Tap a phone number to call. Insurer portals for all major providers listed — Sanlam Sky, AVBOB, Old Mutual, and more.",pos:'bottom',phase:'Phase 7 of 7 — Support & Resources'},
  {page:'team',target:'#userTableBody',title:'Team Page — Advisor Roster',text:'All advisors with DOFA, birthday, compliance status, last seen, and time on site today. Green = 1h+ active, amber = 10m+, grey = inactive. Live view refreshed every 30 seconds.',pos:'top',phase:'Phase 7 of 7 — Support & Resources',managerOnly:true},
  {page:'activity',target:'#actToolLeaderboard',title:'Activity Log — Live Team Engagement',text:'See who is online now, who was active today, and which tools each advisor has used. The engagement table and tool leaderboard give a real-time picture of how the team is using the hub.',pos:'bottom',phase:'Phase 7 of 7 — Support & Resources',managerOnly:true},
  // ── Final ──────────────────────────────────────────────────────────────────────
  {page:'hub',target:'#aiFab',title:"You're All Set! 🎉",text:"You've now seen the full process — from knowing the rules, to finding clients, running appointments, and submitting cases. Whenever you're stuck at any step, tap Need Answers and ask. Welcome to the herd!",pos:'top',phase:'You\'re ready 🦬'},
];

function startTour(){
  const isMgr=currentUser&&(currentUser.isManager||currentUser.isOps);
  _tourSteps=TOUR_STEPS.filter(s=>!s.managerOnly||isMgr);
  _tourActive=true;_tourIdx=0;
  document.getElementById('tourSpotlight').style.display='block';
  document.getElementById('tourCallout').style.display='block';
  _tourShowStep(0);
}
function tourNext(){if(_tourIdx<_tourSteps.length-1){_tourIdx++;_tourShowStep(_tourIdx);}else tourEnd();}
function tourBack(){if(_tourIdx>0){_tourIdx--;_tourShowStep(_tourIdx);}}
function tourEnd(){
  _tourActive=false;
  document.getElementById('tourSpotlight').style.display='none';
  document.getElementById('tourCallout').style.display='none';
}
function _tourShowStep(idx){
  const step=_tourSteps[idx],total=_tourSteps.length;
  document.getElementById('tourStepLabel').textContent=step.phase?step.phase+' · '+(idx+1)+' / '+total:'Step '+(idx+1)+' of '+total;
  document.getElementById('tourTitle').textContent=step.title;
  document.getElementById('tourText').textContent=step.text;
  const backBtn=document.getElementById('tourBackBtn'),nextBtn=document.getElementById('tourNextBtn');
  backBtn.style.display=idx>0?'':'none';
  if(idx===total-1){nextBtn.className='tc-finish';nextBtn.textContent='🎉 Done';}
  else{nextBtn.className='tc-next';nextBtn.textContent='Next →';}
  const cur=document.querySelector('.page.active');
  const curId=cur?cur.id.replace('page-',''):'';
  const doPos=()=>{
    if(!step.target||step.pos==='center'){
      document.getElementById('tourSpotlight').style.display='none';
      _tourCenterCallout();return;
    }
    const el=document.querySelector(step.target);
    if(!el||(!el.offsetWidth&&!el.offsetHeight)){
      document.getElementById('tourSpotlight').style.display='none';
      _tourCenterCallout();return;
    }
    el.scrollIntoView({behavior:'smooth',block:'center'});
    setTimeout(()=>{
      const rect=el.getBoundingClientRect(),p=8;
      const sp=document.getElementById('tourSpotlight');
      sp.style.display='block';
      sp.style.left=(rect.left-p)+'px';sp.style.top=(rect.top-p)+'px';
      sp.style.width=(rect.width+p*2)+'px';sp.style.height=(rect.height+p*2)+'px';
      _tourPosCallout(rect,step.pos);
    },200);
  };
  if(step.page&&step.page!==curId){showPage(step.page);setTimeout(doPos,340);}
  else setTimeout(doPos,80);
}
function _tourCenterCallout(){
  const cl=document.getElementById('tourCallout');
  const cw=Math.min(300,window.innerWidth-28);
  cl.style.maxWidth=cw+'px';
  const ch=cl.offsetHeight||220;
  cl.style.left=Math.round((window.innerWidth-cw)/2)+'px';
  cl.style.top=Math.max(70,Math.round((window.innerHeight-ch)/2))+'px';
}
function _tourPosCallout(rect,pos){
  const cl=document.getElementById('tourCallout');
  const cw=Math.min(300,window.innerWidth-24),gap=14;
  const vw=window.innerWidth,vh=window.innerHeight;
  cl.style.maxWidth=cw+'px';
  const ch=cl.offsetHeight||220;
  let left=Math.round(rect.left+rect.width/2-cw/2);
  let top;
  if(pos==='top'||(rect.bottom+gap+ch>vh)){top=Math.round(rect.top-gap-ch);}
  else{top=Math.round(rect.bottom+gap);}
  left=Math.max(12,Math.min(left,vw-cw-12));
  top=Math.max(60,Math.min(top,vh-ch-10));
  cl.style.left=left+'px';cl.style.top=top+'px';
}
// ── END HUB TOUR ─────────────────────────────────────────────────────────────
